(window.GIM_TS=window.GIM_TS||{})["Yoma.5"]={"from":120,"a":[["\u0003וכי עדרו שורף?\u0004 שהרי לא חייבה התורה לשרוף אלא אחד, ומכל מקום פעמים שצריכים לשרוף שעירים הרבה, כפי ששנינו במשנה! קושיה זו דחה ר' נחמן: \u0003מי דמי\u0004 \u0005[וכי דומה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בענין שריפת השעירים \u0003לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"אתו\"\u0004 למעט ולומר שאין שורפים אלא אחד, אבל \u0003הכא\u0004 \u0005[כאן]\u0006 בשעיר המשתלח \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"אתו\",\u0004 ומשמע: \"אותו\" — לבדו, רק אחד. בעיה זו נפתרה איפוא, שאכן אינו משלח אלא רק אחד מן השעירים.","אולם בעקבותיה \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בדבר, \u0003רב פפי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר: ראשון\u0004 שבהם \u0003משלח, ורב שימי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר: אחרון\u0004 שבהם \u0003משלח.\u0004 ודנין בדבר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003רב שימי\u0004 משמו של \u0003רבא,\u0004 ש\u0003אמר: אחרון\u0004 שבהם \u0003משלח,\u0004 אפשר להניח כי \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 כנימוק שאמרנו: \u0003הואיל וגמר בו כפרה. אלא רב פפי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא, מאי קסבר\u0004 \u0005[מה סבר]\u0006 מה טעמו? ומשיבים: \u0003סבר לה\u0004 \u0005[סבור היה]\u0006 בענין זה כדעת \u0003ר' יוסי\u0004 ש\u0003אמר\u0004 שכאשר יש כמה דברים שווים שעומדים לעשות בהם מצוה — \u0003מצוה בראשון\u0004 שבהם.","ושואלים: \u0003הי\u0004 \u0005[איזה]\u0006 \u0003ר' יוסי?\u0004 כלומר: מאיזה מדברי ר' יוסי מסיקים מסקנה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ר' יוסי\u0004 שאמר בענין \u0003קופות.\u0004 שכן שנינו במשנה: \u0003ר' יוסי אומר: שלש קופות של שלש שלש סאין\u0004 היו \u0003שבהם\u0004 היו \u0003תורמין את הלשכה.\u0004 שהיו מכניסים בלישכה את השקלים שנדבו כל העם לצורך עבודת המקדש בחודש אדר בכל שנה והיו הגזברים ממלאים מהם שלוש קופות של מטבעות והיו קונים בהם את קרבנות הציבור (כגון תמידים ומוספים), \u0003והיה כתוב עליהם אל\"ף בי\"ת גימ\"ל\u0004","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר ר' יוסי: למה כתוב עליהן אלף בית גימל\u0004 — כדי \u0003לידע איזה מהן נתרמה ראשון, להביא הימנה ראשון,\u0004 כי \u0003מצוה בראשון.\u0004","אולם משם אין ראיה \u0003דילמא בעידנא דאיתחזאי קמיתא לא איתחזאי בתרייתא\u0004 \u0005[בזמן שהיתה הראשונה ראויה לא היתה ראויה האחרונה],\u0006 שהרי כאשר הביא את הקופה הראשונה כבר נעשית הראשונה ראויה לקרבנות ומיועדת להם, ואילו השניה עדיין לא נתרמה, ולכן חלה הקדושה על הראשונה תחילה. אולם כאן הרי קדושה חלה על השעיר המשתלח רק עם הקרבת השעיר השני, ואם כן אין הדברים דומים זה לזה לגמרי.","\u0003אלא\u0004 למדו את הדבר מדברי \u0003ר' יוסי\u0004 בענין פסחים. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המפריש\u0004 שה ל\u0003פסחו ואבד\u0004 השה, \u0003והפריש\u0004 שה\u0003אחר תחתיו, ואחר כך נמצא הראשון, והרי שניהן עומדין\u0004 לפניו — \u0003אי זה מהן שירצה יקריב, דברי חכמים. ר' יוסי אומר: מצוה בראשון. ואם היה\u0004 ה\u0003שני מובחר ממנו — יביאנו.\u0004 הרי ששיטת ר' יוסי שבכל מקום שיש שני קרבנות ששניהם ראויים להקרבה — מביאים את זה שנבחר ראשון.","","\u0003שני שעירי יום הכפורים\u0004 השעיר לה' והשעיר לעזאזל שמביאין כזוג — \u0003מצותן\u0004 לכתחילה \u0003שיהיו שניהן שוין במראה\u0004 (בצבעם) \u0003ובקומה\u0004 (בגודל) \u0003ובדמים\u0004 (במחיר) \u0003ובלקיחתן כאחד\u0004 שיקנו את שניהם יחד. אולם \u0003ואף על פי שאין שוין — כשרין,\u0004 וכן אם \u0003לקח אחד היום ואחד למחר — כשרין.\u0004","\u0003מת אחד\u0004 מן השעירים, \u0003אם עד שלא הגריל\u0004 ביניהם \u0003מת — יקח\u0004 מיד בן \u0003זוג לשני\u0004 שהרי עדיין לא הוברר אחד מהן. \u0003ואם משהגריל מת — יביא זוג אחר\u0004 של שעירים \u0003ויגריל עליהם בתחילה,\u0004 ולאחר ההגרלה \u0003יאמר\u0004 בלשון תנאי: \u0003אם של שם מת — זה שעלה עליו הגורל לשם יתקיים\u0004 (יעמוד) \u0003תחתיו, ואם של עזאזל מת — זה שעלה עליו הגורל לעזאזל יתקיים תחתיו, והשני\u0004 שהוא בן הזוג ואין זקוקים לו \u0003ירעה עד שיסתאב\u0004 (שיפול בו מום) \u0003וימכר, ויפלו דמיו\u0004 לקרבן \u0003נדבה.\u0004 ואף שבחטאת יחיד כגון זו לא היתה תקנה לקרבן והיו מניחים לו למות, כאן אין עושים כן, לפי שזו נחשבת כחטאת הציבור וכלל בידינו \u0003שאין חטאת צבור מתה,\u0004 ואילו \u0003ר' יהודה אומר:\u0004 במקרה כזה \u0003תמות.\u0004 \u0003ועוד אמר ר' יהודה:\u0004 אם \u0003נשפך הדם\u0004 של השעיר הפנימי לפני שהיזו ממנו — \u0003ימות המשתלח\u0004 וכן אם \u0003מת המשתלח — ישפך הדם\u0004 של השעיר הפנימי ויביאו שעירים נוספים ויגרילו עליהם מתחילה.","",""],["\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \u0003\"יקח שני שעירי עזים\"\u0004 (ויקרא טז, ה), \u0003מיעוט \"שעירי\" — שנים\u0004 שכן מיעוט לשון רבים שלא נתפרש מניינה הריהי שנים. אם כן \u0003מה תלמוד לומר: \"שני\"\u0004 — ללמד \u0003שיהיו שניהן שוים.\u0004 ו\u0003מניין\u0004 ש\u0003אף על פי שאין שניהן שוין כשירין\u0004 להקרבה — \u0003תלמוד לומר: \"שעיר\" \"שעיר\"\u0004 האמור בפרשה זו כמה פעמים — \u0003ריבה,\u0004 שבדיעבד אין דבר זה מעכב.","ושואלים: \u0003טעמא דרבי רחמנא\u0004 \u0005[הטעם,\u0006 דווקא, משום \u0005שריבה הכתוב]\u0006 ללמדנו שכשרים, \u0003הא לא רבי רחמנא\u0004 \u0005[הרי אם לא היה מרבהו הכתוב]\u0006 \u0003— הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 ש\u0003פסולין\u0004 הם. ויש לשאול: \u0003עיכובא מנלן\u0004 \u0005[עיכוב מניין לנו]\u0006 שהם מעכבים ופסולים? שהרי בקדשים לא די שנאמר כתוב אחד למצוה, אלא יש צורך להדגיש שכל שינוי מעכב!","ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[\u0006היה \u0005עולה על דעתך לומר]\u0006 \u0003\"שני\" \"שני\" \"שני\" כתיב\u0004 \u0005[נאמר]\u0006 שלוש פעמים, וחזרה זו לא באה אלא כדי לומר שמעכב, ולכן היה צורך בריבוי מיוחד להתיר.","ושואלים: \u0003והשתא דרבי רחמנא\u0004 \u0005[ועכשיו שריבה הכתוב]\u0006 \u0003\"שעיר\" \"שעיר\"\u0004 לומר: אם כן אותה חזרה שלוש פעמים שאמר: \u0003\"שני\" \"שני\" \"שני\", למה לי?\u0004 ומשיבים: בא הדבר ללמד לדרך עשייתם לכתחילה, \u0003חד\u0004 \u0005[אחד]\u0006 מהן שיהיו שווין \u0003למראה, וחד\u0004 \u0005[ואחד]\u0006 לענין שויון \u0003לקומה, וחד\u0004 \u0005[ואחד]\u0006 לגבי שיהיו שוים ב\u0003דמים.\u0004","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 ל\u0003גבי כבשי מצורע,\u0004 שנאמר שם: \u0003\"יקח שני כבשים\"\u0004 (ויקרא יד, י) והלא \u0003מיעוט \"כבשים\" — שנים,\u0004 ו\u0003מה תלמוד לומר \"שני\"?\u0004 אלא ודאי בא ללמד \u0003שיהיו שניהן שוין. ומנין שאף על פי שאין שניהן שוין כשירין\u0004 בדיעבד — \u0003תלמוד לומר: \"כבש\", \"כבש\" — ריבה\u0004 הכתוב שאף שאינן שווים, אין הדבר מעכב בדיעבד.","ומבררים באותו אופן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003דרבי רחמנא\u0004 \u0005[שריבתה התורה]\u0006 \u0003הא לא רבי רחמנא\u0004 \u0005[הרי אם לא היתה מרבה התורה] —\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שהם \u0003פסולין\u0004 ואף שם \u0003עיכובא מנא לן\u0004 \u0005[לעכב מניין לנו]?\u0006 ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \"זאת \u0003תהיה\u0004 תורת המצורע\" (ויקרא יד, ב) \u0003כתיב\u0004 \u0005[נאמר ויקרא יד, ב]\u0006 והכוונה להדגיש: שכל פרט האמור בו חייב להיעשות בדיוק כמו שנאמר, לכן היה צורך בריבוי להתיר.","ושואלים: \u0003והשתא דרבי רחמנא\u0004 \u0005[ועכשיו שריבתה התורה]\u0006 מהאמור \u0003\"כבש\", \"כבש\",\u0004 ההדגשה \u0003\"תהיה\" למה לי?\u0004 ומשיבים: \u0003לשאר הויתו של מצורע\u0004 ששאר הדינים האמורים במצורע, אם שינה בהם — מעכב.","\u0003ותנן נמי\u0004 \u0005[ושנינו גם כן]\u0006 ל\u0003גבי\u0004 צפורי \u0003מצורע כי האי גוונא\u0004 \u0005[מעין זה].\u0006 נאמר: \u0003\"\u0004שתי \u0003צפרים\"\u0004 (ויקרא יד, ד), \u0003מיעוט \"צפרים\" — שנים, מה תלמוד לומר \"שתי\"\u0004 — ללמד \u0003שיהיו שתיהן שוות. ומנין שאף על פי שאינן שוות כשרות — תלמוד לומר: \"צפר\" \"צפר\" — ריבה.\u0004","ומבררים: \u0003טעמא דרבי רחמנא\u0004 \u0005[הטעם,\u0006 דווקא, \u0005שריבהו הכתוב],\u0006 \u0003הא לא רבי רחמנא\u0004 \u0005[הרי אם לא היה מרבהו הכתוב],\u0006 — \u0005היו\u0006 \u0003פסולות\u0004 ונשאל: \u0003עכובא מנא לן\u0004 \u0005[לעכב מניין לנו]?\u0006 ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003\"תהיה\" כתיב\u0004 \u0005[נאמר]\u0006 ומשמעו לעכב, ולכן יש צורך בריבוי מיוחד כדי להתיר.","ושואלים: \u0003והשתא דרבי רחמנא\u0004 \u0005[ועכשיו שרבתה התורה]\u0006 על ידי האמור \u0003\"צפר\",\u0004 אם כן \u0003\"תהיה\" למה לי?\u0004 ומשיבים: \u0003לשאר הויתו של מצורע,\u0004 ללמד ששאר הפרטים בדיני המצורע לעיכוב נאמרו.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 לפי דרך לימוד זו, הרי בקרבנות ה\u0003תמידין נמי\u0004 \u0005[גם כן]\u0006 \u0003נימא\u0004 \u0005[נאמר]:\u0006 \u0003\"כבשים\u0004 בני שנה שנים ליום תמיד\u0003\"\u0004 (שמות כט, לח), \u0003מיעוט \"כבשים\" — שנים,\u0004 ו\u0003מה תלמוד לומר \"שנים\"\u0004 (שמות כט, לח) — \u0003שיהיו שניהן שוין. ומנין שאף על פי שאין שניהן שוין כשירין — תלמוד לומר: \"כבש\" \"כבש\" ריבה.\u0004 ושואלים: אם כן, נלמד מכאן כי \u0003למצוה\u0004 על כל פנים \u0003הכי נמי דבעינן\u0004 \u0005[כך גם צריכים אנו]\u0006 שיהיו שניהן שווין, ומדוע לא שנינו בשום מקום הלכה זו?","ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 שנאמר בו \"שנים\" — \u0003מיבעי ליה לכדתניא\u0004 \u0005[נצרך לו לכפי ששנינו\u0006 בברייתא אחרת\u0005]\u0006 כי מה שנאמר: \u0003\"שנים ליום\"\u0004 (שמות כט, לח), כוונתו: \u0003כנגד היום,\u0004 ששוחטים אותם במקום מסויים, מול, ובכיוון הפוך, מהשמש באותה שעה.","ושואלים: \u0003אתה אומר\u0004 שהכוונה היא \u0003כנגד היום, או אינו אלא\u0004 כפשוטו שנים \u0003לחובת היום?\u0004 ומשיבים: \u0003כשהוא אומר \"את הכבש אחד תעשה בבקר ואת הכבש השני תעשה בין הערבים\"\u0004 (במדבר כח, ד), \u0003הרי חובת היום אמור\u0004 במפורש, \u0003ומה\u0004 אם כן \u0003אני מקיים\u0004 להבין את האמור \u0003\"שנים ליום\"\u0004 \u0005—\u0006 ללמד שיקריבום \u0003כנגד היום.\u0004","\u0003כיצד\u0004 נעשה הדבר בפועל? — \u0003תמיד של שחר היה נשחט על קרן צפונית מערבית, על טבעת שניה\u0004 מן הטבעות שהיו שם להחזיק את הקרבנות, שהוא בדיוק מול היום שהשמש זורחת מצד מזרחית דרומית. ותמיד \u0003של בין הערבים היה נשחט על קרן מזרחית צפונית, על טבעת שניה\u0004 ואף הוא כנגד היום.","ומעירים: ואילו \u0003מוספין של שבת,\u0004 שאף בהם נאמר \"שני כבשים\" — \u0003ודאי צריכין שיהיו שניהן שוין\u0004 לכתחילה, שנלמד מן המילה \"שנים\" הכתובה בהם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שני שעירי יום הכפורים ששחטן בחוץ\u0004 מתי יהא חייב כרת על שחיטה זו משום הקרבת קרבנות בחוץ? \u0003עד שלא הגריל עליהן\u0004 ולא נקבע איזה שעיר לה' ואיזה לעזאזל — \u0003חייב על שניהם,\u0004 שהרי שניהם ראוים להיות קרבן. \u0003משהגריל עליהן — חייב על של שם\u0004 שהרי הוא קרבן, \u0003ופטור על של עזאזל\u0004 שכן איננו קרבן.","את הברייתא הזו מבררים. שנינו: \u0003עד שלא הגריל עליהן — חייב על שניהם.\u0004 ושואלים: \u0003למאי חזו\u0004 \u0005[למה הם ראויים],\u0006 שהרי קודם הגרלה לכאורה אינם ראוים עדיין לכל קרבן, ומדוע איפוא יתחייבו עליהם? ומשיבים: \u0003אמר רב חסדא: הואיל וראוי לשעיר הנעשה בחוץ,\u0004 שהרי שני שעירים אלה ראוים להיות קרבן ביום הכיפורים לצורך שעירי המוספים, על כן דינם כקרבנות לכל דבר.","ושואלים עוד: אם כן \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 שאתה אומר ש\u0003לשעיר הנעשה בפנים\u0004 ש\u0003לא\u0004 ראויים, וטעם הדבר כי עדיין הוא \u0003מחוסר הגרלה\u0004 ואינו ראוי עדיין לקרבן, אם כן, אף לענין \u0003שעיר הנעשה בחוץ נמי לא חזי\u0004 \u0005[גם כן אינם ראויים]\u0006 שהרי \u0003דמחסרי\u0004 \u0005[שמחוסרים]\u0006 הם עדיין \u0003עבודת היום\u0004 כיון שעוד לא הגיעה השעה להקריב אותם, שכל עבודת יום הכיפורים חייבת להיות לפי הסדר ועדיין לא נתנו דמי הפר והשעיר ולא נעשה מעשה חפינת הקטורת והקטרתה שכולם נעשים טרם הקרבת המוספים. וכיון שכך, אפשר לומר שהם בגדר \"מחוסר זמן\". וקרבן שעדיין לא הגיע זמנו להקרבה בפנים מפני כל טעם שהוא — אינו נחשב לקרבן גם לענין חיוב כרת אם שוחטים אותו בחוץ!","ומשיבים: \u0003קסבר\u0004 \u0005[סבור]\u0006 היה \u0003רב חסדא אין מחוסר זמן לבו ביום.\u0004 כלומר: דין זה במחוסר זמן חל רק כאשר זמן ההקרבה הראוי הוא ביום אחר, אבל מה שראוי לקרבן באותו יום אף שעדיין טרם הגיעה שעתו — הריהו נחשב כאילו הוא זמנו. אבל השעיר הפנימי, כל זמן שלא נערכה ההגרלה, מאחר וזו מצוותו, עדיין נחשב הוא כמחוסר מעשה.","\u0003אמר רבינא: השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003אמר רב חסדא\u0004 ולמדנו מדבריו כי אף על פי שאינו מחוסר מעשה בגופו, בכל זאת \u0003מחוסר הגרלה כמחוסר מעשה דמי\u0004 \u0005[נחשב]\u0006 ולכן אין השעיר ראוי לקרבן, כי לא נעשה עדיין המעשה המכשירו, אם כן \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב יהודה אמר שמואל: שלמים ששחטן קודם שנפתחו דלתות ההיכל — פסולין,\u0004 לפי \u0003שנאמר\u0004 בשלמים: \u0003\"ושחטו פתח אהל מועד\"\u0004 (ויקרא ג, ב) ומכאן יש ללמוד: הפתח נחשב כפתח \u0003בזמן שהוא פתוח, ולא בזמן שהוא נעול.\u0004 וכל עוד פתח אוהל מועד (ובמקדש — פתח ההיכל) עדיין סגור אי אפשר להקריב שלמים, ואם הקריבום — הרי הם פסולים."],["\u0003שחטן בחוץ קודם שנפתחו דלתות ההיכל — פטור. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003מחוסר פתיחה כמחוסר מעשה דמי\u0004 \u0005[נחשב],\u0006 וכיון שלא היה הקרבן ראוי עדיין להיקרב בפנים, לכן כששחטו בחוץ, אף ששחטו לשמו, אינו נחשב \"כשחוטי חוץ\".","ושואלים: \u0003ומי אית ליה\u0004 \u0005[האם יש לו]\u0006 \u0003לרב חסדא,\u0004 האם מקבל הוא את העיקרון של \u0003\"הואיל\"?\u0004 כלומר: שמאחר ויכול להיווצר בעתיד מצב מסויים, דנים אנו כאילו מצב זה כבר קיים בפועל. שהרי אמר ששעירים של פנים ששחטם בחוץ לפני ההגרלה חייב עליהם, הואיל וראויים היו להקרב כקרבנות המוספים!","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חסדא:\u0004 קרבן \u0003פסח ששחטו בחוץ בשאר ימות השנה,\u0004 שלא בערב פסח, אם שחטו \u0003לשמו\u0004 כקרבן פסח \u0003— פטור,\u0004 שהרי בכל ימות השנה אינו ראוי להקרב לשם פסח בפנים. ואם שחטו \u0003שלא לשמו\u0004 אלא לשם קרבן שלמים \u0003— חייב,\u0004 שכל קרבן פסח שנשחט בשאר ימות השנה שלא לשמו אלא לשם שלמים, הריהו נחשב כקרבן שלמים, וכיון שהוא ראוי להקרב כשלמים בפנים ושחטו בחוץ — חייב.","ומעירים: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא ששחטו במפורש \u0003שלא לשמו, הא סתמא\u0004 \u0005[הרי סתם],\u0006 אם לא היה מפרש דבר, היינו אומרים ש\u0003לשמו הוא\u0004 שוחטו \u0003ופטור. ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003לימא\u0004 \u0005[שיאמר]:\u0006 \u0003הואיל וראוי\u0004 להקרב \u0003שלא לשמו בפנים,\u0004 ואם כן, יש להתייחס לכך כאילו אכן הוקרב שלא לשמו וכיון שהוקרב בחוץ יהא חייב!","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משוה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בקרבן פסח \u0003בעי\u0004 \u0005[צריך]\u0006 שתהיה בשעת השחיטה \u0003עקירה\u0004 משמו של הקרבן לשלא לשמו כדי להכשירו בפנים, וכל זמן שלא נעקר שמו אינו נחשב כראוי להקרב בפנים, אבל \u0003האי\u0004 \u0005[זה]\u0006 שעירים של פנים \u0003לא בעי\u0004 \u0005[צריך]\u0006 \u0003עקירה\u0004 משמם, שהרי גם אם מקריבם בחוץ, לשם חטאת הוא מקריבם ועדיין שם חטאת עליהם, ויש לחייבו איפוא אף בלא הכלל של \"הואיל\".","\u0003רבה בר שימי מתני להו\u0004 \u0005[היה שונה אותם]\u0006 את שתי ההלכות הללו לא בשם רב חסדא אלא בשם \u0003רבה, וקשיא ליה\u0004 \u0005[ו\u0006היה \u0005קשה לו]\u0006 מדברי \u0003רבה\u0004 על דברי \u0003רבה. ומשני כדשנינן\u0004 \u0005[ותירץ כמו שתירצנו]\u0006 באותה דרך.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' ירמיה אמר ר' יוחנן: פסח ששחטו בחוץ בשאר ימות השנה, בין\u0004 ששחטו \u0003לשמו בין\u0004 ששחטו \u0003שלא לשמו — פטור.\u0004","\u0003אמר רב דימי: אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי הלכה זו לפני]\u0006 \u0003ר' ירמיה\u0004 ושאלתיו: \u0003בשלמא\u0004 \u0005[נניח]\u0006 כשמקריב אותו בחוץ \u0003לשמו,\u0004 הריהו פטור, \u0003דהא לא חזי ליה\u0004 \u0005[שהרי אינו ראוי לו]\u0006 להקרבה בפנים לשם פסח בשאר ימות השנה, וכל שאינו ראוי בפנים — אין עוברים עליו בחוץ. \u0003אלא\u0004 אם שחטו \u0003שלא לשמו — אמאי\u0004 \u0005[מדוע]\u0006 פטור? \u0003הא חזי\u0004 \u0005[הרי ראוי]\u0006 להקריבו \u0003שלא לשמו\u0004 בתורת שלמים \u0003בפנים,\u0004 ומדוע נפטר איפוא על הקרבתו בחוץ?","\u0003ואמר לי\u0004 ר' ירמיה בתשובה: כלל הוא כי \u0003עקירת\u0004 שמו של קרבן \u0003חוץ\u0004 למקדש \u0003לאו\u0004 \u0005[אין]\u0006 \u0003שמה עקירה,\u0004 שאינה יכולה להיעשות אלא בתוכו, ומכיון ששחטו בחוץ, אף ששחטו שלא לשמו — אין במעשהו כל תוקף ואין זו נחשבת עקירה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 נוסח אחר בשם \u0003ר' ירמיה אמר ר' יוחנן: פסח ששחטו בחוץ בשאר ימות השנה, בין לשמו בין שלא לשמו — חייב.\u0004","ותוהים: \u0003ואפילו לשמו\u0004 חייב? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 במסכת זבחים (קיב, ב): קרבן שהיה \u0003מחוסר זמן,\u0004 כלומר: שלא היה ראוי להקרבה מפני גורם התלוי בזמן. \u0003בין\u0004 שהיה מחוסר זמן \u0003בגופו\u0004 כגון שהוא פחות מבן שמונה ימים, \u0003בין בבעלים,\u0004","ומבארים: \u0003ואיזהו מחוסר זמן בבעלים\u0004 — כגון \u0003הזב והזבה והיולדת והמצורע\u0004","\u0003שהקריבו חטאתם ואשמם\u0004 (=אשם מצורע) לפני הזמן הראוי להם (זב, זבה ומצורע — בתום ספירת שבעה, יולדת — במלאות ימי טהרתה), קרבנות אלה אם הקריבום \u0003בחוץ — פטורין,\u0004 שמכיון שטרם הגיע זמנם אינם עולים לבעליהם לשם חובה, שהרי עדיין לא הגיע זמנם. ולנדבה אינם עולים, שהרי אין חטאת ואשם באין נדבה. אבל אם הקריבו \u0003עולותיהן ושלמיהן\u0004 כיון שאינם קרבנות כפרה ממש, אלא הם כדורון לשמים, לכן אם הקריבום \u0003בחוץ — חייבין.\u0004","\u0003ואמר רב חלקיה בר טובי: לא שנו\u0004 שהמקריב אשם שלא לשמו ועדיין לא הגיע זמנו בבעלים שפטור \u0003אלא\u0004 שמקריב קרבן זה \u0003לשמו, אבל\u0004 אם מקריב אותו \u0003שלא לשמו — חייב,\u0004 כי אשם שהוקרב שלא לשמו מכל מקום הוא קרבן כשר.","ומדייק: \u0003לשמו מיהא\u0004 \u0005[על כל פנים]\u0006 אם שחטו הרי הוא \u0003פטור, אמאי\u0004 \u0005[ומדוע]?\u0006 \u0003נימא\u0004 \u0005[ונאמר]:\u0006 \u0003הואיל וראוין שלא לשמו בפנים,\u0004 יהיו איפוא חייבים אף על הקרבתם בחוץ! ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משוה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 באשם \u0003בעי\u0004 \u0005[צריך]\u0006 שתהא \u0003עקירה\u0004 מפורשת מלהיות לשמו, כדי להכשירו. \u0003הכא\u0004 \u0005[כאן]\u0006 לגבי פסח כלל בידינו כי \u0003פסח בשאר ימות השנה — שלמים נינהו\u0004 \u0005[הם],\u0006 אף כשלא היתה אינו עקירה מפורשת.","ועוד בבעיה זו של הפסח ששחטו בחוץ שלא לשמו בשאר ימות השנה, \u0003רב אשי מתני\u0004 \u0005[היה שונה]\u0006 בהלכה זו: \u0003חייב כדאמרינן\u0004 \u0005[כפי שאמרנו].\u0006 \u0003רב ירמיה מדפתי מתני\u0004 \u0005[היה שונה]:\u0006 \u0003פטור,\u0004 וטעמו: \u0003קסבר\u0004 \u0005[סבור\u0006 היה\u0005]:\u0006 \u0003פסח בשאר ימות השנה בעי\u0004 \u0005[צריך]\u0006 \u0003עקירה\u0004 כדי שיחשב שלא לשמו, \u0003ועקירת חוץ לאו\u0004 \u0005[אין]\u0006 \u0003שמה עקירה. ופליגא\u0004 \u0005[וחלוקה]\u0006 הלכה זו על דברי \u0003רב חלקיה בר טובי,\u0004 שהרי לדעתו עקירת חוץ שמה עקירה.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 שני שעירי יום הכיפורים ששחטן בחוץ, \u0003משהגריל עליהן — חייב על של שם, ופטור על של עזאזל.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: נאמר: \u0003\"איש איש מבית ישראל אשר ישחט שור או כשב או עז במחנה או אשר ישחט מחוץ למחנה. ואל פתח אהל מועד לא הביאו להקריב קרבן לה'\u0004 לפני משכן ה' דם יחשב לאיש ההוא דם שפך ונכרת האיש ההוא מקרב עמו\u0003\"\u0004 (ויקרא יז ג-ד)."],["\u0003אי\u0004 \u0005[אם]\u0006 \u0003\"קרבן\", שומע אני אפילו קדשי בדק הבית\u0004 ששחטן בחוץ יהיה חייב עליהן, שהרי גם הם \u0003נקראו קרבן, כענין שנאמר: \"ונקרב את קרבן ה'\u0004 איש אשר מצא כלי זהב אצעדה וצמיד טבעת עגיל וכומז\u0003\"\u0004 (במדבר לא, נ), \u0003תלמוד לומר: \"ואל פתח אהל מועד לא הביאו\"\u0004 (ויקרא יז, ד), ללמדנו: \u0003כל\u0004 הקדש \u0003הראוי\u0004 להקריבו \u0003לפתח אהל מועד\u0004 — \u0003חייב עליו\u0004 אם הקריבו \u0003בחוץ,\u0004 ו\u0003כל שאינו ראוי לפתח אהל מועד — אין חייבין עליו\u0004 אם הקריבוהו \u0003בחוץ.\u0004","ועוד: \u0003אוציא\u0004 את \u0003אלו\u0004 קדשי בדק הבית \u0003שאין ראוין לפתח אהל מועד\u0004 שסתם בהמות המוקדשות לבדק הינם בעלי מומים ואינם ראויים למזבח, \u0003ולא אוציא פרת חטאת\u0004 (פרה אדומה) \u0003ושעיר המשתלח שהוא\u0004 השעיר \u0003ראוי לבוא אל פתח אהל מועד\u0004 להגרלה ולוידוי, \u0003תלמוד לומר: \"לה'\"\u0004 וכוונתו: \u0003מי שמיוחדין לה', יצאו אלה שאין\u0004 הם \u0003מיוחדין לשם\u0004 שהרי אינם באים לקרבן ממש אלא לצורך אחר.","על מדרש הלכה זה שואלים: וכי הביטוי \u0003\"לה'\"\u0004 דווקא \u0003להוציא\u0004 ולמעט \u0003הוא\u0004 בא? \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: נאמר: \u0003\"\u0004שור או כשב או עז כי יולד והיה שבעת ימים תחת אמו ומיום השמיני והלאה \u0003ירצה לקרבן אשה לה'\"\u0004 (ויקרא כב, כז), ומכאן למדנו: \u0003אלו אישים\u0004 הקרבנות העולים על המזבח שאסור להקריבם טרם זמנם,","\u0003מנין שלא יקדישנו\u0004 את השעיר המשתלח כשהוא \u0003מחוסר זמן,\u0004 כלומר: לפני היום השמיני — \u0003תלמוד לומר: \"קרבן לה'\" — לרבות שעיר המשתלח\u0004 שאף הוא מובא לשם שמים בעיקרו, הרי שהביטוי \"לה'\" אינו בא למעט שעיר המשתלח מתורת קרבנות, אלא להיפך, להכלילו ביניהם!","\u0003אמר רבא,\u0004 יש ליישב: \u0003התם מענינא דקרא והכא מענינא דקרא\u0004 \u0005[שם מעניינו של הכתוב, וכאן מעניינו של הכתוב],\u0006 כלומר, לפי עניינו של הפסוק אפשר להבין אם ביטוי מסויים משמעו לרבות או למעט. כיצד? \u0003התם\u0004 \u0005[שם]\u0006 בענין שחוטי חוץ כשהביטוי באותו מקרא \u0003\"אל פתח\"\u0004 בא \u0003לרבות\u0004 ולהוסיף קרבנות אחרים, ממילא מה שנאמר \u0003\"לה'\"\u0004 ודאי אינו בא אלא \u0003להוציא.\u0004 ולהיפך, \u0003הכא\u0004 \u0005[כאן]\u0006 שהביטוי \u0003\"אשה\"\u0004 בא \u0003להוציא\u0004 ולצמצם, הרי \u0003\"לה'\"\u0004 בא \u0003לרבות.\u0004","לאחר שיישבנו את הסתירה, תוהים על עצם הלימוד: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא \u0003דרבי רחמנא\u0004 \u0005[שריבתה התורה]\u0006 במפורש שעיר המשתלח בין הקרבנות, שאין להקדישו טרם מלאות שמונה ימים ללידתו, \u0003הא לא רבי\u0004 \u0005[הרי אם לא היית מרבה]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003שעיר המשתלח קדוש\u0004 אפילו כשהוא \u0003מחוסר זמן.\u0004 ויש לתמוה: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אין הגורל קובע\u0004 לה' \u0003אלא בראוי לשם,\u0004 וכיון שעדיין אינו יודע איזה מהם יעלה בגורל לה', לא שייך שייחשב אחד מהם כמחוסר זמן!","\u0003אמר רב יוסף: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו כשיטת מי היא],\u0006 כשיטת \u0003חנן המצרי היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חנן המצרי אומר: אפילו\u0004 נשחט כבר השעיר הפנימי ו\u0003דם\u0004 השעיר מצוי כבר \u0003בכוס,\u0004 ומת השעיר המשתלח — \u0003מביא חבירו\u0004 מן השוק \u0003ומזווג לו\u0004 ואין צריך לעשות הכל מחדש, אלא מצרפים את השעיר השני, שיהא לעזאזל. ולכן צריך לומר ששעיר זה לא יהא מחוסר זמן.","ועדיין מקשים: \u0003אימר דשמעת ליה\u0004 \u0005[אמור ששמעת אותו]\u0006 את \u0003חנן המצרי דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003דחויין,\u0004 שאפילו אם מת המשתלח אין בן זוגו נדחה, אולם \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 גם \u0005הגרלה\u0006 \u0003הגרלה\u0004 לשעיר השני \u0003מי שמעת ליה\u0004 \u0005[האם שמעת אותו]\u0006 שמפרש כן? \u0003דילמא מייתי\u0004 \u0005[שמא\u0006 כוונתו שאכן \u0005מביא]\u0006 \u0003ומגריל\u0004 ומה שאמר שמביא את חבירו ומזווג לו — אין הכוונה שלוקח מיד שעיר לעזאזל, אלא מביא זוג שעירים אחר ומגריל ביניהם, וזה שעלה עליו הגורל להיות משתלח לעזאזל הוא בן זוגו של זה שכבר נשחט קודם לכן.","\u0003אלא אמר רב יוסף: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו כשיטת מי היא],\u0006 כשיטת \u0003ר' שמעון היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מת אחד מהן\u0004 מן השעירים — \u0003מביא חבירו\u0004 במקומו \u0003שלא בהגרלה,\u0004 אלו \u0003דברי ר' שמעון,\u0004 ולכן הוצרך לומר ששעיר זה לא יהא בעל מום.","\u0003רבינא אמר\u0004 שאפשר לפרש שהוא כדעת הכל, וכאן מדובר \u0003כגון שהומם\u0004 (נעשה בעל מום) השעיר המשתלח \u0003וחיללו על אחר\u0004 ואז אין השני צריך הגרלה, שהרי מכוחו של ראשון הוא בא.","ושואלים: \u0003ומנא תימרא\u0004 \u0005[ומנין תאמר]\u0006 \u0003דפסיל ביה מומא\u0004 \u0005[שפוסל בו מום]\u0006 בשעיר המשתלח, שהרי אין מום פוסל אלא בקרבן והוא הרי אינו קרבן! \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \"עורת או שבור או חרוץ או יבלת או גרב או ילפת לא תקריבו אלה לה' \u0003ואשה לא תתנו מהם\u0004 על המזבח לה'\" (ויקרא כב, כב), \"ואשה לא תתנו וגו'\" \u0003אלו החלבים\u0004 של בעלי המומים שאסור להקריבם למזבח.","\u0003אין לי אלא\u0004 שאסורה הקרבת חלבי בעל מום \u0003כולן,\u0004 אבל אם הקריב \u0003מקצתן\u0004 של החלבים בלבד \u0003מנין\u0004 שעובר עליהם? — \u0003תלמוד לומר: \"מהם\"\u0004 ופירושו: אף מקצתן. \u0003\"\u0004ה\u0003מזבח\" — זו זריקת דמים\u0004 שאסור לזרוק מדמם של אלה. \u0003\"לה'\" — לרבות שעיר המשתלח.\u0004","ומעירים: \u0003ואיצטריך למיכתב\u0004 \u0005[וצריך היה לכתוב]\u0006 ריבוי לענין \u0003בעל מום\u0004 שפוסל בשעיר המשתלח, \u0003ואיצטריך למיכתב\u0004 \u0005[והוצרך לכתוב]\u0006 ריבוי לענין \u0003מחוסר זמן\u0004 שפוסל בשעיר המשתלח. וטעמו של דבר: \u0003דאי כתב רחמנא\u0004 \u0005[שאילו כתבה התורה]\u0006 לפסול \u0003מחוסר זמן\u0004 בלבד הייתי אומר: דווקא הוא פסול, \u0003משום\u0004 שעדיין \u0003לא מטי זמניה\u0004 \u0005[הגיע זמנו]\u0006 ולכן עדיין לא חלה עליו קדושה כלל, \u0003אבל בעל מום דמטי זמניה\u0004 \u0005[שהגיע זמנו]\u0006 ורק אחר כך נפסל — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ויהיה כשר. ולהיפך, \u0003ואי כתב רחמנא\u0004 \u0005[ואילו כתבה התורה]\u0006 לפסול \u0003בעל מום\u0004 בלבד, הייתי אומר: דווקא הוא פסול \u0003משום\u0004 שהבאת בעל מום לקרבן בזיון הוא כיון \u0003דמאיס\u0004 \u0005[\u0006שהוא \u0005מאוס],\u0006 \u0003אבל\u0004 הבאת \u0003מחוסר זמן דלא מאיס\u0004 \u0005[שאינו מאוס]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ויהיה כשר, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שיהיה ריבוי מיוחד לשני המקרים."],["\u0003רבא אמר:\u0004 לא בא הכתוב למעט את השעיר המשתלח כשהוא מחוסר זמן אלא במקרה מסויים בלבד, \u0003כגון שהיה לו\u0004 לזה שמכר את שני השעירים לציבור \u0003חולה\u0004 מסוכן \u0003בתוך ביתו ושחט\u0004 עבורו את \u0003אמו\u0004 של השעיר המשתלח \u0003ביום הכפורים\u0004 עצמו מדין פיקוח נפש, וכיון שאסור לשחוט אותו ואת בנו ביום אחד, נמצא שבאותו יום שעיר זה הוא מחוסר זמן.","ושואלים: \u0003וכי האי גוונא מי אסיר\u0004 \u0005[ובכגון זה האם אסור]?\u0006 הלא \"ושור או שה אותו ואת בנו \u0003לא תשחטו\u0004 ביום אחד\" (ויקרא כב, כח) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003והא\u0004 \u0005[וזו]\u0006 הדחיה מהצוק \u0003לאו שחיטה היא,\u0004 ואין בכך משום איסור \"אותו ואת בנו\"! ומשיבים: \u0003הא אמרי במערבא\u0004 \u0005[הרי אומרים בארץ ישראל]\u0006 \u0003דחייתו לצוק זו היא שחיטתו,\u0004 וכיון שזוהי מצותו, בכך נחשב הוא כשחוט.","שנינו במשנה: מת אחד מן השעירים לאחר ההגרלה, יביא זוג אחר ויגריל עליהם מחדש ויאמר: \u0003אם של שם מת, זה שעלה עליו\u0004 עכשיו הגורל לה' \u0003—\u0004 יתקיים תחתיו. וכיון שעומדים לפנינו שני שעירים לעזאזל, אחד מהם ירעה עד שיפול בו מום וימכר ויפלו דמיו לנדבה. וכן אם של עזאזל מת \u0003—\u0004 יתקיים זה שעלה עליו עכשיו הגורל לעזאזל תחתיו. וכיון שעומדים לפנינו שני שעירים לה', אחד מהם ירעה עד שיפול בו מום וימכר ויפלו דמיו לנדבה. ויש לדון איזה מהם ניתן לרעייה, האם זה שנותר מהגרלה ראשונה או הנותר מהגרלה שניה.","\u0003אמר רב: שני,\u0004 השעיר לה', \u0003שבזוג ראשון — יקרב,\u0004 ו\u0003שני שבזוג שני — ירעה\u0004 עד שיפול בו מום. \u0003ר' יוחנן אמר: שני שבזוג ראשון\u0004 הוא ש\u0003ירעה,\u0004 ואילו \u0003שני שבזוג שני — יקרב.\u0004","ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה הם חלוקים],\u0006 מה הוא יסוד מחלוקתם? ומסבירים: \u0003רב סבר: בעלי חיים אינן נידחין,\u0004 כלומר: בעל חיים שהוקדש למטרה מסויימת ומפני טעם כלשהו לא היה ראוי בשעתו לקרבן, אינו נחשב כדחוי שיהיה פסול משום כך לעולם. ולכן אף שמשמת בן זוגו לא היה ראוי להקרב, מכל מקום משיצטרף לו בן זוג לאחד הגרלה מחודשת שוב אינו נדחה ויש להקריבו. \u0003ור' יוחנן סבר:\u0004 אף \u0003בעלי חיים נידחין,\u0004 ולכן, שעיר שבזוג ראשון כיון שלא היה לו בן זוג בשעתו נפסל לעולם מלהיקרב.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב,\u0004 על מה הוא מבסס את שיטתו? \u0003דיליף\u0004 \u0005[ש\u0006הוא \u0005לומד]\u0006 מדינו של \u0003מחוסר זמן,\u0004 קרבן שעדיין לא הגיע זמנו להיקרב וכגון שעדיין לא מלאו שמונה ימים ללידתו. \u0003מחוסר זמן, לאו אף על גב דהשתא לא חזי\u0004 \u0005[האם לא אף על פי שעכשיו אינו ראוי],\u0006 \u0003כי הדר מיחזי\u0004 \u0005[כאשר חוזר ונעשה ראוי]\u0006 \u0003— שפיר דמי\u0004 \u0005[יפה הדבר]\u0006 ואין בו חסרון, \u0003הכא נמי לא שנא\u0004 \u0005[כך גם כן אינו שונה].\u0006 ודוחים: \u0003מי דמי\u0004 \u0005[האם דומה]\u0006 הדבר? הרי \u0003התם\u0004 \u0005[שם]\u0006 במחוסר הזמן \u0003לא איתחזי\u0004 \u0005[נראה]\u0006 \u0003כלל,\u0004 שמתחילה לא היה ראוי כלל לקרבן, ואין לקרוא לו איפוא דחוי כלל. \u0003הכא\u0004 \u0005[כאן]\u0006 במקרה זה הלא \u0003נראה\u0004 היה ראוי כבר לקרבן \u0003ונדחה\u0004 ושמא נפסל בכך?","\u0003אלא\u0004 חוזרים מההסבר הראשון ואומרים: \u0003היינו טעמא\u0004 \u0005[זהו טעמו]\u0006 של \u0003רב, דיליף\u0004 \u0005[ש\u0006הוא \u0005לומד]\u0006 \u0003מבעל מום עובר,\u0004 כלומר: בעל חיים שהיה בו מום, אלא שמום זה מתרפא לאחר זמן ואין מום כזה פוסל להקרבה אלא בשעודו עליו ומשעבר הריהו כשר. \u0003בעל מום עובר לאו אף על גב דלא חזי השתא\u0004 \u0005[האם לא אף על פי שאינו ראוי עכשיו],\u0006 \u0003כי הדר מיחזי\u0004 \u0005[כאשר הוא חוזר ונעשה ראוי] —\u0006 \u0003שפיר דמי\u0004 \u0005[טוב הדבר],\u0006 \u0003הכא נמי לא שנא\u0004 \u0005[כאן גם כן איננו שונה].\u0006","ושואלים: \u0003והתם מנא לן\u0004 \u0005[ושם\u0006 בבעל מום עובר \u0005מנין לנו]\u0006 הלכה זו שבחלוף המום הריהו כשר להקרבה? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי משחתם בהם מום בם\u0004 לא ירצו לכם\u0003\"\u0004 (ויקרא כב, כה), ללמדנו: כאשר \u0003מום בם — הוא\u0004 ש\u0003לא ירצו, הא\u0004 \u0005[הרי]\u0006 \u0003אם עבר מומן — ירצו.\u0004","ושואלים: \u0003ור' יוחנן\u0004 מה אומר הוא על הוכחה זו? לשיטתו: \u0003מיעט רחמנא\u0004 \u0005[הכתוב]\u0006 על ידי ההדגשה \u0003\"בהם\"\u0004 לומר: \u0003הם הוא דכי\u0004 \u0005[שכאשר]\u0006 \u0003עבר מומן ירצו, הא\u0004 \u0005[הרי]\u0006 \u0003כל דחויין\u0004 אחרים, \u0003הואיל ונדחו — נדחו.\u0004","ושואלים: \u0003ורב,\u0004 מה משיב הוא על דברי ר' יוחנן? \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 \u0003\"בהם\"\u0004 יש להבינו כך: \u0003בעינייהו הוא דלא מירצו\u0004 \u0005[בעינם,\u0006 לבדם, \u0005הוא שאינם מרצים]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003על ידי תערובות\u0004 שנתערבו בקרבנות כשרים אף הם \u0003מירצו\u0004 \u0005[מרצים].\u0006","\u0003כדתנן\u0004 \u0005[\u0006ו\u0005כפי ששנינו\u0006 במשנה\u0005]:\u0006 נתערבו \u0003איברים תמימים\u0004 (של עולות תמימות, כשרות) \u0003באיברים\u0004 של עולות \u0003בעלי מומין. ר' אליעזר אומר: אם קרב\u0004 כבר \u0003הראש של אחד מהן\u0004 כשלא ידעו על הפסול והקריבוהו, הרי אנו מניחים שהפסול הוא שכבר הוקרב, וכל השאר כשרים הם ולכן \u0003יקריבו כל הראשין כולן,\u0004 וכן אם קרבו \u0003כרעיו\u0004 (רגליו) \u0003של אחד מהן — יקריבו כל הכרעיים כולן. וחכמים אומרים: אפילו קרבו כולן חוץ מאחד מהן — יצא לבית השריפה\u0004, שלשיטתם כיון שכבר קרבו שוב אין לחשוש שאברי בעל המום היו ביניהם. ואם כן, נראה שלא רק ר' אליעזר אלא אף חכמים סבורים כי פסול זה אינו אלא מדברי סופרים, אבל מדין תורה, כיון שנתערבו — שוב אינם פסולים.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יוחנן\u0005]\u0006 מהיכן למד הוא הלכה זו שהם כשרים על ידי תערובת? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו,\u0006 נלמד הדבר\u0005]\u0006 משינוי הלשון, שהיה יכול לכתוב \u0003\"בם\"\u0004 וכתב \u0003\"בהם\",\u0004 ולכך יש ללמוד ממילה זו שתי הלכות. ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 רב\u0005]\u0006 מה הוא סבור על דיוק זה? ומשיבים: \u0003\"בם\" \"בהם\" — לא דריש\u0004 \u0005[אינו דורש],\u0006 שאינו סבור כי יש בשינוי לשון זה כדי להוציא ממנו הלכה. עד כאן ביררנו שיטות רב ור' יוחנן.","ושואלים: \u0003ולרב, נהי נמי\u0004 \u0005[אם כי גם]\u0006 אומרים ש\u0003בעלי חיים אינן נדחין,\u0004 הרי זה מסביר רק מפני מה אף השעיר שבזוג ראשון כשר לקרבן, אולם מדוע דווקא יוקרב דווקא הוא? \u0003אי בעי האי נקריב\u0004 \u0005[אם רוצה את זה\u0006 שבזוג ראשון \u0005יקריב]\u0006 \u0003ואי בעי האי נקריב\u0004 \u0005[ואם רוצה את זה,\u0006 שבזוג שני, \u0005יקריב]!\u0006","\u0003אמר רבא: רב סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' יוסי\u0004 ש\u0003אמר: מצוה בראשון.\u0004 ושואלים: \u0003הי\u0004 \u0005[איזה]\u0006 מדברי \u0003ר' יוסי\u0004 מלמד שזו היא שיטתו? \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 שיטת \u0003ר' יוסי\u0004 בענין \u0003קופות, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 היו בלשכה \u0003שלש קופות של שלש שלש סאין, שבהן תורמין את\u0004 הכסף שב\u0003לשכה, וכתוב עליהן: אלף בית גימל. ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יוסי: למה כתוב עליהן אלף בית גימל — לידע איזה מהן נתרמה ראשון,\u0004 כדי \u0003להביא הימנה\u0004 קרבן \u0003ראשון,\u0004 לפי \u0003שמצוה בראשון.\u0004","אולם מכאן אין הוכחה גמורה לעניננו, \u0003דילמא שאני התם\u0004 \u0005[שמא שונה שם]\u0006 בקופות, \u0003דבעידנא דאתחזי קמיתא לא אתחזי בתרייתא\u0004 \u0005[שבזמן שהיתה ראויה הראשונה, לא היתה ראויה האחרונה]\u0006 ולכן חלה המצוה על הראשון. אבל אין מכאן הוכחה לכששניהם ראויים באותה שעה.","\u0003אלא\u0004 למדים זאת משיטת \u0003ר' יוסי\u0004 בענין קרבן \u0003פסח. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המפריש\u0004 שה\u0003לפסחו ואבד\u0004 לפני חצות היום, \u0003והפריש אחר תחתיו, ואחר כך\u0004 לאחר חצות היום שראוי כבר הפסח להיקרב \u0003נמצא הראשון, והרי שניהן עומדין\u0004 לפניו — \u0003איזה מהן שירצה\u0004 בעליו \u0003יקרב, דברי חכמים. ר' יוסי אומר: מצוה בראשון.\u0004"],["\u0003ואם היה השני מובחר ממנו יביאנו.\u0004 הרי שלדבריו אף ששניהם ראויים באותה שעה, יש מלכתחילה להעדיף את הראשון.","\u0003אמר רבא: דיקא מתניתין כוותיה\u0004 \u0005[מדוייקת משנתנו כשיטתו]\u0006 של \u0003רב וברייתא\u0004 \u0005[והברייתא]\u0006 מדוייקת \u0003כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003ר' יוחנן.\u0004 ומפרט: \u0003מתניתין כוותיה\u0004 \u0005[משנתנו\u0006 מדוייקת \u0005כשיטתו]\u0006 של \u0003רב, דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בה\u0005]:\u0006 \u0003אם של שם מת — זה שעלה עליו הגורל לשם יתקיים תחתיו,\u0004 משמע: \u0003ואידך כדקאי קאי\u0004 \u0005[והאחר\u0006 זה בן זוגו \u0005כמו ש\u0006היה \u0005עומד\u0006 עדיין הוא \u0005עומד],\u0006 שלא נשתנה דינו, וכדעת רב.","וה\u0003ברייתא\u0004 מדוייקת \u0003כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003ר' יוחנן, דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"שני\"\u0004 שהזכירה המשנה בדבריה, \u0003איני יודע אם\u0004 מדובר ב\u0003שני שבזוג ראשון אם שני שבזוג שני, כשהוא אומר \"יעמד חי\"\u0004 משמע: \u0003ולא שחבירו מת.\u0004 ושואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 כלומר: כיצד למדים מכאן \"ולא שחבירו מת\"? ומשיבים: שאמרו \u0003\"יעמד חי\"\u0004 לשון עתיד, משמע: \u0003ולא\u0004 זה \u0003שכבר עמד\u0004 עם בן זוגו המת.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003ועוד אמר ר' יהודה: נשפך הדם\u0004 של השעיר לה' — \u0003ימות המשתלח, מת\u0004 השעיר \u0003המשתלח — ישפך הדם. בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 כי אף \u0003בעלי חיים נדחין — משום הכי\u0004 \u0005[כך]\u0006 \u0003ימות המשתלח. אלא לרב,\u0004 ש\u0003אמר\u0004 כי \u0003בעלי חיים אינן נדחין\u0004 אם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003ימות המשתלח?\u0004","\u0003אמר לך רב\u0004 \u0005[\u0006יכול היה \u0005רב לומר לך]:\u0006 \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' יהודה לא קא אמינא\u0004 \u0005[אין אני אומר],\u0006 שהרי ודאי אין דבריו כדעתי. \u0003כי אמינא\u0004 \u0005[כאשר אומר אני]\u0006 ומפרש את דעתי, הרי זה \u0003אליבא דרבנן\u0004 \u0005[על פי שיטת חכמים].\u0006 שמתוך שר' יהודה בא להשמיענו כי בעלי חיים נדחים, הרי שלדעת חכמים החולקים עליו אינם נדחים והשני שבזוג הראשון קרב ושבזוג השני ירעה עד שיפול בו מום, שהרי אין חטאת הציבור מתה, ובשני הדינים הללו חולק אני עליהם ואומר כי זה שאמרתם שירעה, לדעתי הוא קרב וזה שאמרתם שהוא קרב, לדעתי הולך הוא למיתה.","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003רב, בהא פליגי\u0004 \u0005[\u0006בדבר \u0005זה נחלקו]\u0006 \u0003ר' יהודה ורבנן\u0004 \u0005[וחכמים],\u0006 בנשפך דם השעיר או מת השעיר לעזאזל, אם בעלי חיים נדחין או לא, וזהו \"ועוד אמר ר' יהודה וכו'\" שהביאה המשנה. \u0003אלא\u0004 לשיטת \u0003ר' יוחנן\u0004 שאף לחכמים השני שבזוג הראשון הוא שירעה, אם כן \u0003במאי פליגי\u0004 \u0005[במה הם חלוקים]?\u0006 \u0003אמר רבא: הא אמרינן\u0004 \u0005[הרי\u0006 כבר \u0005אמרנו]\u0006 כי \u0003דייקא מתניתין כוותיה\u0004 \u0005[מדוייקת משנתנו כשיטתו]\u0006 של \u0003רב\u0004 וקשה לפרש אותה כיאות לדברי ר' יוחנן.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003שאין חטאת צבור מתה. הא\u0004 \u0005[הרי]\u0006 נדייק מכאן: שחטאת של \u0003יחיד כי האי גוונא\u0004 \u0005[כעין זה] —\u0006 \u0003מתה.\u0004 ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003ר' יוחנן\u0004 הסבור כי בדין שהובא במשנה שמת אחד השעירים שהשני שבזוג הראשון ירעה, ואינו מת לפי שאין חטאת הציבור מתה, אפשר להסביר מפני מה חטאת יחיד כגון זו דחויה ומתה כדברי \u0003ר' אבא אמר רב.\u0004 ש\u0003אמר ר' אבא אמר רב:\u0004"],["\u0003הכל מודים שאם\u0004 הפריש יחיד חטאתו ואבדה והפריש אחרת תחתיה ו\u0003נתכפר\u0004 בזו \u0003שאינה אבודה,\u0004 כלומר: בשניה, ולאחר מכן מצאו את האבודה — \u0003אבודה מתה.\u0004","\u0003אלא\u0004 לשיטת \u0003רב\u0004 עצמו הסבור בדין שהובא במשנה שמת אחד מן השעירים כי השני שבזוג השני הוא שירעה ויתכפר בראשון שנדחה, אם כן מדוע חטאת של יחיד בכגון זה תמות, \u0003הוה ליה\u0004 \u0005[הרי זה]\u0006 \u0003כמפריש שתי חטאות לאחריות\u0004 שחושש שמא תאבד אחת ומפריש מיד שתים להקריב אחת מהן, \u0003ואמר ר' אושעיא:\u0004 כי לדעת הכל אם \u0003הפריש שתי חטאות לאחריות —\u0004 הריהו \u0003מתכפר באחת מהם, והשניה תרעה\u0004 עד שיפול בה מום. ואם כן, מדוע לדעת ר' יהודה תמות השניה?","ומשיבים: \u0003כיון\u0004 ש\u0003אמר רבא\u0004 כי \u0003רב סבר לה\u0004 \u0005[סבור הוא]\u0006 כשיטת \u0003ר' יוסי\u0004 ש\u0003אמר\u0004 כי \u0003מצוה בראשון,\u0004 הרי לשיטה זו הזוג השני \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 הוא \u0003כמפריש\u0004 אותו בכוונה שילך \u0003לאיבוד דמי\u0004 \u0005[נחשב].\u0006","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003ר' יהודה אומר: תמות. בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 כי \u0003שני שבזוג ראשון ירעה,\u0004 הרי \u0003לר' יהודה\u0004 שאמר \u0003ימות\u0004 הרי הוא \u0003מתכפר בשני שבזוג שני.\u0004","\u0003אלא לרב\u0004 ש\u0003אמר\u0004 כי \u0003שני שבזוג שני ירעה,\u0004 ולדעתו \u0003ר' יהודה\u0004 אמר ש\u0003ימות,\u0004 אם כן \u0003לר' יהודה במאי מיכפר\u0004 \u0005[במה הוא מתכפר]?\u0006 שהרי אינו יכול להקריב אף אחד מהם, הראשון משום שנדחה ולדבריו בעלי חיים נדחים, והשני הלא רועה ולשיפול בו מום ימכר לשוק! ומשיבים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי \u0003ר' יהודה\u0004 על \u0003שני שבזוג שני קאי\u0004 \u0005[עומד,\u0006 מוסב\u0005]?\u0006 לא על שעיר זה מדבר ר' יהודה, אלא \u0003אשני שבזוג ראשון קאי\u0004 ועליו אמר שימות, אבל השני לא ימות כלל ובו תהא כפרתו.","\u0003ואיכא דקא מותיב הכי\u0004 \u0005[ויש שהיה מקשה\u0006 באופן \u0005זה]:\u0006 שנינו במשנה: \u0003ועוד אמר ר' יהודה: נשפך הדם — ימות המשתלח, מת המשתלח — ישפך הדם.\u0004","\u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003רב רישא\u0004 \u0005[בתחילה]\u0006 הרי הם חלוקים בדין \u0003חטאת צבור\u0004 שלשיטת חכמים השני ירעה ולשיטת ר' יהודה ימות, \u0003וסיפא\u0004 \u0005[ובסופה\u0006 של המשנה\u0005]\u0006 \u0003פליגי\u0004 \u0005[חלוקים הם]\u0006 \u0003בבעלי חיים\u0004 אם הם נדחין או לא נדחין, שלשיטת חכמים אינם נדחים ומתכפר בראשון ולשיטת ר' יהודה הריהם נדחים ולכך הראשון ימות ויתכפר בשני. \u0003אלא לר' יוחנן מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 \u0003\"ועוד\"\u0004 שנאמר, שהרי לדעתו אף חכמים סבורים כי השני שבזוג ראשון ידחה ואין איפוא מחלוקת בכך. ומעירים אכן \u0003קשיא\u0004 \u0005[קשה].\u0006","שנינו במשנה: \u0003\"ועוד אמר ר' יהודה: נשפך הדם\u0004 של השעיר לה' — \u0003ימות המשתלח\",\u0004 ואם מת המשתלח — ישפך דם השעיר לה'. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 במה שאמר שאם \u0003נשפך הדם ימות המשתלח — דאכתי לא איתעביד מצותיה\u0004 \u0005[שעדיין לא נעשתה מצותו]\u0006 של השעיר החי.","\u0003אלא אם מת המשתלח אמאי\u0004 \u0005[מדוע]\u0006 \u0003ישפך הדם? הא איתעביד ליה מצותיה\u0004 \u0005[הרי\u0006 כבר \u0005נעשתה בו מצותו]\u0006 של השעיר המשתלח, שאין מעכב בו אלא דבר שצריך להיעשות על ידי הכהן וזוהי ההגרלה, אבל שילוחו לעזאזל ודחייתו מן הצוק אינו נעשה אלא על ידי איש עיתי ולכך אין דבר זה מעכב אלא לכתחילה, אולם בדיעבד אם מת באופן אחר — יצא!","\u0003אמרי דבי\u0004 \u0005[אמרו\u0006 חכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"והשעיר אשר עלה עליו הגורל לעזאזל \u0003יעמד חי לפני ה' לכפר\u0004 עליו לשלח אותו לעזאזל המדברה\" (ויקרא טז, י), ומכאן למדים כי \u0003עד מתי יהא זקוק\u0004 שעיר זה \u0003להיות חי — עד\u0004 שעת כפרה שהיא \u0003שעת מתן דמים של חבירו,\u0004 ואם מת קודם לכן פוסל את עצמו ואת חבירו.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת שקלים (פ\"ב מ\"א): \u0003בני העיר ששלחו את שקליהן\u0004 למקדש באמצעות שליחים \u0003ונגנבו\u0004 השקלים בדרך \u0003או שאבדו, אם\u0004 כבר \u0003נתרמה\u0004 ה\u0003תרומה\u0004 במקדש, שהוציאו מהלשכה את השקלים לצורך קרבנות השנה החדשה לפני שנגנב הכסף — \u0003נשבעין\u0004 השליחים שהם לא מעלו בשקלים, אלא שנלקחו מהם שלא מדעתם או באונסם, ושבועתם \u0003לגזברין\u0004 של המקדש, שהרי לאחר שנתרמה התרומה נחשבים השקלים — בכל מקום שהם ואפילו נגנבו — כרכוש המקדש, ולכן צריכים השליחים להישבע לגזברי המקדש ופטורים מלשלם.","\u0003 ואם לאו\u0004 לא נתרמה תרומה — עדיין נחשבים השקלים בבעלותם של בני העיר ולכן \u0003נשבעין\u0004 השליחים \u0003לבני העיר, ובני העיר שוקלין\u0004 למקדש שקלים \u0003אחרים תחתיהן.\u0004","ואם \u0003נמצאו\u0004 השקלים שאבדו \u0003או שהחזירום הגנבים — אלו ואלו שקלים הם\u0004 וקדושת שקלים עליהם, \u0003אבל אין עולין להן\u0004 לחשבון ה\u0003שנה הבאה.\u0004 שבשנה הבאה חייבים בני אותה העיר להביא שקלים אחרים נוספים על אלו, ולא יצאו ידי חובתם בכך שנתנו פעמיים בשנה זו. \u0003ר' יהודה אומר: עולין להן לשנה הבאה.\u0004","ושואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יהודה? אמר רבא: קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' יהודה חובות של שנה זו קריבות\u0004 גם \u0003לשנה הבאה\u0004 ולכן שקלים שהן חובה לשנה זו אפשר לצאת בהם אף בשנה הבאה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי:\u0004 שנינו: \u0003פר ושעיר של יום הכפורים שאבדו, והפריש אחרים תחתיהן, וכן שעירי\u0004 כפרה על חטא הציבור ב\u0003עבודה זרה\u0004 על פי הוראת בית דין \u0003שאבדו והפריש אחרים תחתיהן — כולן\u0004 אם נמצאו לאחר מכן — \u0003ימותו,\u0004 ואין הם קרבים לשנה הבאה, אלו \u0003דברי ר' יהודה. ר' אליעזר ור' שמעון אומרים: ירעו עד שיסתאבו\u0004 (יפול בהם מום) ואז \u0003ימכרו, ויפלו דמיהם לנדבה,\u0004 לפי \u0003שאין חטאת צבור מתה\u0004 אלא רועה עד שיפול בה מום. ואם אפשר להקריב את הפר ואת השעיר לשנה הבאה מדוע איפוא ימותו? יעכבום לשנה הבאה ויקריבום לחובת יום הכיפורים הבא! \u0003אמר ליה\u0004 \u0005[לו]:\u0006"],["\u0003קרבנות צבור קא אמרת\u0004 \u0005[אמרת]?\u0006 מהם אין להביא ראיה, \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003קרבנות צבור\u0004 שבהן מתקיים הדין שאמר \u0003ר' טבי אמר ר' יאשיה.\u0004 ש\u0003אמר ר' טבי אמר ר' יאשיה: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"זאת עלת חדש בחדשו\"\u0004 (במדבר כח, יד), ומכפילות הלשון יש להבין כי \u0003אמרה\u0004 ה\u0003תורה\u0004 ולמדה בכך\u0003: חדש והבא לי קרבן מתרומה חדשה,\u0004 ומכאן שקרבנות ציבור יש להביאם מתרומה חדשה, ואין להמתין להם לשנה הבאה, אבל שקלים שנועדים למטרות שונות ולא רק לקרבנות ציבור אפשר היה שיביאום גם לשנה הבאה.","על תירוץ זה מקשים: \u0003הא תינח\u0004 \u0005[זה נוח]\u0006 לגבי ענין ה\u0003שעיר\u0004 של יום הכיפורים שהוא מקרבנות הציבור ובא מתרומת הלשכה, אולם לגבי \u0003פר\u0004 של כהן גדול שהוא מרכושו הפרטי של הכהן הגדול ונחשב כקרבן יחיד, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003גזירה\u0004 גזרו ב\u0003פר אטו\u0004 \u0005[משום]\u0006 ה\u0003שעיר.\u0004","ותוהים: \u0003ומשום גזירה ימותו?\u0004 וכי רק מפני גזירה יגרמו שימותו הקדשים? הרי יכולים להניחם שירעו! \u0003ועוד\u0004 יש להקשות: \u0003הא\u0004 \u0005[זו,\u0006 ההלכה\u0005]\u0006 של \u0003ר' טבי אמר ר' יאשיה גופה\u0004 \u0005[\u0006היא \u0005עצמה]\u0006 \u0003מצוה היא\u0004 מלכתחילה ואינה לעכב. שכן \u0003אמר רב יהודה אמר שמואל: קרבנות צבור הבאין באחד בניסן — מצוה להביא מן החדש,\u0004 מן השקלים שתרמו בשנה זו \u0003ואם הביא מן הישן — יצא, אלא שחסר מצוה\u0004 זו של תרומה חדשה. וקשה לומר שמשום דבר זה, שאינו מעכב כלל, יגזרו גזירה שפר של כהן גדול ימות!","\u0003אלא\u0004 יש לדחות תירוץ זה ולומר שהסיבה במיתת פרו של הכהן הגדול היא אחרת וכפי ש\u0003אמר ר' זירא: לפי שאין הגורל קובע משנה לחברתה\u0004 שיפה כוחו של הגורל רק לשנה אחת ולא לשנה הבאה, ולכן אין השעיר שנקבע בהגרלה לשנה זו ראוי לשנה הבאה. ושואלים: \u0003ונייתי\u0004 \u0005[ונביא אותו]\u0006 את השעיר הזה \u0003ונגריל\u0004 יחד עם השעיר השני? ומשיבים: \u0003גזירה שמא יאמרו הגורל קובע משנה לחברתה.\u0004","ומקשים: \u0003הא תינח\u0004 \u0005[זה נוח]\u0006 לענין ה\u0003שעיר,\u0004 אולם לגבי ה\u0003פר\u0004 של הכהן הגדול \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 על זה, שהרי הוא לא בא בהגרלה? ומשיבים: \u0003גזירה\u0004 ב\u0003פר אטו\u0004 \u0005[משום]\u0006 ה\u0003שעיר.\u0004 ומקשים שוב: \u0003ומשום גזירה ימותו?\u0004 ולכן יש לדחות אף תירוץ זה.","\u0003אמרוה רבנן קמיה\u0004 \u0005[אמרו חכמים לפני]\u0006 \u0003אביי\u0004 תירוץ אחר: הרי זו \u0003גזירה משום חטאת שמתו בעליה\u0004 שהרי יתכן שימות הכהן הגדול בשנה זו. ומשיבים: \u0003הא תינח\u0004 \u0005[זה נוח]\u0006 לגבי ה\u0003פר,\u0004 שיש לחשוש למות בעליו, אלא \u0003שעיר\u0004 שהוא קרבן הציבור \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003גזירה\u0004 ב\u0003שעיר אטו\u0004 \u0005[משום]\u0006 ה\u0003פר.\u0004","ומקשים שוב: \u0003ומשום גזירה ימותו? אלא\u0004 יש לומר: \u0003גזירה\u0004 היא \u0003משום חטאת שעברה שנתה,\u0004 שכל בהמה שעברה עליה שנתה הראשונה שוב אינה כשרה להיקרב חטאת. וכאן יש לחשוש שמא עד יום הכיפורים תעבור שנתו של שעיר זה ויפסל. ותוהים: אם כבר הגענו לנימוק זה, איזה מקום אם כן יש ללשון גזירה כאן? וכי \u0003גזירה\u0004 היא זו, הלא \u0003היא גופה חטאת שעברה שנתה היא,\u0004 שהרי שעיר זה יהיה בשנה הבאה יותר מבן שנה!","ודוחים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 כי יתכן שאף כעבור שנה לא יהא עדיין שעיר זה פסול, והדבר יכול להיות על פי שיטת \u0003רבי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר בענין פדיון בתים בערי חומה: \u0003\"\u0004ואם לא יגאל עד מלאת לו \u0003שנה תמימה\"\u0004 (ויקרא כה, ל) הרי הוא \u0003מונה שלש מאות וששים וחמשה יום כמנין ימות החמה, דברי רבי, וחכמים אומרים: מונה שנים עשר חדש מיום ליום.\u0004 ולשיטת רבי אם היה השעיר ביום הכיפורים זה, פחות מבן אחד עשר יום, הרי ביום הכיפורים הבא (אם לא נתעברה השנה) הוא פחות מבן שלוש מאות שישים וחמישה יום, ולדעת רבי עדיין הוא כשר מצד גילו. אלא משום גזירה של שעירים אחרים פסלוהו."],["\u0003ואם נתעברה\u0004 השנה הרי לדעת חכמים \u0003נתעברה למוכר,\u0004 ויש לו חודש נוסף שרשאי לגאול לעצמו את ביתו. ושואלים: \u0003התינח\u0004 \u0005[נניח,\u0006 זה נוח\u0005]\u0006 לענין \u0003שעיר,\u0004 ואולם לגבי \u0003פר מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי הפר כשר גם לאחר שנה! ומשיבים: \u0003גזירה\u0004 ב\u0003פר אטו\u0004 \u0005[משום]\u0006 \u0003שעיר.\u0004","ומקשים כמקודם: \u0003ומשום גזירה ימות?! ועוד\u0004 יש להקשות על תירוץ זה מעיקרו, שאם הוא משום שעברה שנתו הלא \u0003חטאת שעברה שנתה לרעיה אזלא\u0004 \u0005[\u0006היא \u0005הולכת]!\u0006 ש\u0003אמר ריש לקיש: חטאת שעברה שנתה, רואין אותה כאילו היא עומדת בבית הקברות\u0004 ואין הכהן יכול להוציאה משם, שהרי אינו רשאי להיטמא, \u0003ורועה\u0004 עד שיפול בה מום.","\u0003אלא אמר רבא:\u0004 טעם הדבר שאין משהים את הקרבנות משנה אחת לחברתה הריהו \u0003גזירה משום תקלה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 שחוששים לתקלה: \u0003אין מקדישין\u0004 דבר למקדש, \u0003ואין מעריכין\u0004 (סוג של הקדש, שאומר: \"ערך פלוני עלי\") \u0003ואין מחרימין\u0004 אין עושין חרם לקודש \u0003בזמן הזה,\u0004 שהרי אין המקדש קיים.","\u0003ואם הקדיש והעריך והחרים,\u0004 אם \u0003בהמה\u0004 הקדיש — \u0003תיעקר\u0004 כלומר יעשה שתמות מהרה. אם \u0003פירות כסות וכלים\u0004 הקדיש — יגנזם עד ש\u0003ירקבו,\u0004 ואם \u0003מעות וכלי מתכות\u0004 הקדיש — יפדם, ו\u0003יוליך הנאה לים המלח.\u0004 ומסבירים: \u0003ואי זה הוא עיקור — נועל דלת לפניה, והיא מתה מאליה\u0004 ברעב.","ושואלים: בעצם \u0003תקלה דמאי\u0004 \u0005[של מה],\u0006 כלומר: לאיזו תקלה חוששים אם יניחו לפר ולשעיר להמתין עד לשנה הבאה? \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהיא \u0003תקלה\u0004 של \u0003הקרבה,\u0004 שמא יקריבו אותה בטעות לקרבן אחר, אם כן \u0003אפילו כל רעיות,\u0004 כל בהמות הפסולות שאמרו חכמים שתרענה עד שיפול בהן מום \u0003נמי\u0004 \u0005[גם כן]\u0006 נחשוש לכך! \u0003אי\u0004 \u0005[אם\u0006 תאמר\u0005]\u0006 שחשש ה\u0003תקלה\u0004 הוא שמא יבואו לידי \u0003גיזה\u0004 של צמרן \u0003ועבודה\u0004 בהן, שיש בכך מעילה בקדשים, אם כן \u0003אפילו\u0004 ב\u0003כל רעיות\u0004 אחרות \u0003נמי\u0004 \u0005[גם כן]\u0006 יש לחשוש לכך, ומדוע גוזרים דווקא באלה שימותו?","ומשיבים: \u0003לעולם\u0004 החשש הוא משום \u0003תקלה\u0004 של \u0003הקרבה. והנך\u0004 \u0005[ואותם,\u0006 האחרים\u0005]\u0006 \u0003דלאו\u0004 \u0005[שאין]\u0006 \u0003בני הקרבה נינהו\u0004 \u0005[הם]\u0006 כלל, שהרי צריכים לרעות עד שיפול בהם מום \u0003לא טריד בהו\u0004 \u0005[טרוד,\u0006 עסוק \u0005בהן]\u0006 ומניחים אותן לרעות. \u0003הך\u0004 \u0005[זו]\u0006 ש\u0003בת הקרבה היא,\u0004 שראויה היא להקרבה, הרי נצטרך להקריב את הבהמות הללו ליום הכיפורים בשנה הבאה — הרי הוא \u0003טריד\u0004 \u0005[טרוד]\u0006 \u0003בה\u0004 וכיון שדואגים ומטפלים בהם יש לחשוש שמא ישכחו ויקריבום שלא בזמנם.","ומעירים: וענין זה אם חוששים ל\u0003תקלה עצמה תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא. דתניא חדא\u0004 \u0005[ששנויה\u0006 ברייתא \u0005אחת]:\u0006 קרבן \u0003פסח שלא קרב\u0004 משום מה \u0003ב\u0004פסח \u0003ראשון —\u0004 ימכר למי שהיה טמא בפסח ראשון או שהיה בדרך רחוקה ו\u0003יקרב ב\u0004פסח \u0003שני.\u0004 לא הוקרב \u0003ב\u0004פסח \u0003שני — יקרב לשנה הבאה. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 אם לא הוקרב בפסח שני — \u0003לא יקרב\u0004 לשנה הבאה. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003ב\u0004שאלה הזו אם חוששים ל\u0003תקלה פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 שחכם אחד סבור שחוששים ולכן אין ממתינים, והאחר אומר שממתינים.","ודוחים: \u0003לא\u0004 ניתן להוכיח מכאן, כי אפשר לומר \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים]\u0006 \u0003לתקלה, והכא בפלוגתא\u0004 \u0005[וכאן ב\u0006אותה \u0005מחלוקת]\u0006 של \u0003רבי ורבנן קא מיפלגי\u0004 \u0005[הוא שחולקים],\u0006 אם מונים שנה לימות החמה אם לא, \u0003ולא קשיא\u0004 \u0005[ואינו קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 הברייתא שנאמר שמביאים אותו לשנה הבאה היא כשיטת \u0003רבי, הא\u0004 \u0005[זו]\u0006 האומרת שאין ממתינין היא כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 שלשנה הבאה כבר עברה שנתו של שה הקרבן, ואינו ראוי איפוא לפסח.","על דחיה זו מקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003וכן המעות\u0004 שהוקדשו לפסח. ובהם ודאי אין מקום לומר שעברה שנתם, ואין מקום איפוא למחלוקת רבי וחכמים! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא נלמד מכאן]\u0006 כי \u0003בתקלה פליגי\u0004 \u0005[נחלקו]!\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","בהמשך סדר עבודת הכהן הגדול ביום הכיפורים, היה הכהן הגדול \u0003בא לו אצל\u0004 ה\u0003שעיר המשתלח, וסומך שתי ידיו עליו ומתודה. וכך היה אומר: \"אנא השם! חטאו, עוו, פשעו לפניך עמך בית ישראל. אנא השם! כפר נא לחטאים ולעונות ולפשעים שחטאו ושעוו ושפשעו לפניך עמך בית ישראל, ככתוב בתורת משה עבדך לאמר: \"כי ביום הזה יכפר עליכם לטהר אתכם מכל חטאתיכם לפני ה' תטהרו\"\u0004 (ויקרא טז, ל).","\u0003והכהנים והעם העומדים בעזרה כשהיו שומעים שם המפורש שהוא יוצא מפי כהן גדול,\u0004 כשהיה מבטא את השם בפסוק זה בפירושו ולא בכינויו, \u0003היו כורעים ומשתחוים ונופלים על פניהם, ואומרים: \"ברוך שם כבוד מלכותו לעולם ועד\".\u0004 לאחר הוידוי על השעיר לעזאזל \u0003מסרו\u0004 הכהן \u0003למי שהיה מוליכו\u0004 אל המדבר. \u0003הכל כשרין\u0004 על פי דין \u0003להוליכו, אלא שעשו הכהנים\u0004 ה\u0003גדולים קבע\u0004 (מנהג קבוע) לעצמם, \u0003ולא היו מניחין את ישראל להוליכו.\u0004","\u0003אמר ר' יוסי:\u0004 אף על פי כן לא תמיד היה כך, אלא \u0003מעשה והוליכו\u0004 אדם אחד ושמו \u0003ערסלא, וישראל היה. וכבש\u0004 (גשר) שיעבירו אותו מעל לעם \u0003עשו לו\u0004 לשעיר, \u0003מפני הבבליים\u0004 (היהודים מבבל שהיו בירושלים). \u0003שהיו\u0004 הבבליים \u0003מתלשים בשערו\u0004 של השעיר \u0003ואומרים לו: טול וצא טול וצא\u0004 ולא תשהה עוונותינו אצלנו. וכדי שלא יהרגו את השעיר בדרך עשו לו כבש מיוחד זה.","בוידוי זה היה הכהן מתוודה על עוונות ישראל, \u0003ואילו \"בני אהרן עם קדושך\" לא קאמר\u0004 \u0005[אמר]\u0006 בוידוי זה. ושואלים: \u0003מאן\u0004 \u0005[מי הוא]\u0006 \u0003תנא\u0004 זה שזו היא שיטתו? \u0003אמר ר' ירמיה:\u0004 שיטת תנא זה היא ש\u0003לא\u0004 כשיטת \u0003ר' יהודה דאי\u0004 \u0005[שאם]\u0006 תאמר שהיא כשיטת \u0003ר' יהודה, הא\u0004 \u0005[הרי]\u0006 \u0003אמר\u0004 ר' יהודה: \u0003יש להם\u0004 לכהנים \u0003כפרה בשעיר המשתלח,\u0004 ואם כן היו צריכים אף הם להיות מוזכרים בכלל וידוי זה.","\u0003אביי אמר:\u0004 אין מכאן ראיה, \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כי משנתנו כשיטת \u0003ר' יהודה\u0004 היא, \u0003אטו\u0004 \u0005[וכי]\u0006 ה\u0003כהנים לאו\u0004 \u0005[שלא]\u0006 \u0003בכלל \"עמך ישראל\" נינהו\u0004 \u0005[הם]?\u0006 ואין להוכיח דבר ממה שאינו מונה בפרט כל חלק בעם ישראל.","שנינו במשנה: \u0003מסרו\u0004 הכהן \u0003למי שמוליכו\u0004 למדבר. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \"ושילח ביד איש עתי המדברה\" (ויקרא טז, כא), ומפרשים במדרש הלכה: \u0003\"איש\"\u0004 כוונתו — \u0003להכשיר את הזר\u0004 למעשה השילוח, \u0003\"עתי\"\u0004 פירושו"],["\u0003שיהא מזומן\u0004 לכך מאתמול. \u0003\"עתי\"\u0004 משמעו — בזמנו, \u0003ואפילו בשבת, \"עתי\"\u0004 — בזמנו, \u0003ואפילו בטומאה.\u0004","ומפרשים: \u0003\"איש\" — להכשיר את הזר.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט],\u0006 מהיכן יעלה על דעתנו שלא להכשירו? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 הלא לשון \u0003\"כפרה\" כתיבא ביה\u0004 \u0005[נאמרה בו],\u0006 ואין כפרה אלא על ידי כהנים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין זו כפרת קרבנות, וכשרה אף על ידי ישראל.","\u0003\"עתי\" — ואפילו בשבת.\u0004 ושואלים: \u0003למאי הלכתא\u0004 \u0005[לאיזה הלכה]\u0006 נאמר דבר זה, שלכאורה אין חילול שבת בהוצאת השעיר? שהרי דין תחומים אינו אלא מדברי סופרים. \u0003אמר רב ששת: לומר, שאם היה\u0004 השעיר \u0003חולה\u0004 ואינו יכול להלך כל דרך זו — \u0003מרכיבו\u0004 המשלח \u0003על כתפו.\u0004","ומעירים: \u0003כמאן\u0004 \u0005[כמי\u0006 אמר זאת\u0005]\u0006 ש\u0003לא כר' נתן. דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' נתן, האמר\u0004 \u0005[הרי אמר]\u0006 ר' נתן כלל: \u0003חי נושא את עצמו\u0004 שהחי מיקל את משאו, ולכך הנושא דבר חי, אינו נחשב כנושא משא, ואף הנושא את השעיר לא יחשב אם כן כנושא משא בשבת. ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003ר' נתן,\u0004 כיון ש\u0003חלה\u0004 השעיר \u0003שאני\u0004 \u0005[שונה\u0006 הדבר\u0005],\u0006 שמאחר שאין השעיר יכול להלך בכוחות עצמו, לכן הנושאו, אף שהוא חי, הרי הוא לדעת הכל כנושא משא. למדנו כי \"עתי\" בא ללמד, שאף בשבת משלחים את השעיר.","\u0003אמר רפרם: זאת אומרת\u0004 כי יש דיני \u0003עירוב והוצאה לשבת,\u0004 אבל \u0003אין\u0004 דיני \u0003עירוב\u0004 ואין איסור \u0003הוצאה ליום הכפורים.\u0004 שאם לא כן — לא היה צריך לפרש שאפילו בשבת יהא מותר לטלטלו, אם גם ביום הכיפורים עצמו אסור הדבר.","\u0003\"עתי\" ואפילו בטומאה.\u0004 ושואלים: \u0003למאי הלכתא\u0004 \u0005[לאיזו הלכה\u0006 נאמר הדבר\u0005]?\u0006 \u0003אמר רב ששת: לומר שאם נטמא משלחו\u0004 של השעיר \u0003נכנס\u0004 אפילו כשהוא \u0003טמא לעזרה, ומשלחו.\u0004","כיון שהוזכרה בעיה זו בשעיר מביאים מעשה ש\u0003שאלו את ר' אליעזר: חלה\u0004 השעיר \u0003מהו שירכיבהו\u0004 המשלחו \u0003על כתפו? אמר להם: יכול הוא\u0004 השעיר \u0003להרכיב אני ואתם\u0004 כלומר, בריא היה השעיר, ולא יזדמן שיחלה. ולא ענה על השאלה שנשאל. שאלוהו: \u0003חלה משלחו\u0004 של השעיר \u0003מהו שישלחנו ביד אחר? אמר להם\u0004 בדחייה: \u0003אהא בשלום אני ואתם,\u0004 שאין הדבר מצוי כלל.","ועוד שאלוהו: \u0003דחפו\u0004 לשעיר \u0003ולא מת\u0004 בנפילתו, \u0003מהו שירד אחריו וימיתנו? אמר להם: \"כן יאבדו כל אויביך ה'\"\u0004 (שופטים ה, לא), כלומר: בודאי ימות בעצמו. שר' אליעזר לא רצה לענות על שאלות אלה, וכפי שיבואר להלן. אולם \u0003חכמים אומרים:\u0004 אם \u0003חלה\u0004 השעיר — \u0003מרכיבו\u0004 המשלח \u0003על כתפו, חלה משלחו — ישלחנו ביד אחר. דחפו ולא מת — ירד אחריו וימיתנו.\u0004 ומביאים עוד שאלות ששאלו את ר' אליעזר וענה עליהם בדחיה.","\u0003שאלו את ר' אליעזר: פלוני,\u0004 אדם מסויים שהיה ידוע כרשע, \u0003מהו לעולם הבא?\u0004 התחמק וענה: \u0003לא שאלתוני אלא על פלוני\u0004 אדם אחר שהוא בעיניכם כצדיק.","שאלוהו: \u0003מהו\u0004 הדין בענין \u0003להציל\u0004 על ידי \u0003רועה כבשה מן הארי\u0004 בשבת? (מאירי) \u0003אמר להם: לא שאלתוני אלא על הכבשה.\u0004 שאלוהו: \u0003מהו להציל הרועה מן הארי\u0004 בשבת? \u0003אמר להם: לא שאלתוני אלא על הרועה.\u0004 שאלוהו: \u0003ממזר מהו לירש\u0004 כלומר האם יורש הוא את אביו, למרות היותו פסול? ענה להם בשאלה: האם לא שאלתוני \u0003מהו ליבם?\u0004 ושאלוהו \u0003מהו,\u0004 האם מותר בזמן הזה לאדם לאחר שנחרב בית המקדש \u0003לסוד את ביתו?\u0004 ענה להם: \u0003מהו לסוד את קברו?\u0004","ומעירים: \u0003לא מפני שהפליגן בדברים,\u0004 שרצה להתחמק מלענות ואמר דברים סתם מפני שלא ידע לענות. \u0003אלא מפני שלא אמר\u0004 ר' אליעזר \u0003דבר שלא שמע מפי רבו לעולם,\u0004 וכיון שבעניינים אלו לא שמע במפורש מפי רבו, לא היה עונה על כך במישרין, שיבינו שעל נושאים אלה אין בידו תשובה מקובלת. כיוצא בו מביאים שאלה אחרת ששאלו את ר' אליעזר.","\u0003שאלה אשה חכמה את ר' אליעזר: מאחר שמעשה העגל שוין\u0004 וכולם חטאו בו, \u0003מפני מה אין מיתתן\u0004 של כולם \u0003שוה?\u0004 אלא מהם נהרגו בחרב על ידי משה והלוים, ומהם במגפה ומהם במחלות מעיים (הדרוקן)! \u0003אמר לה: אין חכמה לאשה אלא\u0004 בטויה \u0003בפלך, וכן הוא אומר: \"וכל אשה חכמת לב בידיה טוו\"\u0004 (שמות לה, כה), ואם כן אין ראוי לאשה לעסוק בשאלות אלו.","לגופו של ענין \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו האמוראים \u0003רב ולוי\u0004 בדבר. \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 מי ש\u0003זיבח וקיטר\u0004 לעגל שעשה עבודה זרה ממש, שחייבים עליה מיתה בידי אדם — נידון \u0003בסייף\u0004 (חרב). מי ש\u0003גפף ונישק\u0004 שלא עשה עבודות שחייבים עליהן מיתה בידי אדם — נענש \u0003במיתה\u0004 במגיפה בידי שמים. מי ש\u0003שמח בלבבו\u0004 ולא עשה מעשה — נדון \u0003בהדרוקן\u0004 (מחלת מעיים).","\u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 מי שהיו \u0003עדים והתראה\u0004 שאכן עבד לעגל — נדון \u0003בסייף, עדים בלא התראה — במיתה\u0004 במגיפה, \u0003לא עדים ולא התראה — בהדרוקן.\u0004","\u0003אמר רב יהודה: שבטו של לוי\u0004 כולו \u0003לא עבד עבודה זרה, שנאמר: \"ויעמד משה בשער המחנה\u0004 ויאמר מי לה' אלי ויאספו אליו כל בני לוי\u0003\"\u0004 (שמות לב, כו).","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רבינא וקאמר להא שמעתא\u0004 \u0005[ואמר את ההלכה הזאת]\u0006 בענין בני לוי. \u0003איתיביה\u0004 \u0005[הקשו לו]\u0006 \u0003בני רב פפא בר אבא לרבינא:\u0004 הלא נאמר בשבחם של בני לוי: \u0003\"האמר לאביו ולאמו לא ראיתיו\u0004 ואת אחיו לא הכיר ואת בניו לא ידע\u0003\"\u0004 (דברים לג, ט) משמע שחלקם עבדו עבודה זרה והרגום קרוביהם!","והשיב להם: \u0003\"אביו\"\u0004 אין פירושו אביו ממש, אלא \u0003אבי אמו\u0004 שהיה \u0003מישראל, \"אחיו\" — אחיו מאמו\u0004 שהיו \u0003מישראל, \"בניו\" — בני בתו מישראל\u0004 שהם ישראלים, אבל הלויים אכן לא היו בין העובדים לעגל.","שנינו במשנה כי \u0003כבש עשו לו\u0004 לשעיר מפני הבבליים. \u0003אמר רבה בר בר חנה:\u0004 באמת \u0003לא בבליים\u0004 (בני בבל) \u0003היו, אלא אלכסנדריים\u0004 (בני אלכסנדריא שבמצרים) \u0003היו. ומתוך ששונאים\u0004 בארץ ישראל \u0003את הבבליים היו קורין אותן\u0004 את כל הזרים ובכללם בני אלכסנדריא \u0003על שמן\u0004 של הבבליים בכל מקום של גנאי. כיוצא בזה \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' יהודה אומר: לא בבליים היו, אלא אלכסנדריים היו. אמר לו ר' יוסי\u0004 שמוצא משפחתו היה מבבל: \u0003תנוח דעתך, שהנחת את דעתי.\u0004","שנינו במשנה שהיו הבבליים אומרים לשעיר \u0003טול וצא. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא שכך היו אומרים: \u0003מה שהי צפירא דין וחובי דרא סגיאין\u0004 \u0005[מה שוהה שעיר זה\u0006 כאן \u0005וחטאות הדור מרובות],\u0006 אלא ימהר ויצא.","\u0003מיקירי\u0004 (חשובי) \u0003ירושלים היו מלוין אותו\u0004 את המשלח \u0003עד\u0004 ה\u0003סוכה הראשונה,\u0004 שהיו עושים לו בדרך למדבר שיוכל לנוח בהן. \u0003עשר סוכות\u0004 היו \u0003מירושלים ועד צוק,\u0004"],["כשהמרחק ביניהם הוא \u0003תשעים ריס, שבעה ומחצה\u0004 ריס \u0003לכל מיל\u0004 והרי הם בסך הכל שנים עשר מיל. \u0003על כל סוכה וסוכה אומרין לו\u0004 השוהים שם: \u0003הרי מזון, והרי מים,\u0004 שמא זקוק אתה לכך. \u0003ומלוין אותו מסוכה לסוכה, חוץ מאחרון שבהן\u0004 הנמצא בסוכה אחרונה, \u0003שאינו מגיע עמו לצוק, אלא עומד מרחוק ורואה את מעשיו\u0004 אם מקיים את המצוה כדינה.","\u0003מה היה עושה\u0004 שם המשלח? \u0003חולק\u0004 (מחלק) \u0003לשון של זהורית\u0004 לשני חלקים \u0003חציו\u0004 של לשון זה \u0003קשור בסלע, וחציו קשור בין שני קרניו\u0004 של השעיר. \u0003ודחפו\u0004 את השעיר \u0003לאחוריו, והוא מתגלגל ויורד. ולא היה מגיע לחצי ההר עד שנעשה אברים אברים. בא וישב לו\u0004 המשלח \u0003תחת סוכה אחרונה עד שתחשך\u0004 ומשם חוזר לביתו. \u0003ומאימתי מטמא\u0004 המשלח \u0003בגדים,\u0004 שהרי נאמר שהוא טמא וטעון כיבוס בגדים — \u0003משיצא חוץ לחומת ירושלים, ר' שמעון אומר:\u0004 אין בגדיו מיטמאים אלא \u0003משעת דחייתו לצוק.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עשר סוכות\u0004 היו, \u0003ושנים עשר מילין\u0004 היה המרחק מירושלים לצוק, \u0003דברי ר' מאיר. ר' יהודה אומר: רק תשע סוכות\u0004 היו, \u0003ועשרה מילין. ר' יוסי אומר: חמש סוכות, ועשרה מילין היו. וכולן על ידי עירוב\u0004 שמניחים המלוים בין הסוכות מבעוד יום, ועל ידי העירוב רשאי היה המלוה ללכת מסוכה לסוכה.","\u0003אמר ר' יוסי: סח לי אלעזר בני: אם על ידי עירוב — יכולני לעשות אפילו שתי סוכות ועשרה מילין.\u0004 כי על ידי העירוב רשאי אדם להלך לא רק מיל אחד (אלפים אמה) אלא שני מילין, וילווהו בני ירושלים שני מילין, ובני הסוכה יצאו לקראתו שני מילין, ואחרים ילווהו לסוכה שניה שני מילין וכן בסוכה שניה, ובשתי סוכות בלבד יספיק.","ומעירים: \u0003כמאן אזלא\u0004 \u0005[כשיטת מי הולכת]\u0006 \u0003הא דתניא\u0004 הלכה זו האומרת שבני כל הסוכות היו הולכים ללוותו \u0003חוץ מאחרון שבהן שלא הגיע עמו לצוק אלא עומד מרחוק ורואה את מעשיו — כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר,\u0004 שאחרון זה מרוחק היה מן הצוק יותר משיעור תחום שבת, ולכן לא יכול ללוותו עד הצוק ממש.","נאמר במשנה כי \u0003על כל סוכה וסוכה אומרים לו\u0004 הדרים בה: \u0003הרי מזון והרי מים. תנא\u0004 \u0005[שנה,\u0006 החכם\u0005]:\u0006 \u0003מעולם לא הוצרך אדם לכך,\u0004 שלא היה משלח שהוזקק ממש לאכול. ומפני מה היו בכל זאת אומרים לו כן — \u0003אלא שאינו דומה מי שיש לו פת בסלו, למי שאין לו פת בסלו,\u0004 שמי שאין לו פת מוכן בסלו, מתוך שהוא חושש שלא יוכל למצוא מאכל, הריהו מרגיש יותר רעב וצמא.","שנינו במשנה: \u0003מה היה עושה — חולק לשון של זהורית,\u0004 וקושר חציו בסלע וחציו בין קרני השעיר. ושואלים: \u0003ונקטריה כוליה\u0004 \u0005[ושיקשור\u0006 את כל הלשון \u0005כולה]\u0006 \u0003בסלע?\u0004 ומשיבים: \u0003כיון\u0004 ש\u0003מצוה בשעיר\u0004 לדוחפו מן הצוק, \u0003דילמא קדים ומלבין\u0004 \u0005[שמא תקדים\u0006 לשון הזהורית \u0005ותלבין]\u0006 \u0003ומיתבא דעתיה\u0004 \u0005[ותתיישב דעתו]\u0006 ויהא מרוצה שנמחלו עוונות ישראל ולא ישים לב לקיום מצוות דחיפת השעיר כראוי לה, לכך עליו לקשור חלקה גם בין קרני השעיר ומתוך שיביט בו כדי לראות אם הלבינה לשון הזהורית שבראשו יזכור שמוטלת עליו עדיין החובה לדוחפו מן הצוק.","ושואלים: אם כן \u0003ונקטריה כוליה\u0004 \u0005[ושיקשור את כולו]\u0006 \u0003בין קרניו\u0004 של השעיר? ומשיבים: \u0003זימנין דגמיש ליה לרישיה, ולא אדעתיה\u0004 \u0005[פעמים ש\u0006השעיר \u0005מעקם את ראשו, ו\u0006אז \u0005אין לדעת]\u0006 אם הלבין או לא הלבין.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בראשונה היו קושרין לשון\u0004 זו \u0003של זהורית על פתח האולם מבחוץ, הלבין\u0004 הלשון — \u0003היו שמחין\u0004 שהתכפרו עוונותיהם, \u0003לא הלבין — היו עצבין ומתביישין.\u0004 כיון שראו שבאים לידי עצבות יתירה בחג — \u0003התקינו שיהיו קושרין על פתח אולם מבפנים\u0004 שרק מעטים רשאים להיכנס שם לראות. \u0003ועדיין היו מציצין ורואין, הלבין — היו שמחין, לא הלבין — היו עצבין. התקינו שיהיו קושרין אותו חציו בסלע וחציו בין קרניו\u0004 של השעיר, שלא ידע כל העם מה אירע בלשון עד מוצאי היום.","\u0003אמר ר' נחום בר פפא משום ר' אלעזר הקפר: בראשונה היו קושרין לשון של זהורית על פתח אולם מבפנים, וכיון שהגיע שעיר למדבר\u0004 מיד \u0003היה מלבין, וידעו שנעשית מצותו.\u0004 ורמז לענין זה של קשירת לשון הזהורית — \u0003שנאמר: \"אם יהיו חטאיכם כשנים כשלג ילבינו\u0004 אם יאדימו כתולע כצמר יהיו","נאמר במשנה כי \u0003לא היה\u0004 השעיר \u0003מגיע למחצית ההר\u0004 עד שהיה נעשה אברים אברים. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003אותן אברים מה הן בהנאה?\u0004 האם מותר ליהנות מהם או שמא אסורין הן? נחלקו בכך \u0003רב ושמואל. חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: מותרין\u0004 בהנא, \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: אסורין.\u0004","ומסבירים טעמיהם: \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר מותרין\u0004 הן בהנאה,"],["ראייתו היא ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"במדבר\"\u0004 (ויקרא טז, כב), כלומר: הפקר לכול כמו המדבר. \u0003ומאן\u0004 \u0005[ומי]\u0006 ש\u0003אמר\u0004 ש\u0003אסורין\u0004 הן, הוא משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"גזרה\"\u0004 (ויקרא טז, כב), משמע: חומרה ואיסור יש בדבר.","ושואלים: \u0003ומאן\u0004 \u0005[ומי]\u0006 ש\u0003אמר אסורין, האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"מדבר\" מאי עביד ליה\u0004 \u0005[מה עושה הוא בו],\u0006 מה הוא למד ממנו? ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[דרוש הוא לו לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר בענין השעיר המשתלח שלש פעמים \u0003\"המדברה\"\u0004 (ויקרא טז, י) \u0003\"המדברה\"\u0004 (ויקרא טז, כא) \u0003\"במדבר\"\u0004 (ויקרא טז, כב), ודבר זה בא \u0003לרבות\u0004 את \u0003נוב וגבעון,\u0004 ו\u0003שילה\u0004 בתקופה שהיו מקריבים בהם קרבנות, \u0003ובית עולמים\u0004 שמצוה זו נוהגת בכולם.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 \u0003האי\u0004 \u0005[\u0006מילה \u0005זו]\u0006 \u0003\"גזרה\" מאי עביד ליה\u0004 \u0005[מה עושה הוא בה]?\u0006 ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[דרוש הוא לו לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"גזירה\" — אין גזירה אלא חתוכה.\u0004 כלומר: שצריך להשליכו במקום שהוא מחותך על ידי סלעים זקופים ובולטים. \u0003דבר אחר: אין גזרה אלא דבר המתגזר ויורד,\u0004 שהוא","השעיר שמתגזר לאיברים איברים. \u0003דבר אחר: \"גזרה\" שמא תאמר מעשה\u0004 של \u0003תהו הוא,\u0004 וכי איזו קדושה וכפרה יש בשילוח השעיר לעזאזל ובדחייתו מן הצוק? \u0003תלמוד לומר: \"אני ה'\"\u0004 (ויקרא יח, ה), כלומר: \u0003אני ה' גזרתיו, ואין לך רשות להרהר בהן.\u0004 עד כאן עסקו בבירור המחלוקת.","ולסיכומה \u0003אמר רבא: מסתברא\u0004 \u0005[מסתבר]\u0006 \u0003כ\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שאיברים אלה \u0003מותרין,\u0004 כי \u0003לא אמרה תורה\u0004 \"ו \u0003שלח\u0004 את השעיר\" \u0003לתקלה,\u0004 שאם אמרה התורה סתם לשלח, הרי שמכאן והלאה אינם באחריותו ומסתבר שאין בהם איסור, שתיגרם על ידי כך אפשרות של תקלה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"עזאזל\"\u0004 משמע — \u0003שיהא\u0004 המקום \u0003עז וקשה. יכול\u0004 ישלחנו במקום \u0003ישוב — תלמוד לומר: \"במדבר\", ומנין\u0004 שעושים זאת \u0003בצוק\u0004 (בסלע) — \u0003תלמוד לומר: \"גזרה\"\u0004 כלומר דבר הגוזר וחותך, כמו צוק. \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 באותו נושא: \u0003\"עזאזל\" — קשה שבהרים, וכן הוא אומר: \"ואת אילי הארץ לקח\"\u0004 (יחזקאל יז, יג) שעזאזל נדרש כמו \"עזז-אל\" לשון קושי ותוקף.","\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: \"עזאזל\"\u0004 נקרא כן מפני שהוא \u0003מכפר על מעשה עוזא ועזאל,\u0004 שהם שמות בני האלהים שחטאו בבנות האדם, והחטיאו את העולם בדור המבול.","בנושא זה מביאים עוד ברייתא: \u0003תנו רבנן, \"את משפטי תעשו\u0004 ואת חוקותי תשמרו ללכת בהם אני ה' אלהיכם\u0003\"\u0004 (ויקרא יח, ד), \"משפטי\" אלה \u0003דברים שאלמלא נכתבו דין הוא שיכתבו\u0004 מפני שהדעת מחייבת אותם, \u0003ואלו הן: עבודה זרה, וגלוי עריות, ושפיכות דמים, וגזל, וברכת\u0004 (קללת) \u0003השם.\u0004","אבל \u0003\"ואת חקתי תשמרו\"\u0004 (ויקרא יח, ד) — אלו \u0003דברים שהשטן\u0004 ואומות העולם \u0003משיב\u0004ים \u0003עליהן\u0004 משום שאין להם טעם מובן, \u0003ואלו הן:\u0004 איסור \u0003אכילת חזיר, ולבישת שעטנז,\u0004 ומצות \u0003חליצת יבמה, וטהרת מצורע, ושעיר המשתלח. ושמא תאמר\u0004 אלה שאין להם טעם ו\u0003מעשה תוהו הם — תלמוד לומר: \"אני ה'\"\u0004 (ויקרא יח, ד), לומר: \u0003אני ה' חקקתיו, ואין לך רשות להרהר בהן\u0004 לערער עליהן.","במשנה נחלקו תנאים \u0003אימתי מטמא\u0004 המשלח את השעיר את ה\u0003בגדים\u0004 שלו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003המשלח\u0004 עצמו \u0003מטמא בגדים ואין השולח את המשלח\u0004 כגון המלוים אותו \u0003מטמא בגדים.\u0004","\u0003יכול משיצא חוץ לחומת עזרה\u0004 מיד יטמא — \u0003תלמוד לומר: \"המשלח\",\u0004 שאינו מטמא עד שיהא משלחו בכיוון היעד. ומצד אחר \u0003אי\u0004 \u0005[אם]\u0006 אומר אתה \u0003\"המשלח\" — יכול עד שיגיע לצוק\u0004 לא יטמא — \u0003תלמוד לומר: \"והמשלח\",\u0004 האות \"ו\" באה לרבות. \u0003הא כיצד:\u0004 אינו מטמא בגדים אלא \u0003משיצא חוץ לחומת ירושלים.\u0004 אלו \u0003דברי ר' יהודה,\u0004 ואילו","\u0003ר' יוסי אומר:\u0004 נאמר \u0003\"\u0004והמשלח את השעיר \u0003לעזאזל וכבס\"\u0004 (ויקרא יח, כה) משמע: עד שיגיע לעזאזל, ש\u0003עד שהגיע לצוק\u0004 אינו מטמא. \u0003ר' שמעון אומר:\u0004 אינו מטמא בגדים אלא בשעת דחיפתו מן הצוק, שהרי נאמר: \u0003\"והמשלח את השעיר לעזאזל יכבס בגדיו\"\u0004 (ויקרא טז, כו) ללמד ש\u0003זורקו בבת ראש\u0004 (בבת אחת) ואז \u0003מטמא בגדים,\u0004 שזו היא מצות שילוחו, ורק לאחריה מטמא.","לאחר שמסר הכהן הגדול את השעיר המשתלח ביד מי שמשלחו \u0003בא לו\u0004 הכהן הגדול \u0003אצל פר ושעיר הנשרפין, קרען\u0004 ואין צריך לחותכן ולנתחן, \u0003והוציא את אימוריהן\u0004 (החלקים העולים להקרב למזבח) \u0003נתנן במגיס\u0004 (קערה גדולה) \u0003והקטירן על גבי המזבח.\u0004","\u0003קלען\u0004 צרפן וקשרם, את הפר והשעיר, כעין \u0003מקלעות\u0004 (כגוש אחד), כשהם מונחים כך על שני מוטות הנישאים ביד ארבעה בני אדם \u0003והוציאן לבית השריפה\u0004 שהיה מחוץ לירושלים. \u0003ומאימתי מטמאין\u0004 הפר והשעיר הללו \u0003בגדים\u0004 של הנושאים אותם ככתוב: \"והשורף אותם יכבס בגדיו\" (ויקרא טז, כח) — \u0003משיצאו חוץ לחומת העזרה. ר' שמעון אומר:\u0004 לא כן, אלא בשעה שנשרפים ממש, ש\u0003משיצית האור ברובן\u0004 הרי הם מטמאים.","נאמר במשנה שלאחר שהוציא את איבריהם נתנם לאיברים במגיס והקטירן. ותוהים: \u0003\"והקטירן\" סלקא דעתך\u0004 \u0005[עולה על דעתך\u0006 לומר\u0005]?\u0006 שהרי אינו מקטירן מיד וצריך לעשות תחילה עבודות אחרות, \u0003אלא אימא\u0004 \u0005[אמור]\u0006 שמניחם במגיס על מנת \u0003להקטירן\u0004 מאוחר יותר \u0003על גבי\u0004 ה\u0003מזבח.\u0004","נאמר במשנה שלפני הוצאת הפר והשעיר לשריפה \u0003\"קלען במקלעות\". אמר ר' יוחנן:\u0004 שהיה עושה אותם \u0003כמין קליעה\u0004 שחלקיה מחוברים זה לזה. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003לא היה מנתחן\u0004 את הפר והשעיר כ\u0003ניתוח בשר עולה\u0004 שמפשיטים את העור ומנתחים את כל הבהמה לנתחיה, אלא חותך \u0003עור על גבי בשר\u0004 ולא היה מפשיטם. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003רבי אומר: נאמר כאן\u0004 בפר ושעיר אלה \u0003'עור ובשר ופרש'\u0004 (ויקרא טז, כז) \u0003ונאמר להלן\u0004 בפרי חטאת הנשרפים \u0003'עור ובשר ופרש'\u0004 (ויקרא ד, יא),"],["\u0003מה להלן, על ידי ניתוח ולא על ידי הפשט — אף כאן, על ידי ניתוח ולא על ידי הפשט.\u0004","ושואלים: \u0003והתם\u0004 \u0005[ושם]\u0006 בפרים הנשרפים \u0003מנא לן\u0004 \u0005[מניין לנו]\u0006 שהיה ניתוח בלא הפשט? ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \"ואת עור הפר ואת כל בשרו על ראשו ועל כרעיו \u0003וקרבו ופרשו והוציא\u0004 את כל הפר אל מחוץ למחנה אל מקום טהור אל שפך הדשן ושרף אותו\" (ויקרא ד, יא-יב) — \u0003מלמד שמוציאו שלם. יכול ישרפנו שלם\u0004 כמו שהוא? \u0003נאמר כאן \"ראשו וכרעיו\" ונאמר להלן\u0004 בקרבן העולה \u0003\"ראש וכרעים\", מה להלן\u0004 בעולה \u0003על ידי ניתוח\u0004 כמפורש בכתוב, \u0003אף כאן על ידי ניתוח.\u0004","ויש להקשות: \u0003אי\u0004 \u0005[או]\u0006 \u0003מה להלן\u0004 בעולה הניתוח הוא \u0003על ידי הפשט, אף כאן על ידי הפשט,\u0004 שצריך להפשיט את עור הבהמות קודם שריפתם, \u0003תלמוד לומר: \"וקרבו ופרשו\".\u0004 ושואלים: \u0003מאי תלמודא\u0004 \u0005[מה הלימוד\u0006 בכך\u0005],\u0006 כיצד נובע מן המילים \"וקרבו ופרשו\" שיש להקריבו כמות שהוא? \u0003אמר רב פפא:\u0004 יש כאן כעין היקש, \u0003כשם שפרשו בקרבו\u0004 ואין מוציאים אותו, \u0003כך בשרו בעורו\u0004 ואין מוציאים את העור לבדו.","שנינו במשנה שנחלקו תנאים \u0003מאימתי מטמאין\u0004 שורפי הפר והשעיר את ה\u0003בגדים. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \u0003\"\u0004ואת פר החטאת ואת שעיר החטאת אשר הובא את דמם לכפר בקודש \u0003יוציא אל מחוץ למחנה ושרפו\"\u0004 (ויקרא טז, כז).","ויש לתמוה: \u0003להלן\u0004 בדין שאר פרים הנשרפים \u0003אתה נותן להם שלש מחנות\u0004 ששורפים את הפרים מחוץ למחנה ישראל (או חוץ לירושלים במקום המקדש), \u0003וכאן אתה נותן להם\u0004 רק \u0003מחנה אחת,\u0004 שמיד בצאתם ממחנה שכינה (העזרה) ישרפום? דבר זה אינו מתקבל על הדעת! אלא \u0003אם כן למה נאמר \"מחוץ למחנה\",\u0004 אין הכוונה שיוצאים רק ממחנה אחד, אלא \u0003לומר לך: כיון שיצא לחוץ למחנה אחת\u0004 — מיד \u0003מטמאים בגדים.\u0004","ושואלים: \u0003והתם מנא לן\u0004 \u0005[ושם\u0006 בשאר פרים הנשרפים \u0005מניין לנו]\u0006 שמוציאו חוץ לשלוש מחנות? ומסבירים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר בפר חטאת הכהן הגדול: \u0003\"והוציא את כל הפר\u0004 אל מחוץ למחנה... ושרף אותו...\u0003\"\u0004 (ויקרא ד, יב), וכוונתו: שיוציאנו \u0003חוץ לשלש מחנות.\u0004","\u0003אתה אומר\u0004 שמוציאו \u0003חוץ לשלש מחנות, או אינו אלא חוץ למחנה אחת\u0004 בלבד? \u0003כשהוא אומר בפר\u0004 החטאת שמביאים על חטא \u0003העדה: \"\u0004והוציא את הפר \u0003אל מחוץ למחנה\"\u0004 (ויקרא ד, כא), \u0003שאין תלמוד לומר\u0004 ללמד במילים אלה לגוף ההלכה, \u0003שהרי\u0004 לגופה \u0003כבר נאמר: \"ושרף אתו כאשר שרף את הפר הראשון\"\u0004 (ויקרא ד, כא) ויודעים אנו כבר שכל דיני פר הכהן גם בפר העדה. \u0003ומה תלמוד לומר \"אל מחוץ למחנה\"\u0004 שנאמר שנית — \u0003ליתן לו מחנה שניה,\u0004 שמוציאים אותו לא רק חוץ למחנה שכינה (תחום המקדש) אלא אף חוץ למחנה נוסף.","\u0003וכשהוא אומר \"מחוץ למחנה\"\u0004 (ויקרא ו, ד) בהוצאת ה\u0003דשן\u0004 שגם שם \u0003אין תלמוד לומר\u0004 ממילים אלה הלכה למעשה, \u0003שהרי כבר נאמר\u0004 בפר הכהן: \"והוציא את כל הפר אל מחוץ למחנה אל מקום טהור \u0003אל שפך הדשן\u0004 ושרף אותו על עצים באש על שפך הדשן ישרף\" (ויקרא ד, יב), אלא באה חזרה זאת על המילים \"מחוץ למחנה\" ללמד: \u0003תן לו מחנה שלישית\u0004 שמוציאים אותם אף מחוץ למחנה ישראל. ואם כן למדנו שחטאות הפנימיות נשרפות מחוץ לשלש מחנות, ומה שנאמר בפר ושעיר של יום הכיפורים \"מחוץ למחנה\" בא ללמד שמיד כשמוציאו חוץ למחנה שכינה (מחומת העזרה), הריהו מטמא בגדים.","ושואלים: \u0003ור' שמעון\u0004 הסבור שאין מטמאים אלא מחוץ לשלשה מחנות, \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"מחוץ למחנה\" מאי עביד ליה\u0004 \u0005[מה עושה הוא בו],\u0006 מה למד הוא ממנו? ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך הוא לו]\u0006 \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' אליעזר אומר: נאמר כאן\u0004 בפר יום הכיפורים \u0003\"מחוץ למחנה\" ונאמר להלן\u0004 בפרה אדומה \u0003\"מחוץ למחנה\"\u0004 (במדבר יט, ג), \u0003מה כאן\u0004 מקום שריפתה \u0003חוץ לשלש מחנות — אף להלן\u0004 בפרה, שריפתה \u0003חוץ לשלש מחנות. ומה להלן\u0004 מדובר \u0003במזרחה של ירושלים,\u0004 שהרי צריכה להיות שריפת הפרה \"אל פני אהל מועד\" — מול פתח המקדש, מזרחה לו, \u0003אף כאן\u0004 פר ושעיר של יום הכיפורים שריפתם \u0003במזרחה של ירושלים.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[\u0006ולדעת \u0005חכמים]\u0006 \u0003היכא שריף להו\u0004 \u0005[היכן שורפים אותם]?\u0006 ומשיבים: \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 במפורש בברייתא\u0005]:\u0006 \u0003היכן נשרפין?\u0004"],["\u0003לצפונה של ירושלים, וחוץ לשלש מחנות. ר' יוסי אומר: אבית\u0004 \u0005[בבית]\u0006 \u0003הדשן נשרפין.\u0004","\u0003אמר רבא: מאן\u0004 \u0005[מי הוא]\u0006 \u0003תנא\u0004 זה \u0003דפליג עליה\u0004 \u0005[החולק עליו]\u0006 על \u0003ר' יוסי\u0004 בענין זה — \u0003ר' אליעזר בן יעקב הוא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 המפרשת את מחלוקתם: נאמר: \u0003\"אל שפך הדשן ישרף\"\u0004 (ויקרא ד, יב), כוונתו: \u0003שיהא לשם\u0004 באותו מקום כבר \u0003דשן, ר' אליעזר בן יעקב אומר: שיהא מקומו משופך\u0004 (משופע) שיוכל הדשן להשפך. וסבר רבא שתנא קמא שהוא ר' יוסי מצריך שבמקום שריפת הפרים יהא כבר דשן, ור' אליעזר בן יעקב אינו מקפיד בכך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 מכאן אין ראיה, \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003במקומו משופך הוא דפליגי\u0004 \u0005[שנחלקו],\u0006 שגם ר' אליעזר בן יעקב מסכים שצריך שיהא שם דשן מלכתחילה, אלא שהוא מוסיף תנאי אחר שיהא המקום משופע, ואין איפוא הוכחה לדברי רבא. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \u0003\"והשרף\u0004 אותם יכבס בגדיו\u0003\"\u0004 (ויקרא טז, כח), להדגיש, כי \u0003השורף\u0004 בלבד הוא \u0003מטמא בגדים ולא המצית\u0004 (המדליק) \u0003את האור ולא המסדר את המערכה\u0004 של העצים קודם השריפה. \u0003ואי זהו השורף — זה המסייע בשעת שריפה\u0004 ממש.","","\u0003יכול אף משנעשו\u0004 פרים אלה \u0003אפר\u0004 יהיו \u0003מטמאין בגדים — תלמוד לומר: \"אתם\"\u0004 למעט: \u0003אותם\u0004 — כשהן בשלימותן \u0003מטמאין בגדים, ולא משנעשו אפר מטמאין בגדים. ר' אלעזר בר' שמעון אומר: הפר מטמא\u0004 כל עוד לא נשרף, אולם מש\u0003ניתך הבשר — אינו מטמא בגדים.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה ביניהם],\u0006 מה ההבדל בין שיטת התנא הראשון לשיטת ר' אלעזר בר' שמעון? ומשיבים: \u0003איכא בינייהו דשויה חרוכא\u0004 \u0005[יש ביניהם הבדל שחרך אותם]\u0006 וכבר בטלה צורת הפר אבל עדיין לא נעשו אפר ממש, שלר' אלעזר בר' שמעון כבר בכך אינו מטמא.","\u0003אמרו לו לכהן גדול: הגיע שעיר למדבר. ומניין היו יודעין\u0004 בבית המקדש \u0003שהגיע שעיר למדבר? דירכאות\u0004 (במות מוגבהות) \u0003היו עושין\u0004 בכל הדרך ועומדים עליהן אנשים \u0003ומניפין בסודרין\u0004 לאותת זה לזה כאשר הגיע השעיר. ולכן \u0003יודעין\u0004 היו מיד כ\u0003שהגיע השעיר למדבר.\u0004","\u0003אמר ר' יהודה:\u0004 לשם מה דרושות דירכאות אלה? \u0003הלא סימן גדול היה להם: מירושלים ועד בית חדודו\u0004 ששם תחילת המדבר, ושם מתקיימת כבר מצות שילוח, הוא מהלך \u0003שלשה מילין,\u0004 וכיון שהיו יקירי ירושלים \u0003הולכין מיל\u0004 ללוות המשלח \u0003וחוזרין מיל, ושוהין כדי מיל — יודעין\u0004 שכבר \u0003הגיע שעיר למדבר\u0004 ואין צורך בסימנים מיוחדים.","\u0003ר' ישמעאל אומר: והלא סימן אחר היה להם: לשון של זהורית היה קשור על פתחו של היכל, וכשהגיע\u0004 ה\u0003שעיר למדבר\u0004 והתקיימה המצוה \u0003היה הלשון מלבין, שנאמר: \"אם יהיו חטאיכם כשנים כשלג ילבינו\"\u0004 (ישעיה א, יח). \u0003אמר אביי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003בית חדודו במדבר קיימא\u0004 \u0005[היא מצויה],\u0006 \u0003והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו]\u0006 בכך: \u0003דקסבר\u0004 \u0005[שסבור]\u0006 \u0003ר' יהודה: כיון שהגיע שעיר למדבר\u0004 אף לפני שנדחה מן הצוק כבר \u0003נעשית מצותו\u0004 בעיקרה ואין צורך להמתין עוד.","","","\u0003בא לו כהן גדול לקרות\u0004 את הפרשה, \u0003אם רצה לקרות בבגדי בוץ\u0004 (פשתן) שהשתמש בהם בעבודה — \u0003קורא, ואם לאו\u0004 — רשאי להיות \u0003קורא באצטלית\u0004 (חלוק) \u0003לבן משלו,\u0004 שאינו מבגדי הקודש.","\u0003חזן\u0004 (שמש) \u0003הכנסת נוטל ספר תורה, ונותנו לראש הכנסת\u0004 הממונה על בית הכנסת שבהר הבית, \u0003וראש הכנסת נותנו לסגן\u0004 הכהנים, \u0003והסגן נותנו לכהן גדול, וכהן גדול עומד ומקבל\u0004 את הספר מידו, \u0003וקורא\u0004 בספר פרשת \u0003אחרי מות\u0004 ופרשת \u0003\"אך בעשור\"\u0004 (שבפרשת אמור) \u0003וגולל\u0004 את \u0003ספר\u0004 ה\u0003תורה\u0004 ולאחר מכן הריהו \u0003מניחו בחיקו ואומר: יותר ממה שקראתי לפניכם כתוב כאן.\u0004 פרשת \u0003\"ובעשור\"\u0004 (במדבר כט, ז) \u0003שבחומש הפקודים\u0004 (ספר \"במדבר\"), \u0003קורא על פה.\u0004","\u0003ומברך עליה\u0004 לאחר הקריאה \u0003שמונה ברכות:\u0004 ברכה על \u0003התורה\u0004 (\"אשר נתן לנו תורת אמת וכו'\"), \u0003ועל העבודה\u0004 (\"רצה בעמך ישראל ותרצה העבודה בדביר ביתך... שאותך לבדך ביראה נעבוד\"), \u0003ועל ההודאה\u0004 (\"מודים אנחנו לך וכו'\") \u0003ועל מחילת העון\u0004 (מחול לעוונותינו ביום הכיפורים הזה וכו'\"), וברכה \u0003על המקדש בפני עצמו\u0004 (וחותם: \"ברוך שבחר במקדש\"), וברכה \u0003על ישראל בפני עצמן\u0004 (וחותם: \"ברוך שבחר בישראל\"), וברכה \u0003על ירושלים בפני עצמה,\u0004 וברכה \u0003על הכהנים בפני עצמן\u0004 (וחותם: \"ברוך שבחר בכהנים\"), וברכה נוספת \u0003על שאר התפלה.\u0004","ומעירים: \u0003הרואה כהן גדול כשהוא קורא — אינו רואה פר ושעיר הנשרפין, והרואה פר ושעיר הנשרפין — אינו רואה כהן גדול כשהוא קורא.\u0004 ומוסיפים \u0003ולא מפני שאינו רשאי\u0004 לראות שניהם כאחד, \u0003אלא שהיתה דרך רחוקה\u0004 ביניהם, \u0003ומלאכת שניהן שוה כאחת\u0004 שהיו נעשים באותו זמן.","\u0003מדקתני\u0004 \u0005[ממה ששנה]\u0006 שאם רצה הכהן קורא \u0003באצטלית\u0004 (חלוק) \u0003לבן משלו, מכלל\u0004 הדבר למד אתה ש\u0003קריאה לאו עבודה\u0004 מעבודות הקודש \u0003היא,\u0004 ולכן רשאי לעשותה שלא בבגדי כהונה.","\u0003וקתני\u0004 \u0005[ושנינו]\u0006 לאחר מכן: \u0003אם רצה\u0004 הכהן \u0003לקרות בבגדי בוץ\u0004 שהם בגדי קודש — \u0003קורא,\u0004 הרי \u0003שמעת מינה\u0004 \u0005[לומד אתה מכאן]\u0006 כי \u0003בגדי כהונה ניתנו ליהנות בהן,\u0004 שמותר לכהנים ליהנות מלבישת בגדי הכהונה גם שלא בשעת העבודה. ובכך תיפתר בעיה שעסקנו בה בכמה מקומות! ודוחים: מכאן אין להביא ראיה, \u0003דילמא שאני\u0004 \u0005[שמא שונה]\u0006 ה\u0003קריאה\u0004 בתורה של \u0003צורך עבודה היא\u0004 ולכן מותר לעשותה אף בבגדי כהונה, אף שאינה עבודה גמורה.","\u0003דאיבעיא לן\u0004 \u0005[כי נשאלה לנו]\u0006 שאלה זו: האם \u0003בגדי כהונה ניתנו ליהנות בהן, או לא ניתנו ליהנות בהן.\u0004 ומנסים להביא ראיה, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה מן המשנה: שנינו כי הכהנים \u0003לא היו ישנים בבגדי קודש,\u0004 מפני חשש הפחה. ונדייק מכאן: \u0003שינה הוא דלא\u0004 \u0005[שלא]\u0006 שאסור להם, \u0003הא מיכל\u0004 \u0005[אבל לאכול] —\u0006 \u0003אכלי\u0004 \u0005[אוכלים],\u0006 שמותר להם לאכול בבגדי קודש, ומשמע שבגדי הכהונה מותרים בהנאה! ודוחים: אין מכאן ראיה \u0003דילמא שאני\u0004 \u0005[שמא שונה]\u0006 \u0003אכילה\u0004 ש\u0003צורך עבודה היא,\u0004 כי אף באכילת הקדשים יש מצות עבודה, וכמו שדרשו על הכתוב: \u0003\"ואכלו אתם אשר כפר בהם\"\u0004 (שמות כט, לג) — \u0003מלמד שהכהנים אוכלים ובעלים מתכפרין\u0004 על ידי אכילת הכהנים.","מדיוק זה אי אפשר איפוא ללמוד, אבל מנסים לדייק באופן אחר: \u0003שינה הוא דלא\u0004 \u0005[שאין]\u0006 ישנים בבגדי כהונה, \u0003הא הלוכי מהלכי\u0004 \u0005[אבל ללכת מהלכים\u0006 בהם\u0005],\u0006 משמע שמותר ליהנות בבגדי כהונה! ודוחים: \u0003בדין הוא דהלוכי נמי לא\u0004 \u0005[מצד הדין\u0006 היה ראוי \u0005ש\u0006גם \u0005להלך\u0006 בבגדי כהונה \u0005לא\u0006 יתירו\u0005]\u0006",""],["\u0003וסיפא איצטריכא ליה\u0004 \u0005[וסופה\u0006 של המשנה \u0005הוצרך לו]\u0006 שנאמר בה: \u0003פושטין ומקפלין ומניחין תחת ראשיהם,\u0004 ולכן הדגיש שאין ישנים בהם.","שואלים: נאמר ש\u0003מניחין אותן תחת ראשיהן,\u0004 הרי \u0003שמעת מינה\u0004 \u0005[לומד אתה מכאן]\u0006 במפורש ש\u0003בגדי כהונה ניתנו ליהנות בהן! אמר רב פפא: לא תימא\u0004 \u0005[אל תאמר\u0006 ותבין\u0005]\u0006 \u0003תחת ראשיהן\u0004 ממש, \u0003אלא אימא\u0004 \u0005[אמור]\u0006 שנותנים אותם \u0003כנגד\u0004 \u0005[ליד]\u0006 \u0003ראשיהן. אמר רב משרשיא: שמעת מינה\u0004 \u0005[לומד אתה מכאן]\u0006 כי אם אדם ישן ומניח \u0003תפילין מן הצד — שפיר דמי\u0004 \u0005[ראוי הדבר]\u0006 ואין לחשוש שמא תוך שנתו יתהפך וישכב עליהם.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 ש\u0003כנגד ראשיהן\u0004 הוא ולא תחת ראשיהם ממש, \u0003דאי סלקא דעתך\u0004 \u0005[שאם יעלה על דעתך\u0006 לומר\u0005]\u0006 \u0003תחת ראשיהן\u0004 ממש, \u0003ותיפוק לי\u0004 \u0005[ותצא לי]\u0006 שאסור הדבר מטעם אחר — \u0003משום כלאים. דהא איכא\u0004 \u0005[שהרי יש]\u0006 בין הבגדים \u0003אבנט,\u0004 ואבנט היה עשוי כלאים. \u0003ונהי נמי\u0004 \u0005[ואם אמנם גם כן]\u0006 בגדי כהונה \u0003ניתנו ליהנות בהן\u0004 — הרי מכל מקום יש איסור אחר בכך, שכן \u0003הא מתהני\u0004 \u0005[הרי נהנה]\u0006 \u0003מכלאים!\u0004","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאמר]:\u0006 \u0003אבנטו של כהן גדול\u0004 ביום הכיפורים \u0003זה הוא אבנטו של כהן הדיוט,\u0004 וכשם שאבנטו של כהן הדיוט לא של כלאים הוא, כך של גם של הכהן הגדול ביום הכיפורים. \u0003אלא למאן דאמר\u0004 \u0005[\u0006לדעת \u0005מי שאמר]\u0006 כי \u0003אבנטו של כהן גדול\u0004 ביום הכיפורים \u0003לא זה הוא אבנטו של כהן הדיוט,\u0004 אלא עשוי כלאים, אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 והרי נהנה הוא מכלאים!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כנגד טענה זו: כי \u0003כלאים בלבישה והעלאה — הוא\u0004 ש\u0003אסור,\u0004 אבל \u0003בהצעה שרי\u0004 \u0005[\u0006להציע אותם תחתיו \u0005מותר]\u0006 שלא נאמר בכתוב שאסור הדבר, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 נאמר בכלאים: \u0003\"\u0004ובגד כלאים שעטנז \u0003לא יעלה עליך\"\u0004 (ויקרא יט, יט), משמע: \u0003אבל אתה מותר להציעו תחתיך.\u0004 אולם זה מדין תורה, \u0003אבל אמרו חכמים: אסור לעשות כן, שמא תיכרך נימא\u0004 (חוט) \u0003אחת\u0004 מן הכלאים \u0003על בשרו,\u0004 ונמצא עובר משום לבישה והעלאה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003דמפסיק ליה מידי ביני ביני\u0004 \u0005[שמפסיק,\u0006 מניח, \u0005דבר ביניהם,\u0006 באמצע\u0005],\u0006 שמניח בגד אחר בין הכלאים ובין גופו — אולם \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003ר' שמעון בן פזי, אמר ר' יהושע בן לוי אמר רבי משום קהלא קדישא\u0004 \u0005[בשם הקהל הקדוש]\u0006 \u0003שבירושלים: אפילו עשר מצעות זו על גב זו וכלאים תחתיהן — אסור לישון עליהן,\u0004 שלא חילקו חכמים בגזירתם. \u0003אלא לאו שמע מינה\u0004 \u0005[אם לא תלמד מכאן]\u0006 שהכוונה היא \u0003כנגד ראשיהן\u0004 — ואפילו מפני איסור כלאים. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003רב אשי אמר: לעולם\u0004 יכול אתה לפרש שמדובר שמניחין את הבגדים \u0003תחת ראשיהן\u0004 ממש, ומה ששאלת \u0003והא קא מתהני\u0004 \u0005[והרי הוא נהנה\u0006 בכך\u0005]\u0006 \u0003מכלאים,\u0004 יש להשיב: \u0003בגדי כהונה\u0004 כלומר אבנטו של הכהן \u0003קשין הן,\u0004 ובגד קשה אין בו משום כלאים. \u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003אמר רב הונא\u0004 בנו של \u0003ר' יהושע: האי נמטא גמדא דנרש\u0004 \u0005[אותו לבד קשה\u0006 של כלאים שמייצרים בעיר \u0005נרש]\u0006 — \u0003שריא\u0004 \u0005[מותר],\u0006 שדבר קשה אין בו הנאת לבישה, ומטעם זה אף מותר להניח את האבנט שהוא עשוי מחומר קשה, תחת ראשו. ומכל מקום לא למדנו מכאן דבר ברור לענין שאלתנו אם מותר ליהנות מבגדי כהונה שלא לצורך העבודה.","ומביאים ראיה אחרת, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ששנינו: \u0003בגדי כהונה, היוצא בהן למדינה\u0004 כלומר מחוץ לתחום המקדש — \u0003אסור, ובמקדש בין בשעת עבודה בין שלא בשעת עבודה — מותר, מפני שבגדי כהונה ניתנו ליהנות בהן,\u0004 והרי לנו תשובה מפורשת לבעיה זו, ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","כיון שלמדנו הלכה מן הברייתא שואלים: \u0003ובמדינה לא\u0004 התירו ללבוש בגדי כהונה כלל? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 בביאור מגילת תענית, שנאמר בה: \u0003בעשרים וחמשה בטבת — יום הר גרזים הוא,\u0004 וקבעו אותו יום שמחה ש\u0003לא\u0004 \u0005[שלא]\u0006 \u0003למספד\u0004 \u0005[להספיד\u0006 בו את המתים\u0005],\u0006 משום שאירעה בו תשועה לישראל. ומה היה המעשה?","— \u0003יום שבקשו כותיים\u0004 (שומרונים) \u0003את בית אלהינו מאלכסנדרוס מוקדון להחריבו, ונתנו להם,\u0004 כלומר: נתן להם רשות להחריבו. \u0003באו והודיעו את\u0004 הכהן הגדול \u0003שמעון הצדיק. מה עשה? לבש בגדי כהונה, ונתעטף בבגדי כהונה, ומיקירי\u0004 (חשובי) \u0003ישראל עמו, ואבוקות של אור בידיהן. וכל הלילה הללו\u0004 נציגי ישראל \u0003הולכים מצד זה, והללו\u0004 צבא אלכסנדר \u0003הולכים מצד זה, עד שעלה עמוד השחר\u0004 וראו אלה את אלה.","\u0003כיון שעלה עמוד השחר אמר להם\u0004 אלכסנדר לכותיים: \u0003מי הללו\u0004 שבאים לקראתנו? \u0003אמרו לו:\u0004 אלה הם \u0003יהודים שמרדו בך. כיון שהגיע לאנטיפטרס זרחה חמה ופגעו\u0004 (פגשו) \u0003זה בזה\u0004 שני המחנות. \u0003כיון שראה\u0004 אלכסנדר את \u0003שמעון הצדיק — ירד ממרכבתו והשתחוה לפניו. אמרו לו\u0004 מלוויו: \u0003מלך גדול כמותך ישתחוה ליהודי זה?! אמר להם:\u0004 יפה עושה אני, כי \u0003דמות דיוקנו של זה מנצחת לפני בבית מלחמתי,\u0004 שכאשר אני נלחם רואה אני מעין דמות זו הולכת לפני כסימן של ניצחון, ומכאן אני למד שיש בו קדושה עליונה.","\u0003אמר להם\u0004 לשלוחי ישראל: \u0003למה באתם? אמרו\u0004 לו: \u0003אפשר בית שמתפללים בו עליך ועל מלכותך שלא תחרב, יתעוך גויים\u0004 הללו \u0003להחריבו? אמר להם: מי\u0004 הם \u0003הללו? אמרו לו\u0004 היהודים: \u0003כותיים הללו,\u0004 הם \u0003שעומדים לפניך. אמר להם: הרי הם מסורין בידיכם\u0004 לעשות בהם כרצונכם.","\u0003מיד נקבום בעקביהם ותלאום בזנבי סוסיהם, והיו מגררין אותן על הקוצים ועל הברקנים, עד שהגיעו להר גריזים. כיון שהגיעו להר גריזים\u0004 ששם היה להם לכותיים מקדש — \u0003חרשוהו, וזרעוהו כרשינין\u0004 לסמל של חורבן גמור, ששוב אין אותו מקום ראוי עוד לבנין אלא לעולם יעמוד חרב ושומם, \u0003כדרך שבקשו\u0004 הם \u0003לעשות לבית אלהינו. ואותו היום עשאוהו יום טוב.\u0004 ומתוך הסיפור למדים אנו כי הכהן הגדול לבש בגדי כהונה בצאתו חוץ למקדש!","ומשיבים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 לא היו אלה בגדי כהונה ממש \u0003אלא ראויין לבגדי כהונה,\u0004 שהיו כתבנית בגדי כהונה אבל לא נעשו מכסף קדשים, ולא היתה בהם קדושת בגדי כהונה. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כדרך שאומר הכתוב: \u0003\"עת לעשות לה' הפרו תורתך\"\u0004 (תהלים קיט, קכו), שבעת הצורך לעשות דבר לשמו של ה', מותר אף להפר דברים המפורשים בתורה, שהרי כפי שראינו היא שעמדה להם לישראל להצילם.","שנינו במשנה \u0003חזן הכנסת נוטל ספר תורה\u0004 ומוסרה למי שגדול ממנו בשררה, וכך מוסרים והולכים עד שנמסר ליד הכהן הגדול. ושואלים: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003חולקין כבוד לתלמיד במקום הרב,\u0004 שהרי הכהן הגדול רב וגדול על כולם הוא, ואף על פי כן חולקים כבוד גם לבעלי השררה שתחתיו, ואין אומרים שיש בכך משום פגיעה בכבודו! \u0003אמר אביי:\u0004 אין להוכיח מכאן, כי \u0003כולה\u0004 כל התהליך כולו, \u0003משום כבודו של כהן גדול היא,\u0004 שעל ידי כך מראים שהכהן הגדול חשוב ביותר, שיש כמה דרגות תחתיו, דרגה אחר דרגה.","שנינו כי \u0003כהן גדול\u0004 היה \u0003עומד\u0004 בשעה שמקבל את הספר. \u0003מכלל\u0004 הדגשה זו שהכהן הגדול עומד באותה שעה למדים \u0003שהוא יושב\u0004 קודם לכן, ותוהים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006"],["\u0003אין\u0004 רשות \u0003ישיבה בעזרה אלא למלכי בית דוד בלבד.\u0004 וכל השאר חייבים לעמוד, \u0003שנאמר\u0004 במלך דוד: \u0003\"ויבא המלך דויד וישב לפני ה'\"\u0004 (דברי הימים א' יז, טז), וכיצד איפוא ישב הכהן הגדול? ומשיבים: \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רב חסדא,\u0004 שדבר זה היה לא בעזרת ישראל אלא \u0003בעזרת נשים, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר שהיתה הקריאה \u0003בעזרת נשים,\u0004 ושם רשאים לשבת.","ושואלים: \u0003והיכא איתמר\u0004 \u0005[והיכן נאמר\u0006 דבר זה\u0005]\u0006 של \u0003רב חסדא\u0004 בעיקרו? ומשיבים: \u0003אהא\u0004 \u0005[על דבר זה].\u0006 שבעת שעסקו באותה סוגיה \u0003מיתיבי\u0004 \u0005[\u0006היו התלמידים \u0005מקשים]:\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003היכן קורין\u0004 בספר התורה בזמן קיום מצוות \"הקהל\" — \u0003בעזרה, ר' אליעזר בן יעקב אומר: בהר הבית\u0004 קורין בו, \u0003שנאמר\u0004 בעזרא כשהביא את ספר התורה: \u0003\"ויקרא בו לפני הרחוב אשר לפני שער המים\"\u0004 (נחמיה ח, ג). \u0003ואמר רב חסדא:\u0004 עזרה זו שאמרו — \u0003בעזרת נשים\u0004 מדובר, ולא בעזרת ישראל.","כיון שהזכרנו כתוב זה בעזרא דנים בפירושו של כתוב אחר באותו ענין; נאמר: \u0003\"ויברך עזרא את ה' האלהים הגדול\"\u0004 (נחמיה ח, ו) ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 עניינו\u0005]\u0006 של \u0003\"גדול\"\u0004 כאן? \u0003אמר רב יוסף אמר רב: שגדלו בשם המפורש,\u0004 שהזכיר שם ה' המפורש באותו מעמד. \u0003רב גידל אמר:\u0004 שתיקן שיאמר בסוף כל ברכה: \u0003\"ברוך ה' אלהי ישראל מן העולם ועד העלם\"\u0004 (דברי הימים א' טז, לו).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב דימי:\u0004 מדוע מפרש רב גידל כן? \u0003ודילמא\u0004 \u0005[ושמא]\u0006 פירוש \"הגדול\" — \u0003שגידלו בשם המפורש? אמר ליה\u0004 \u0005[לו]\u0006 רב דימי: \u0003אין אומרים שם המפורש בגבולים,\u0004 כלומר: מחוץ לעזרה.","ושואלים: \u0003ולא?\u0004 \u0005[וכי אין]\u0006 אומרים? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויעמד עזרא הספר על מגדל עץ אשר עשו לדבר...\u0004 ויברך עזרא את ה'\u0003\"\u0004 (נחמיה ח, ד. ונחמיה ח, ו) \u0003ואמר רב גידל: שגדלו בשם המפורש,\u0004 משמע שיכול להיאמר מחוץ לעזרה! ומשיבים: משם אין להוכיח כי \u0003הוראת שעה היתה\u0004 מפני שהתפללו תפילה מיוחדת במינה. ומספרים מה היה אותו ענין.","נאמר שם: \u0003\"ויזעקו בקול גדול אל ה' אלהיהם\"\u0004 (נחמיה ט, ד). \u0003מאי אמור\u0004 \u0005[מה אמרו]?\u0006 \u0003אמר רב, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יוחנן: בייא בייא\u0004 \u0005[ווי ווי]\u0006 \u0003היינו האי דאחרביה למקדשא וקליה להיכליה וקטלינהו לכולהו צדיקי ואגלינהו לישראל מארעהון\u0004 \u0005[\u0006יצר הרע \u0005הוא הוא שהחריב את המקדש ושרף את היכלו, והרג את כל הצדיקים והגלה את ישראל מארצם]\u0006 \u0003ועדיין מרקד\u0004 (ופועל) \u0003בינן\u0004 \u0005[בינינו].\u0006 \u0003כלום\u0004 לא \u0003יהבתיה לן אלא\u0004 \u0005[נתת אותו לנו]\u0006 \u0003לקבולי ביה אגרא\u0004 \u0005[לקבל בו שכר].\u0006 כשננצחו — \u0003לא איהו בעינן\u0004 \u0005[אותו אנו רוצים],\u0006 \u0003ולא אגריה בעינן\u0004 \u0005[את שכרו אנו רוצים],\u0006 כלומר: מוותרים אנו על השכר שבא מכבישת היצר ובלבד שיסור זה מאתנו.","\u0003נפל להו\u0004 \u0005[להם]\u0006 \u0003פיתקא מרקיעא, דהוה כתב בה\u0004 \u0005[פתק מן השמים שהיה כתוב עליו]\u0006 \u0003\"אמת\",\u0004 לומר להם שמסכים הקדוש ברוך הוא לבקשתם.","\u0003אמר רב חנינא:\u0004 דרך אגב \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003חותמו של הקדוש ברוך הוא \"אמת\"\u0004 שהרי כביכול מסר להם את חותמו, לומר שהוא מסכים וחותם על הדבר.","\u0003אותיבו בתעניתא תלתא יומין ותלתא לילואתא\u0004 \u0005[ישבו בתענית שלושה ימים ושלושה לילות]\u0006 \u0003מסרוהו ניהליהו\u0004 \u0005[מסרו להם]\u0006 את היצר הרע. \u0003נפק אתא כי גוריא דנורא\u0004 \u0005[יצא ובא כמין גור אריה של אש]\u0006 \u0003מבית קדשי הקדשים, אמר להו\u0004 \u0005[להם]\u0006 \u0003נביא לישראל: היינו יצרא\u0004 \u0005[זהו יצר]\u0006 של \u0003עבודה זרה,\u0004 שכך הוא מתגלה, \u0003שנאמר: \"ויאמר זאת הרשעה\"\u0004 (זכריה ה, ח), לומר: שהראה להם באצבע את הרשעה עצמה.","\u0003בהדי דתפסוה ליה אשתמיט ביניתא ממזייא\u0004 \u0005[בשעה שתפסו אותו נשמטה שערה מתוך שערותיו]\u0006 \u0003ורמא קלא ואזל קליה ארבע מאה פרסי\u0004 \u0005[והרים קולו\u0006 מפני הכאב \u0005והלך\u0006 נשמע \u0005קולו ארבע מאות פרסות].\u0006 \u0003אמרו: היכי נעביד\u0004 \u0005[כיצד נעשה]\u0006 כדי להורגו? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003חס ושלום מרחמי עליה מן שמיא\u0004 \u0005[ירחמו עליו מן השמים],\u0006 שהוא בוכה וצועק כל כך. \u0003אמר להו\u0004 \u0005[להם]\u0006 ה\u0003נביא: שדיוהו בדודא דאברא, וחפיוהו לפומיה באברא, דאברא משאב שאיב קלא\u0004 \u0005[זרקו אותו לתוך דוד של עופרת, וכיסו את פיו בעופרת, שהעופרת שואבת את הקול]\u0006 ואין הקול נשמע. שנאמר: \u0003\"ויאמר זאת הרשעה וישלך אתה אל תוך האיפה וישלך את אבן העופרת אל פיה\"\u0004 (זכריה ה, ח) ועל ידי כך יפטרו מיצר הרע של עבודה זרה.","משראו שנמסר בידם יצר הרע של עבודה זרה על פי בקשתם, \u0003אמרו\u0004 חכמי ישראל: \u0003הואיל ועת רצון הוא,\u0004 שהקדוש ברוך הוא שומע לתפילתנו, \u0003נבעי רחמי איצרא\u0004 \u0005[נבקש רחמים\u0006 גם \u0005על היצר]\u0006 של \u0003עבירה\u0004 בענין עריות. \u0003בעו רחמי ואמסר בידייהו\u0004 \u0005[בקשו רחמים ונמסר\u0006 גם הוא \u0005בידם].\u0006","\u0003אמר להו\u0004 \u0005[להם]\u0006 הנביא זכריה: \u0003חזו, דאי קטליתו ליה לההוא, כליא עלמא\u0004 \u0005[ראו, שאם הורגים אתם אותו, יכלה העולם]\u0006 ששוב לא תהיה פריה ורביה בעולם. \u0003חבשוהו תלתא יומי\u0004 \u0005[אסרו אותו שלשה ימים],\u0006 \u0003ובעו ביעתא בת יומא\u0004 \u0005[ובקשו ביצה בת יומה]\u0006 \u0003בכל ארץ ישראל ולא אשתכח\u0004 \u0005[נמצאה]\u0006 כי התרנגולות הפסיקו להטיל שהרי יצר הפריה והרביה בטל. \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003היכי נעביד\u0004 \u0005[כיצד נעשה]?\u0006 \u0003נקטליה\u0004 \u0005[\u0006אם \u0005נהרגנו]\u0006 \u0003— כליא עלמא\u0004 \u0005[יכלה העולם],\u0006 \u0003ניבעי רחמי אפלגא\u0004 \u0005[\u0006ואם \u0005נבקש רחמים על חצי],\u0006 כלומר: שיבטלו מחציתו \u0005—\u0006 \u0003פלגא ברקיעא לא יהבי\u0004 \u0005[חצי מן השמים אין נותנים],\u0006 שמשמים נותנים רק מתנה שלימה. מה עשו? — \u0003כחלינהו לעיניה ושבקוהו\u0004 \u0005[ניקרו את עיניו והניחוהו]\u0006 \u0003ואהני\u0004 \u0005[והועיל]\u0006 מה שנקרו עיניו \u0003דלא מיגרי ביה לאיניש בקריבתה\u0004 \u0005[שאין אדם מתגרה\u0006 עוד כל כך \u0005בקרובות\u0006 משפחתו\u0005],\u0006 שהועילו למעט תוקפו של יצר הרע הזה.","\u0003במערבא מתנו הכי\u0004 \u0005[בארץ ישראל היו שונים כך],\u0006 כלומר: את הכתוב בענין \"ה' האלוהים הגדול\" פירשו כך: ש\u0003רב גידל אמר: \"גדול\" — שגדלו בשם המפורש, ורב מתנא אמר:\u0004 שחזרו ואמרו בתפילותיהם: \u0003\"האל הגדול הגבור והנורא\"\u0004 (נחמיה ט, לב).","ומעירים: \u0003והא\u0004 \u0005[וזה]\u0006 שאמר \u0003רב מתנא מטייא\u0004 \u0005[נוטה],\u0006 כלומר: קרוב לרעיון של \u0003ר' יהושע בן לוי.\u0004 ש\u0003אמר ר' יהושע בן לוי: למה נקרא שמן\u0004 של גדולי אותם הדורות \u0003אנשי כנסת הגדולה\u0004 — לפי \u0003שהחזירו עטרה\u0004 של הקדוש ברוך הוא \u0003ליושנה.\u0004 כיצד? \u0003אתא\u0004 \u0005[בא]\u0006 \u0003משה\u0004 בתפילתו ו\u0003אמר: \"האל הגדל הגבר והנורא\"\u0004 (דברים י, יז). \u0003אתא\u0004 \u0005[בא]\u0006 \u0003ירמיה\u0004 הנביא \u0003ואמר: גוים\u0004 (שרי נבוכדנצר) \u0003מקרקרין\u0004 (משברים) \u0003בהיכלו, איה נוראותיו? לא אמר\u0004 בתפלתו \u0003נורא\u0004 (\"האל הגדול הגיבור ה' צבאות שמו\". ירמיה לב, יח). \u0003אתא\u0004 \u0005[בא]\u0006 \u0003דניאל ואמר: גוים משתעבדים בבנין, איה גבורותיו? לא אמר\u0004 בתפלתו ה\u0003גבור\u0004 (\"האל הגדול והנורא\". דניאל ט, ד).","\u0003אתו אינהו\u0004 \u0005[באו הם]\u0006 אנשי כנסת הגדולה \u0003ואמרו: אדרבה, זו היא גבורת גבורתו: שכובש את יצרו.\u0004 כלומר: זו היא גילוי גבורתו של הקדוש ברוך הוא, שכובש את כעסו מאומות העולם על אף שהחריבו את ביתו ובאו להשמיד את עמו, ובכל זאת הריהו מסתיר פניו לפי שעה, וזה הוא ענין של גבורת ה' — \u0003שנותן ארך אפים לרשעים,\u0004 ולכן ראוי הוא שיקרא \"הגיבור\". \u0003ואלו הן נוראותיו — שאלמלא מוראו של הקדוש ברוך הוא היאך אומה אחת\u0004 בודדת ושנואה \u0003יכולה להתקיים בין האומות\u0004 כולן?","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 כלומר: ירמיה ודניאל \u0003היכי עבדי הכי\u0004 \u0005[כיצד עשו כך]\u0006 \u0003ועקרי תקנתא דתקין\u0004 \u0005[ועקרו תקנה שתיקן]\u0006 \u0003משה\u0004 רבינו הגדול מהם לומר את שלושת הכינויים הללו בתפילה? \u0003אמר רבי אלעזר מתוך שיודעין\u0004 הן \u0003בהקדוש ברוך הוא שאמתי הוא,\u0004 שהוא מסכים על האמת ושונא את השקר \u0003— לפיכך לא כיזבו בו,\u0004 שכיון שלא הרגישו שהם יכולים לקוראו \"הגדול הגבור והנורא\" — לא אמרו כן, ואין להתרעם עליהם.","במשנה נאמר כי הכהן הגדול \u0003קורא פרשת \"אחרי מות\" ו\"אך בעשור\".\u0004 שתי פרשיות אלה כתובות בספר ויקרא אך אינן סמוכות זו לזו. \u0003ורמינהי\u0004 \u0005[מראים סתירה],\u0006 ששנינו: \u0003מדלגין בנביא\u0004 בזמן קריאת ההפטרה ואין חייבים להמשיך ולקרוא כסדר, אבל \u0003אין מדלגין בתורה!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן\u0004 שאמרנו שאין מדלגין בתורה, הרי זה \u0003בכדי שיפסיק התורגמן.\u0004 כלומר: אם המרחק בין הדברים גדול, עד שבתוך זמן גלילת הספר ממקום למקום יסיים המתורגמן (שהיה נוהג לתרגם כל פסוק ופסוק לארמית) את תרגומו ויצטרך להמתין בשתיקה, עד שיגיע הקורא לפסוק הבא — אין מפסיקים. \u0003כאן\u0004 שמותר לדלג — הרי הוא \u0003בכדי שלא יפסיק התורגמן.\u0004","ומקשים: \u0003והא עלה קתני\u0004 \u0005[והרי על\u0006 משנה \u0005זו שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מדלגין בנביא, ואין מדלגין בתורה. ועד כמה מדלג — בכדי שלא יפסיק התורגמן.\u0004 משמע ששיעור שלא יפסיק התורגמן — בנביא דווקא, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בתורה — כלל כלל לא\u0004 מדלגין!","אלא יש ליישב באופן אחר; \u0003אמר אביי: לא קשיא\u0004 \u0005[אינו קשה]\u0006 וכך יש להסביר: \u0003כאן\u0004 שמותר לדלג הוא \u0003בענין\u0004 (בנושא) \u0003אחד\u0004 שאין הדילוג ניכר לשומעים \u0003כאן\u0004 שאסור — הוא \u0003בשני ענינין.\u0004","\u0003והתניא\u0004 \u0005[וכן שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מדלגין בתורה בענין אחד, ובנביא בשני ענינין. כאן וכאן\u0004 לא מדלגים אלא \u0003בכדי שלא יפסיק התורגמן.\u0004 ובכלל \u0003ואין מדלגין מנביא לנביא\u0004 אפילו בענין אחד ובזמן קצר. \u0003ובנביא של שנים עשר מדלגין\u0004 שכל תרי עשר נחשבים כספר אחד לענין זה,"],["\u0003ובלבד שלא ידלג מסוף הספר לתחילתו\u0004 שאז ניכר לכל שהוא מדלג.","במשנה שנינו כי \u0003גולל\u0004 את \u0003ספר התורה\u0004 ואומר: יותר ממה שקראתי כתוב שם. ומעירים: \u0003וכל כך למה\u0004 צריך הוא לומר כן — \u0003כדי שלא להוציא לעז על ספר תורה,\u0004 שלא יחשבו שחסרה שם אותה פרשה שקורא על פה.","שנינו במשנה כי פרשת \u0003\"בעשור\" של חומש הפקודים\u0004 (\"במדבר\") הריהו \u0003קורא על פה.\u0004 ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 קורא על פה? \u0003נגלול\u0004 \u0005[שיגלול]\u0006 את הספר עד שיגיע לפרשה זו \u0003וניקרי\u0004 \u0005[ויקרא]!\u0006 \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר רב ששת: לפי שאין גוללין ספר תורה בציבור מפני כבוד ציבור,\u0004 שאין ראוי שהציבור יחכה עד שיסיים הגולל לגלול.","ושואלים: אם כך יש דרך אחרת, \u0003ונייתי אחרינא ונקרי\u0004 \u0005[ושיביאו\u0006 ספר תורה \u0005אחר\u0006 הפתוח באותה פרשה \u0005ויקרא\u0006 בו\u0005]!\u0006 \u0003רב הונא בר יהודה אמר: משום פגמו של ראשון\u0004 שלא יחשבו שנמצא פגם בספר הראשון ולכן מביאים ספר אחר. \u0003וריש לקיש אמר: משום ברכה שאינה צריכה,\u0004 שכשמתחיל לקרוא מספר תורה אחר צריך לברך עליו ברכת התורה בשנית, ומוטב שיקרא על פה ולא יתחייב בברכה מחדש ויוציא שם שמים לחינם.","ושואלים: \u0003ומי חיישינן לפגמא\u0004 \u0005[האם\u0006 בכגון זה שמוציאים ספר אחר \u0005חוששים אנו לפגמו\u0006 של ראשון]? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יצחק נפחא\u0004 \u0005[הנפח]:\u0006 \u0003ראש חודש טבת שחל להיות בשבת\u0004 ותמיד הוא חל בחנוכה \u0003מביאין שלש תורות\u0004 (שלושה ספרי תורה) \u0003וקורין אחת בענינו של יום\u0004 לפי פרשת השבוע, ובספר תורה \u0003אחת\u0004 קורין בפרשה של \u0003ראש חודש,\u0004 ואחת קורין בענין \u0003של חנוכה.\u0004 הרי שקוראים במספר ספרי תורה לפי הצורך ואין חוששין לפגמו של ספר תורה ראשון!","ומשיבים: אין הדברים דומים; \u0003תלתא גברי בתלתא ספרי\u0004 \u0005[שלושה אנשים\u0006 קורים \u0005בשלושה ספרים]\u0006 \u0003— ליכא פגמא\u0004 \u0005[אין\u0006 בכך \u0005פגם],\u0006 שסבורים שבשביל כבודו של כל אחד מהם קורים לו בספר מיוחד, אולם \u0003חד גברא בתרי ספרי\u0004 \u0005[איש אחד\u0006 הקורא \u0005בשני ספרים]\u0006 \u0003איכא פגמא\u0004 \u0005[יש פגם]\u0006 בדבר, שיכולים לחשוב שנעשה הדבר משום שיש פגם בספר הראשון.","שנינו במשנה, כי לאחר הקריאה היה הכהן הגדול \u0003מברך עליה שמונה ברכות. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: שמונה ברכות אלו הם: \u0003על התורה\u0004 — מברך \u0003כדרך שמברכים\u0004 כרגיל \u0003בבית הכנסת,\u0004 \"נותן התורה\", \u0003על העבודה, ועל ההודאה, ועל מחילת העון — כתיקנה\u0004 כמו שמתוקנות ברכות אלה בסדר התפילה. \u0003ועל המקדש\u0004 ברכה \u0003בפני עצמו, ועל הכהנים בפני עצמן, ועל ישראל בפני עצמן ועל שאר\u0004 ה\u0003תפלה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ושאר התפלה\u0004 שאמרה המשנה, כך אומר הוא: \u0003\"רנה תחינה בקשה מלפניך על עמך ישראל שצריכין להושע\"\u0004 ומוסיף דבר תחינה \u0003וחותם\u0004 ברכה זו \u0003ב\"שומע תפלה\". ואחר כך,\u0004 לאחר שגמר הכהן את קריאתו \u0003כל אחד ואחד\u0004 מהקהל \u0003מביא ספר תורה מביתו (\u0004אשר הובא עוד מערב יום הכיפורים, \u0003וקורא בו\u0004 שנית \u0003כדי להראות חזותו\u0004 (מראהו של הספר) \u0003לרבים,\u0004 ומצוה יש בדבר שהוא מתנאה במצוות בוראו.","נאמר במשנה כי \u0003הרואה\u0004 את ה\u0003כהן\u0004 ה\u0003גדול\u0004 כשהוא קורא אינו רואה פר ושעיר הנשרפין, והוסיפו במשנה: \u0003לא מפני שאינו רשאי,\u0004 אלא מפני המרחק בין המקומות בו נעשו שני הדברים הללו. ומעירים: \u0003פשיטא\u0004 \u0005[\u0006הרי הדבר \u0005פשוט],\u0006 ומדוע יעלה על הדעת שיהא איסור כלשהו בדבר? ומשיבים: \u0003מהו דתימא\u0004 \u0005[מהו שתאמר]\u0006 שיש כאן איסור כשיטת \u0003ריש לקיש.\u0004 ש\u0003אמר ריש לקיש: אין מעבירין על המצות,\u0004 כלומר: אם נזדמנה לו לאדם מצוה, אינו רשאי להבטל ממנה אפילו לשם מצוה אחרת.","\u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003מצוה\u0004 יש כאן בשמיעת הקריאה מפי הכהן הגדול — מפני הטעם של \u0003\"ברב עם הדרת מלך\"\u0004 (משלי יד, כח) שכבוד שמים הוא שיהא קהל מרובה, ולכן היה מקום לחשוש לאיסור אם ילך משם. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו],\u0006 שהסיבה היא המרחק שביניהם ולא משום טעם אחר.","\u0003אם בבגדי בוץ\u0004 לבנים של קודש היה הכהן הגדול \u0003קורא,\u0004 הרי לאחר מכן \u0003קדש ידיו ורגליו\u0004 כדרך שעושה בפשיטת בגדי קודש. \u0003פשט\u0004 את בגדי הבוץ, \u0003ירד\u0004 למקוה \u0003וטבל, עלה ונסתפג\u0004 במגבת, \u0003והביאו לו בגדי זהב\u0004 של כהונה גדולה \u0003ולבש, וקדש ידיו ורגליו,\u0004","\u0003ויצא ועשה את אילו ואת איל העם ואת שבעת כבשים תמימים בני שנה\u0004 שהם מחובת היום, אלו \u0003דברי ר' אליעזר. ר' עקיבא אומר:\u0004 קרבנות אלה לא בשלב זה היו קרבים אלא \u0003עם\u0004 קרבן \u0003תמיד של שחר היו קרבין.\u0004 ואילו \u0003פר העולה\u0004 השייך ליום הכיפורים \u0003ו\u0004ה\u0003שעיר הנעשה בחוץ\u0004 שיש במוספי כל חג קרבן חטאת אחד — אלה \u0003היו קרבין עם\u0004 קרבן \u0003תמיד של בין הערבים.\u0004","לאחר הקרבת קרבנות אלה \u0003קדש ידיו ורגליו ופשט\u0004 את בגדי הזהב, \u0003וירד\u0004 למקוה \u0003וטבל ועלה ונסתפג,\u0004","ו\u0003הביאו לו\u0004 שנית \u0003בגדי לבן ולבש, וקדש ידיו ורגליו.\u0004 ולאחר מכן \u0003נכנס\u0004 לקודש הקדשים \u0003להוציא\u0004 משם \u0003את הכף ואת המחתה\u0004 של הקטורת שהכניס קודם לכן. ושוב \u0003קדש ידיו ורגליו ופשט\u0004 את בגדי לבן \u0003וירד\u0004 למקוה \u0003וטבל\u0004 ו\u0003עלה ונסתפג\u0004","ו\u0003הביאו לו בגדי זהב, ולבש וקדש ידיו ורגליו ונכנס\u0004 להיכל \u0003להקטיר קטורת של בין הערבים, ולהטיב את הנרות\u0004 שזה סוף עבודת היום, \u0003וקדש ידיו ורגליו ופשט\u0004 את בגדי הזהב \u0003וירד\u0004 למקוה \u0003וטבל\u0004 ו\u0003עלה ונסתפג,\u0004","\u0003והביאו לו בגדי עצמו ולבש,\u0004 שהרי נגמרה העבודה ותם יום הכיפורים. \u0003ומלוין אותו\u0004 כל העם \u0003עד ביתו\u0004 משום כבודו. \u0003ויום טוב היה עושה\u0004 הכהן הגדול \u0003לאוהביו\u0004 וידידיו \u0003בשעה שיצא בשלום מן הקודש.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: \u0003היכי קאמר\u0004 \u0005[כיצד אמר]\u0006 ר' עקיבא לגבי חלוקת הקרבנות, האם הכוונה שאילו ואיל העם \u0003עם תמיד של שחר היו קרבין ופר העולה ושעיר הנעשה בחוץ עם תמיד של בין הערבים\u0004 היו קרבין,","\u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 וכך יש להבין: \u0003עם תמיד של שחר היו קרבין, ופר העולה בהדייהו\u0004 \u0005[עמם]\u0006 \u0003ושעיר הנעשה בחוץ — עם תמיד של בין הערבים.\u0004","\u0003ותו\u0004 \u0005[ועוד]\u0006 הוקשה להם: הלא \u0003פר העולה לר' אליעזר דשייריה\u0004 \u0005[ששייר אותו]\u0006 ולא פירש, \u0003אימת עביד ליה\u0004 \u0005[מתי הוא עושה אותו]?\u0006 שלא נתבאר אם לשיטתו עושהו עם השאר או באופן אחר.","\u0003ותו\u0004 \u0005[ועוד]\u0006 קשה: \u0003בין\u0004 לדעת \u0003ר' אליעזר, בין\u0004 לדעת \u0003ר' עקיבא, אימורי חטאת\u0004 הקרבת החלבים של החטאות הפנימיות \u0003אימת עביד להו\u0004 \u0005[מתי עושה\u0006 הוא \u0005אותם]?\u0006 שכן שניהם לא פירשו את זמן עשייתם.","\u0003אמר רבא: לא משכחת לה מתקנתא\u0004 \u0005[תמצא לה שיטה מתוקנת]\u0006 להעמיד ולהסביר את הדברים, \u0003אלא או לר' אליעזר\u0004 לפי שיטת ה\u0003תנא בדבי\u0004 \u0005[החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל, או לר' עקיבא\u0004 כפי שמבואר ב\u0003תוספתא.\u0004","\u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003שמואל: ר' אליעזר אומר: יצא ועשה אילו ואיל העם ואימורי חטאת, אבל פר העולה ושבעת כבשים ושעיר הנעשה בחוץ\u0004 — נעשים \u0003עם תמיד של בין הערבים,\u0004 והרי עבודת היום נעשית לפי ר' אליעזר בשלימותה.","\u0003ר' עקיבא\u0004 שב\u0003תוספתא מאי היא\u0004 \u0005[מה היא]?\u0006 ומביאים את התוספתא, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' עקיבא אומר: פר העולה ושבעת כבשים — עם תמיד של שחר היו קרבין, שנאמר: \"מלבד עלת הבקר אשר לעלת התמיד\"\u0004 (במדבר כח, כג), שכך עושים תמיד את מוספי החג, \u0003ואחר כך\u0004 עושים את \u0003עבודת היום\u0004 המיוחדת ליום הכיפורים."],["\u0003ואחר כך\u0004 היו עושים \u0003שעיר הנעשה בחוץ, שנאמר: \"שעיר עזים אחד חטאת מלבד חטאת הכפרים\u0004 ועולת התמיד ומנחתה ונסכיהם\u0003\"\u0004 (במדבר כט, יא), משמע ששעיר החטאת הקבוע לרגלים נעשה לאחר קרבנות היום. \u0003ואחר כך\u0004 מקריב \u0003אילו ואיל העם, ואחר כך אימורי חטאת, ואחר כך תמיד של בין הערבים.\u0004 ביררנו איפוא את שיטות התנאים.","ומעתה שואלים: \u0003מאי טעמא\u0004 \u0005[מהו טעמו]\u0006 של \u0003ר' אליעזר\u0004 שכך הוא הסדר? ומשיבים: \u0003עביד כדכתיב\u0004 \u0005[עושה הוא כפי שכתוב]\u0006 לפי סדר המקראות, \u0003עביד ברישא\u0004 \u0005[עושה בתחילה]\u0006 קרבנות שמדובר בהם בספר \u0003תורת כהנים\u0004 (\"ויקרא\") \u0003והדר עביד\u0004 \u0005[ואחר כך הוא עושה]\u0006 את קרבנות המוספים האחרים המפורשים ב\u0003חומש הפקודים,\u0004 (\"במדבר\").","ושואלים: \u0003ור' עקיבא\u0004 מה טעמו? ומשיבים: \u0003כדקתני טעמא\u0004 \u0005[כפי ששנינו את הטעם]\u0006 בברייתא, שנאמר: \u0003\"מלבד עלת הבקר אשר לעלת התמיד\"\u0004 (במדבר כח, כג) \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מוספין עם תמיד של שחר עביד להו\u0004 \u0005[עושה אותם].\u0006","ושואלים: אם כן, \u0003ור' אליעזר האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"מלבד חטאת הכפרים\" מאי עביד ליה\u0004 \u0005[מה עושה הוא לו],\u0006 מה לומד הוא ממנו? ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 פסוק \u0005הוצרך לו]\u0006 כדי ללמוד ממנו: \u0003על מה שזה מכפר — זה מכפר,\u0004 שמשעיר פנימי למד הוא לשעיר החיצון לא לענין דרך ומועד עשייתו אלא לענין מהותו, שהוא מכפר על אותם חטאים כמותו.","שנינו בברייתא: \u0003ר' יהודה אומר משמו\u0004 של ר' עקיבא: \u0003אחד\u0004 משבעת הכבשים של יום הכיפורים \u0003קרב עם תמיד של שחר, וששה\u0004 קרבים \u0003עם תמיד של בין הערבים,\u0004 מעין פשרה בין השיטות. ואילו \u0003ר' אלעזר בר' שמעון אומר משמו\u0004 של ר' עקיבא: \u0003ששה קרבין עם תמיד של שחר, ואחד עם תמיד של בין הערבים.\u0004","ושואלים: \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים],\u0006 ר' יהודה ור' אלעזר בר' שמעון שמחלקים את הקרבת שבעת הכבשים לשני חלקים? ומשיבים: \u0003תרי קראי כתיבי\u0004 \u0005[שני מקראות כתובים]\u0006 ויש בהם מעין סתירה. \u0003כתיב\u0004 \u0005[נאמר]\u0006 מצד אחד: \u0003\"מלבד עלת הבקר\u0004 אשר לעולת התמיד תעשו את אלה\u0003\"\u0004 (במדבר כח, כג), משמע שהם קרבים בבוקר, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויצא ועשה את עלתו\u0004 ואת עלת העם\u0003\"\u0004 (ויקרא טז, כד) סמוך לסוף סדר העבודה! \u0003הלכך, עביד מניהו הכא ומנייהו הכא\u0004 \u0005[על כן עושה הוא מקצתם כאן, ומקצתם כאן]\u0006 ומתקיימים על ידי כך שני הכתובים.","ומעתה מבררים \u0003במאי קא מיפלגי\u0004 \u0005[במה הם חלוקים],\u0006 שאחד אומר שעושים אחד בשחרית וששה בין הערבים והשני אומר שעושים ששה בשחרית ואחד בין הערבים? \u0003ר' יהודה סבר: עביד חד\u0004 \u0005[עושה אחד]\u0006 בשחרית \u0003כדכתיב\u0004 \u0005[כמו שנאמר]:\u0006 \u0003\"מלבד עלת הבקר\" והדר\u0004 \u0005[ואחר כך]\u0006 \u0003עביד\u0004 \u0005[עושה]\u0006 מיד \u0003עבודת היום,\u0004 וטעמו — \u0003דילמא חולשא חליש\u0004 \u0005[שמא ייחלש]\u0006 ה\u0003כהן גדול\u0004 בשל הקרבת שבעת הכבשים ולא יוכל להשלים עבודת היום שאינה נעשית על ידי אחר והיא עיקר הכפרה. ולכן ממעטים לו בעבודת המוספים בתחילת היום ככל האפשר.","\u0003ור' אלעזר בר' שמעון סבר: כיון דאתחיל\u0004 \u0005[שהתחיל\u0006 כבר\u0005]\u0006 להקריב קרבנות המוספין — \u0003עביד\u0004 \u0005[עושה הוא]\u0006 \u0003ששה\u0004 כבשים, וזאת משום החשש \u0003דילמא פשע\u0004 \u0005[שמא יתרשל]\u0006 אחר כך, וידחה הדבר ולא יוקרבו. ומדוע חוששים לכך — ש\u0003לגבי עבודת היום\u0004 שהיא קודש קדשים ומיוחדת מכל העבודות — \u0003זריז הוא\u0004 בודאי ביותר, אבל במוסף שהוא כעבודת כל הרגלים, שמא לא יהיה זריז, ויתרשל בקרבנות אלה.","ומעירים: \u0003דכולי עלמא מיהת\u0004 \u0005[לדעת הכל על כל פנים],\u0006 לפי כל השיטות שהוזכרו עד כה, \u0003חד איל\u0004 \u0005[איל אחד]\u0006 בלבד \u0003הוא\u0004 שקרב ביום הכיפורים. \u0003כמאן\u0004 \u0005[כשיטת מי\u0006 הוא הדבר\u0005] —\u0006 כשיטת \u0003רבי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 שביארה שיש מחלוקת בדבר; \u0003רבי אומר: איל אחד\u0004 מקריבים ביום הכיפורים, והוא \u0003האמור כאן\u0004 בספר ויקרא (\"בזאת יבוא אהרן אל הקודש בפר בן בקר לחטאת ואיל לעולה\". טז, ג), \u0003הוא האמור בחומש הפקודים\u0004 (\"והקרבתם עולה לה' ריח ניחוח פר בן בקר אחד איל אחד כבשים בני שנה שבעה תמימים יהיו לכם\". במדבר כט, ח). \u0003ר' אלעזר בר' שמעון אומר: שני אילים הן\u0004 שצריכים להקריב עולה ביום זה \u0003אחד האמור כאן\u0004 בספר ויקרא שהוא חלק מעבודת היום המיוחדת, \u0003ואחד האמור בחומש הפקודים\u0004 שהוא מקרבנות המוספים.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003רבי?\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אחד\"\u0004 משמע איל אחד מביאים ולא שנים. ושואלים: \u0003ור' אלעזר בר' שמעון מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אחד\"\u0004 לדעתו? ומשיבים: לדעתו בא הפסוק לומר שצריך שיהיה ה\u0003מיוחד שבעדרו,\u0004 שחייב לדאוג שיהא מיוחד בטיבו.","ושואלים: \u0003ורבי\u0004 מניין למד הוא הלכה זו? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 הדבר ממה שנאמר: \u0003\"מבחר נדריכם\"\u0004 (דברים יב, יא), ללמד שכל קרבן שמקריבים צריך להיות מן המובחר. ושואלים: \u0003ור' אלעזר בר' שמעון,\u0004 לשם מה נצרך לדעתו פסוק נוסף? ומשיבים: לדעתו \u0003חד\u0004 \u0005[\u0006כתוב \u0005אחד]\u0006 מהם נאמר לגבי קרבן \u0003חובה\u0004 שצריך להיות מן המובחר, \u0003וחד\u0004 \u0005[ו\u0006כתוב \u0005אחד]\u0006 מהם נאמר לגבי קרבן \u0003נדבה. וצריכי\u0004 \u0005[וצריכים\u0006 שניהם להיאמר\u0005]\u0006 ואין ללמוד זה מזה. כי יש טעם לומר שבנדבה יקריב מן המובחר לפי שהוא מתנדב מרצונו, ויש טעם לומר שדווקא בחובה יקריב מן המובחר, לפי שצריך לצאת ידי חיוב המוטל עליו בהידור.","שנינו בסדר העבודה במשנה, כי \u0003קידש\u0004 הכהן הגדול את \u0003ידיו ורגליו\u0004 והוציא את המחתה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \u0003\"ובא אהרן אל אהל מועד\u0004 ופשט את בגדי הבד\u0003\"\u0004 (ויקרא טז, כג) \u0003למה הוא בא —\u0004 כדי \u0003להוציא את הכף ואת המחתה\u0004 מקודש הקדשים,"],["\u0003שכל הפרשה כולה נאמרה על הסדר,\u0004 שהעבודה צריכה להיעשות כסדר שכתוב במקרא, \u0003חוץ מפסוק זה\u0004 שלא נאמר על הסדר, וצריך לעשותו שלא כפי סדר כתיבתו, כי אם לאחר מכן.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אומרים שאינו כתוב כפי סדר העבודה הנכון? \u0003אמר רב חסדא: גמירי\u0004 \u0005[למודים היו]\u0006 מפי המסורת כי \u0003חמש טבילות ועשרה קידושין טובל כהן גדול ומקדש בו ביום,\u0004 כשמחליף בגדים,","\u0003ואי אמרת\u0004 ש\u0003כסדרן\u0004 \u0005[ואם אומר אתה שכסדרן]\u0006 \u0003כתיבי\u0004 \u0005[כתובים]\u0006 המקראות, אם כן \u0003לא משכחת לה\u0004 \u0005[אין אתה מוצא]\u0006 \u0003אלא שלש טבילות וששה קידושין,\u0004 ולכן בהכרח לומר שאין סדר העבודה כפי סדר כתיבתו, אלא כניסתו לקודש הקדשים נעשית לאחר שסיים את עבודת היום.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא: ודילמא\u0004 \u0005[ושמא]\u0006 אין לשבש את סדר הכתובים, אלא כפי הסדר הנאמר בהם הריהו \u0003מפסיק ליה\u0004 \u0005[מפסיק הוא אותה]\u0006 \u0003בשעיר הנעשה בחוץ,\u0004 שעושה את השעיר ואחר כך חוזר ומוציא את הכף ורק לאחר מכן מקריב את האילים, ולא כסדר האמור במשנה!","\u0003אמר אביי: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויצא ועשה את עלתו\u0004 ואת עולת העם\u0003\"\u0004 (ויקרא טז, כד), וזוהי היציאה הראשונה האמורה בכתוב, לומר: \u0003מיציאה ראשונה עביד\u0004 \u0005[עושה הוא]\u0006 את \u0003אילו ואיל העם.\u0004","\u0003רבא אמר\u0004 ראיה אחרת יש שאין הכתובים מסודרים כפי סדר העבודה הנכון, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ופשט את בגדי הבד\u0004 אשר לבש בבואו אל הקודש\u0003\"\u0004 (ויקרא טז, כג), \u0003שאין תלמוד לומר \"אשר לבש\"\u0004 שהרי אין זה מלמד דבר, כי \u0003כלום אדם פושט אלא מה שלובש?! אלא, מה תלמוד לומר \"אשר לבש\" — שלבש כבר.\u0004 ומכאן למדים כי את בגדי הבד שלבש כבר קודם לצורך עבודת היום ופשטן, הריהו חוזר ולובשן לצורך עבודה אחרת, שהיא הוצאת הכף והמחתה ואז חוזר ופושטם בשנית, ואין לומר כן אלא אם אכן הוא מאחר את הוצאת הכף והמחתה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבה בר רב שילא: ואימא\u0004 \u0005[ואמור]\u0006 ש\u0003מפסיק בשעיר הנעשה בחוץ!\u0004 ומשיבים: \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"ויצא ועשה\"\u0004 (ויקרא טז, כד), לומר: כיון שיוצא — עושה ככל הסדר הכתוב.","ושואלים: והאם באמת \u0003כל הפרשה כולה נאמרה על הסדר? והא קראי כתיבי\u0004 \u0005[והרי\u0006 ה\u0005פסוקים נאמרו\u0006 כך\u0005]:\u0006 \u0003\"ואת חלב החטאת יקטיר המזבחה\"\u0004 (ויקרא טז, כה), \u0003והדר\u0004 \u0005[ואחר כך]\u0006 נאמר: \u0003\"ואת פר החטאת ואת שעיר החטאת\u0004 אשר הובא את דמם לכפר בקודש יוציא אל מחוץ למחנה ושרפו...\u0003\"\u0004 (ויקרא טז, כז) \u0003ואילו אנן תנן\u0004 \u0005[אנו שנינו במשנה]:\u0006 \u0003הרואה את כהן גדול כשהוא קורא\u0004 את הפרשה — \u0003אינו רואה פר ושעיר הנשרפין\u0004 בזמן קריאת התורה. הרי שזמן שריפתם בעוד הכהן לובש את בגדי הלבן, \u0003ואילו אמורי חטאת\u0004 לדברי הכל \u0003בתר הכי מקטיר להו\u0004 \u0005[אחר כך מקטיר אותם],\u0006 הרי שאף כתובים אלה לא נאמרו כפי סדר העבודה הנכון!","ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003חוץ מפסוק זה ואילך,\u0004 שמאותו פסוק ואילך שוב אין סדר בעבודה כסדר הכתובים.","ושואלים: \u0003ומאי חזית דמשבשת קראי, שביש מתניתא\u0004 \u0005[ומה ראית לשבש את\u0006 סדר \u0005הכתובים,\u0006 מוטב \u0005שתשבש את המשנה],\u0006 ותאמר שסדר הדברים האמור במשנה לאו דווקא הוא, ויש אכן לעשות כסדר הכתוב בתורה!","\u0003אמר אביי:\u0004 לאחר שעסק הכתוב בענין הקטרת האימורים \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"והמשלח\u0004 את השעיר...\u0003\"\u0004 (ויקרא טז, כו), ומיד לאחריו: \u0003\"והשרף\u0004 אותם\u0003\"\u0004 (ויקרא טז, כח), לומר: \u0003מה משלח\u0004 אף על פי שנכתב לאחר הקטרת האימורים, בכל זאת זמנו בתוך סדר העבודה \u0003דמעיקרא\u0004 \u0005[שמתחילה],\u0006 שנעשה קודם לכן ואכן אינו כתוב כאן כסדר המאורעות, וכפי שאכן ניתן להבין מתחילת הפרשה, \u0003אף שורף\u0004 יש לומר שהוא כמו כן \u0003דמעיקרא\u0004 \u0005[שמתחילה]\u0006 שהיה כבר קודם.","ודוחים: \u0003אדרבה,\u0004 אמור והשווה כך: הרי הציווי אודות שריפת הפר והשעיר נאמר בכתוב לאחר הקטרת האימורים ואם כן יש לומר הפוך: \u0003מה שורף דהשתא\u0004 \u0005[של עכשיו],\u0006 ששריפת הפר והשעיר נעשית לאחר הקטרת האימורים, — \u0003אף משלח דהשתא\u0004 \u0005[של עכשיו]\u0006 ונשנה ונקבע שאף שילוח השעיר יהא מאוחר לשאר הקרבנות!","ומשיבים: הלשון המיוחדת \u0003\"והמשלח\",\u0004 ודאי \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003משמע,\u0004 שאינו אלא חוזר ומדבר אודות המשלח והשילוח שנעשה קודם ושכבר דובר אודותיו. \u0003רבא אמר:\u0004 שילוח השעיר ודאי במקומו נאמר, שהרי \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"והשעיר אשר עלה עליו הגורל לעזאזל \u0003יעמד חי\u0004 לפני ה' לכפר עליו\" (ויקרא טז, י), ללמד: \u0003עד מתי יהא זקוק לעמוד חי — עד שעת כפרה. ואימתי שעת כפרה — בשעת מתן דמים, ותו לא\u0004 \u0005[ולא עוד].\u0006 משמע שזמן שילוחו קודם לשאר סדר העבודה.","ומוסיפים לענין מנהגי יום הכיפורים: \u0003אתי\u0004 \u0005[בא]\u0006 ה\u0003משלח\u0004 למחרת יום הכיפורים, \u0003מצאו בשוק,\u0004 כלומר: במקום פומבי, \u0003לכהן גדול, אומר לו\u0004 בלשון זו: \u0003אישי\u0004 (אדוני) \u0003כהן גדול! עשינו שליחותך,\u0004 שקיימנו מצות שילוח השעיר. ואם \u0003מצאו בביתו, אומר לו\u0004 בלשון אחרת: \u0003מחיה חיים\u0004 (הקדוש ברוך הוא), \u0003עשינו שליחותו.\u0004 כי לשון \"עשינו שליחותך\" שאומר לו בנוכחות אנשים אחרים אינו אלא לכבדו בפני הבריות, אבל בינו לבין עצמו אינו צריך לכך ולכן מדייק בלשונו לומר שעשה שליחותו של הקדוש ברוך הוא כציווי הכתוב.","כיון שהזכרנו נוסח ברכה של \"מחיה חיים\" מביאים מה ש\u0003אמר רבה: כי מיפטרי רבנן מהדדי\u0004 \u0005[כאשר חכמים נפרדים זה מזה]\u0006 \u0003בפומבדיתא אמרי הכי\u0004 \u0005[\u0006היו \u0005אומרים כך]:\u0006 \u0003\"מחיה חיים יתן לך חיים ארוכים וטובים ומתוקנין\".\u0004","אגב לשון זו של \"מחיה חיים\" מסבירים מה שנאמר \u0003\"אתהלך לפני ה' בארצות החיים\"\u0004 (תהלים קטז, ט). \u0003אמר רב יהודה: זה מקום שווקים.\u0004 כי במרכז מסחרי גדול מיני מזונות מצויים ויש פרנסה בשפע. ודוד המלך בהיותו נע ונד, התפלל שיהיה תמיד מזונו מצוי.","ועוד, נאמר: \u0003\"כי ארך ימים ושנות חיים ושלום יוסיפו לך\"\u0004 (משלי ג, ב) ותוהים: \u0003וכי יש שנים של חיים ויש שנים שאינן של חיים\u0004 שצריך לומר שיוסיפו דווקא שנות חיים? \u0003אמר ר' אלעזר:\u0004 שנות חיים משמעו חיים טובים — \u0003אלו שנותיו של אדם המתהפכות עליו מרעה לטובה.\u0004 ולכן ראוי שתהא הברכה לא רק לתוספת שנים, אלא גם תוספת חיים טובים.","נאמר: \u0003\"אליכם אישים אקרא\u0004 וקולי אל בני אדם\u0003\"\u0004 (משלי ח, ד) \u0003אמר ר' ברכיה:\u0004 לשון \"אישים\" שמשמעו אמנם אנשים, אך היא צורה הקרובה ללשון \"אשה\" לכן יש לפרשו: \u0003אלו תלמידי חכמים שדומין לנשים,\u0004 לפי שהם תשושים ואינם עוסקים בהרבה דברים ששאר גברים עוסקים בהם — \u0003ועושין גבורה כאנשים\u0004 בתורתם. \u0003ואמר ר' ברכיה\u0004 על אותו כתוב: \u0003הרוצה לנסך יין על גבי המזבח\u0004 בזמן הזה — \u0003ימלא גרונם של תלמידי חכמים יין\u0004 ובכך יקיים מצות ניסוך היין, \u0003שנאמר: \"אליכם אישים אקרא\".\u0004 כלומר: תלמידי חכמים הם כאשה שעל גבי המזבח, והנותן להם יין הריהו כמנסך על גבי המזבח.","כיון שהבאנו מדברי ר' ברכיה מביאים עוד ש\u0003אמר ר' ברכיה: אם רואה אדם שתורה פוסקת מזרעו\u0004 וילדיו אינן מגיעים להיות בני תורה כמותו — \u0003ישא בת תלמיד חכם,\u0004 ועל ידי זה מובטח לו שבניו ממנה יגדלו בתורה, \u0003שנאמר: \"אם יזקין בארץ שרשו ובעפר ימות גזעו\u0004"],["\u0003מריח מים יפריח ועשה קציר כמו נטע\"\u0004 (איוב יד, ח-ט). ומדרש הכתוב: אם גזע המשפחה יבשו מתורה — יטע עצמו במקום מים — משפחת תלמידי חכמים, לפי שהתורה נמשלת למים, ועל ידי כך מובטח לו שיצמיח שוב פירות הראויים לו.","במשנה נאמר שהיו הכל מלווין את הכהן הגדול בדרכו לביתו, \u0003ויום טוב היה עושה לאוהביו. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בכהן גדול אחד שיצא מבית המקדש והוו אזלי כולי עלמא בתריה\u0004 \u0005[והיו הולכים הכל אחריו]\u0006 \u0003כיון דחזיונהו\u0004 \u0005[שראו]\u0006 את \u0003שמעיה ואבטליון\u0004 ראשי הסנהדרין שהם הולכים \u0003שבקוהו לדידיה\u0004 \u0005[עזבו אותו]\u0006 את הכהן הגדול \u0003ואזלי בתר\u0004 \u0005[והלכו אחר]\u0006 \u0003שמעיה ואבטליון\u0004 לחלוק להם כבוד.","\u0003לסוף אתו\u0004 \u0005[לבסוף באו]\u0006 \u0003שמעיה ואבטליון לאיפטורי מיניה\u0004 \u0005[להפרד ממנו]\u0006 מן ה\u0003כהן גדול\u0004 טרם הליכתם לביתם. \u0003אמר להן\u0004 בכעס: \u0003ייתון בני עממין לשלם\u0004 \u0005[יבואו בני העמים לשלום],\u0006 כי שמעיה ואבטליון מבני גרים היו, ולכן רצה להזכיר להם שהם מבני הגויים. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ייתון בני עממין לשלם דעבדין עובדא\u0004 \u0005[יבואו בני העמים לשלום שעושים מעשה]\u0006 של \u0003אהרן\u0004 שהיה אוהב שלום ורודף שלום, \u0003ולא ייתי\u0004 \u0005[ואל יבוא]\u0006 \u0003בר\u0004 \u0005[בן]\u0006 \u0003אהרן לשלם\u0004 \u0005[לשלום]\u0006 \u0003דלא עביד עובדא\u0004 \u0005[שאינו עושה מעשה]\u0006 של \u0003אהרן\u0004 ומקניט שלא כדין את הגרים.","\u0003כהן גדול משמש\u0004 בכל ימות השנה בעבודתו \u0003בשמונה כלים\u0004 (בגדים), \u0003וההדיוט\u0004 משמש \u0003בארבעה.\u0004 ובמה משמש ההדיוט — \u0003בכתונת ומכנסים ומצנפת ואבנט. מוסיף עליו כהן גדול\u0004 עוד ארבעה בגדים: \u0003חשן ואפוד ומעיל וציץ. באלו\u0004 בשמונה בגדים אלו, כשלבוש בהם הכהן הגדול \u0003נשאלין באורים ותומים.\u0004 ומוסיפים: \u0003ואין נשאלין\u0004 באורים ותומים \u0003אלא\u0004 או \u0003למלך\u0004 או \u0003לאב בית דין ולמי שהציבור\u0004 כולו \u0003צריך בו,\u0004 אבל אין שואלים שאלות פרטיות של אדם פרטי.","שנינו: \u0003תנו רבנן, דברים שנאמר בהן\u0004 בתורה שהם עשויים \u0003\"שש\",\u0004 לא רק שלמדים שהם עשויים מפשתן (שש), אלא גם כן ש\u0003חוטן\u0004 (כל אחד מסוגי החוטים ממנו הוא ארוג) צריך להיות \u0003כפול ששה.\u0004 אלו שנאמר בהם \u0003\"משזר\"\u0004 משמע שיש בהם פתיל נוסף וחוטן כפול \u0003שמונה.\u0004 חוטים שארגו מהם את ה\u0003מעיל\u0004 של הכהן גדול היו שזורים מ\u0003שנים עשר\u0004 חוטים. חוטי ה\u0003פרכת\u0004 מ\u0003עשרים וארבעה\u0004 חוטים היו עשויים. \u0003חושן ואפוד\u0004 מ\u0003עשרים ושמונה\u0004 חוטים.","ומבארים: \u0003חוטן כפול ששה מנא לן\u0004 \u0005[מניין לנו]\u0006 — ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויעשו את הכתנת שש\u0004 מעשה אורג לאהרן ולבניו. \u0003ואת המצנפת שש ואת פארי המגבעות שש ואת מכנסי הבד שש משזר\"\u0004 (שמות לט, כז-כח) \u0003חמשה קראי כתיבי\u0004 \u0005[כתובים נאמרו],\u0006 שנאמר ארבע פעמים שש ופעם נוספת נאמר \"בד\" שאף הוא פשתן, ובאה חזרה זו ללמד כמה דברים. \u0003חד לגופיה\u0004 \u0005[\u0006כתוב \u0005אחד\u0006 נאמר \u0005לגופו]\u0006 לעצם ההלכה, ללמד: \u0003דכיתנא ניהוו\u0004 \u0005[שיהיו\u0006 עשויים \u0005פשתן],\u0006 \u0003וחד\u0004 \u0005[ו\u0006כתוב \u0005אחד]\u0006 שנאמר \"שש\", לומר: \u0003שיהא חוטן כפול ששה,\u0004 ש\"שש\" מתפרש — שש פעמים. \u0003וחד\u0004 \u0005[ו\u0006כתוב \u0005אחד]\u0006 שנאמר \"שש\", כוונתו: \u0003שיהיו שזורין\u0004 יחד כל ששת החוטים, מהם עשוי כל חוט. \u0003וחד\u0004 \u0005[ו\u0006כתוב \u0005אחד]\u0006 נוסף שנאמר \"שש\" — ללמד \u0003לשאר בגדים שלא נאמר בהן שש\u0004 במפורש, שאף חוטיהם צריכים להיות שזורים וכפולים. \u0003וחד\u0004 \u0005[ו\u0006כתוב \u0005אחד]\u0006 בא \u0003לעכב,\u0004 לומר: שאין לעשותם באופן אחר ואם שינה פסל.","ושואלים: \u0003מאי משמע\u0004 \u0005[מהיכן שומעים\u0006 אנו\u0005]\u0006 בכלל \u0003דהאי\u0004 \u0005[שזה]\u0006 ה\u0003\"שש\" כיתנא\u0004 \u0005[פשתן]\u0006 \u0003הוא? אמר ר' יוסי בר' חנינא:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 גם \"שש\" וגם \u0003\"בד\",\u0004 ו\"בד\" נדרש: \u0003דבר העולה מן הקרקע בד בד,\u0004 כלומר: כל חוט לעצמו, וכך הם חוטי הפשתן שכל גבעול צומח לבדו, ואינו כשאר הצמחים כגון צמר גפן שחוטיו סבוכים זה בזה. ומקשים: \u0003ואימא עמרא\u0004 \u0005[ואמור\u0006 שהכוונה היא \u0005לצמר],\u0006 שאף בו כל נימה צומחת לבדה! ומשיבים: \u0003עמרא איפצולי מיפצלא\u0004 \u0005[הצמר מפוצל הוא],\u0006 שכל שערה מתחלקת לכמה שערות, ואם כן אינו מוגדר לגמרי כ\"בד\". ומקשים: \u0003כיתנא נמי איפצולי מפציל\u0004 \u0005[פשתן גם כן מתפצל הוא]\u0006 לנימים בודדות! ומשיבים: אינו דומה, \u0003כיתנא אגב לקותיה מפציל\u0004 \u0005[הפשתן,\u0006 בניגוד לצמר, \u0005מתוך שמכים עליו הוא מתפצל]\u0006 אבל בדרך צמיחתו צומח הוא אחד אחד, ולא בפיצולים.","\u0003רבינא אמר מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה לדבר, שנאמר בפירוש בספר יחזקאל: \u0003\"פארי פשתים יהיו על ראשם ומכנסי פשתים יהיו על מתניהם\"\u0004 (יחזקאל מד, יח), משמע ש\"שש\" ו\"בד\" שנאמר בתורה, פשתים הם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי: הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 \u0003מקמי דאתי\u0004 \u0005[לפני שבא]\u0006 \u0003יחזקאל מאן אמרה\u0004 \u0005[מי אמר אותה]\u0006 וכיצד ידעו אותה? ענה לו רבינא: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה מקשה כך, \u0003הא דאמר\u0004 \u0005[זו שאמר]\u0006 \u0003רב חסדא\u0004 בענין אחר: \u0003דבר זה מתורת משה רבינו לא למדנו\u0004 שאינו כתוב בתורה במפורש, \u0003מדברי יחזקאל בן בוזי למדנו\u0004 והיא ההלכה שנאמרה ביחזקאל: \u0003\"כל בן נכר ערל לב וערל בשר לא יבא אל מקדשי (לשרתני)\"\u0004(יחזקאל מד, ט), ואם כן, \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 שמשומד וערל אינו עובד \u0003מקמי דאתי\u0004 \u0005[לפני שבא]\u0006 \u0003יחזקאל מאן אמרה\u0004 \u0005[מי אמר אותה]\u0006 וכיצד ידעו מה לעשות? אלא על כרחך \u0003גמרא גמירי לה\u0004 \u0005[במסורת היו למודים אותה]\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003יחזקאל ואסמכה אקרא\u0004 \u0005[והסמיכה לפסוק\u0006 וכתבה\u0005]\u0006 \u0003הכא נמי\u0004 \u0005[אף כאן]\u0006 \u0003גמרא גמירי לה\u0004 \u0005[במסורת היו למודים אותה]\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003יחזקאל ואסמכה אקרא\u0004 \u0005[והסמיכה לפסוק\u0006 וכתבה\u0005].\u0006","וממשיכים לבאר את הברייתא: \u0003\"משזר\" — שמונה.\u0004 ושואלים: \u0003מנא לן\u0004 \u0005[מניין לנו]\u0006 שכך הוא? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויעשו על שולי המעיל רמוני תכלת וארגמן ותולעת שני משזר\"\u0004 (שמות לט, כד) \u0003ויליף\u0004 \u0005[ולמדים]\u0006 בגזירה שוה \u0003\"משזר\" \"משזר\"\u0004 ממה שנאמר גם \u0003בפרכת, מה להלן\u0004 בפרוכת \u0003עשרים וארבעה\u0004 חוטים (כאשר יבואר להלן) \u0003אף כאן עשרים וארבעה\u0004 חוטים בסך הכל, וכיון שרימונים אלה עשויים משלושה מינים, תכלת וארגמן ותולעת שני, משמע \u0003דהוה כל חד וחד תמני\u0004 \u0005[שהיה כל אחד ואחד\u0006 מהם \u0005של שמונה\u0006 חוטים\u0005].\u0006","ושואלים: \u0003ונילף\u0004 \u0005[ונלמד]\u0006 \u0003מחשן ואפוד,\u0004 ונאמר: \u0003מה להלן\u0004 בחושן ואפוד מ\u0003עשרים ושמונה\u0004 הם עשויים, \u0003אף כאן עשרים ושמונה\u0004 חוטים בסך הכל! ומשיבים: \u0003דנין דבר\u0004 (פרוכת) \u0003שלא נאמר\u0004 שהיו שזורים \u0003בו\u0004 גם חוטי \u0003זהב, מדבר שלא נאמר בו זהב\u0004 כרימוני המעיל, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003חשן ואפוד שנאמר בהן זהב.\u0004 ומקשים: \u0003אדרבה,\u0004 להיפך אם צריכים להחליט כיצד להשוות, נאמר: ראוי שיהיו \u0003דנין בגד מבגד\u0004 שהרי המעיל הוא בגד כמו החושן והאפוד, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003פרוכת\u0004 ש\u0003אהל הוא\u0004 והיא חלק מבנין המקדש!","\u0003אלא\u0004 חוזרים אנו מהלימוד הראשון, וכך למדים: \u0003דנין\u0004 ולמדים \u0003מאבנט,\u0004 שהיו בו בסך הכל עשרים וארבעה חוטים, \u0003ודנין\u0004 כל \u0003בגד ודבר שלא נאמר בו זהב,\u0004 מאבנט שהוא \u0003בגד ודבר שלא נאמר בו זהב, ואין דנין דבר שאין בו זהב\u0004 כרימוני המעיל \u0003מדבר שיש בו זהב\u0004 כחושן ואפוד.","\u0003רב מרי אמר: \"תעשנו\"\u0004 (שמות כח, טו) \u0003כתיב\u0004 \u0005[נאמר]\u0006 בחושן, לומר: \u0003תעשנו לזה ולא לאחר,\u0004 שאין ללמוד ממנו לענין שזירה אחרת.","\u0003רב אשי אמר: \"ועשית\"\u0004 (שמות כח, לג) \u0003כתיב\u0004 \u0005[נאמר]\u0006 ברימונים, ללמד: \u0003שיהיו כל עשיות שוות,\u0004 כלומר: שיהיו החוטים מהמינים השונים שווים זה לזה, אולם אם יהיו שם בסך הכל עשרים ושמונה חוטים, הרי אין יכולים לעשות שכל מין יהיה בו מספר שוה של חוטים. כי \u0003היכי נעביד\u0004 \u0005[כיצד נעשה]?\u0006 \u0003נעביד תלתא\u0004 \u0005[נעשה שלושה]\u0006 של \u0003עשרה עשרה\u0004 — אם כן \u0003הוו ליה תלתין\u0004 \u0005[הרי הם שלושים]\u0006 והם יותר מבחושן! \u0003נעביד תרי\u0004 \u0005[נעשה שנים]\u0006 של \u0003תשעה תשעה, וחד\u0004 \u0005[ואחד]\u0006 של \u0003עשרה\u0004 הלא \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ועשית\" — שיהיו כל עשיותיו שוות,\u0004 ולכן בהכרח עלינו ללמוד מדבר שמספר חוטיו מתחלק לשלוש, והוא מן הפרוכת.","ועוד לבירור הברייתא, נאמר בה שהיו חוטי ה\u0003מעיל\u0004 שזורים מ\u0003שנים עשר\u0004 חוטים כל אחד. ושואלים: \u0003מנא לן\u0004 \u0005[מניין לנו]\u0006 דבר זה — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועשית את מעיל האפוד\u0004"],["\u0003כליל תכלת\"\u0004 (שמות כח, לא) \u0003ויליף\u0004 \u0005[ולומד]\u0006 בגזירה שוה \u0003\"תכלת\" \"תכלת\" מפרוכת מה להלן\u0004 בפרוכת היו חוטי התכלת של \u0003ששה, אף כאן\u0004 של \u0003ששה\u0004 וכיון שנאמר \"כליל\" שמשמעו דבר השזור יחד, למדנו שכל החוטים היו כפולים והרי כאן בסך הכל שנים עשר.","ומקשים: \u0003ונילף\u0004 \u0005[ושנלמד]\u0006 \u0003משוליו ורמוניו\u0004 של המעיל הכתובים להלן \u0003ומה להלן\u0004 (שמות כח, לא) עשוי כל חוט מ\u0003שמונה\u0004 חוטים, \u0003אף כאן שמונה!\u0004 ודוחים: \u0003דנין כלי\u0004 (בגד) \u0003מכלי, ואין דנין כלי\u0004 מדבר שהוא רק \u0003תכשיט כלי\u0004 כרימוני המעיל.","ומקשים: \u0003אדרבה\u0004 ההיפך מסתבר: \u0003דנין גופו מגופו\u0004 את גוף המעיל מהרימונים שבו \u0003ואין דנין גופו מעלמא\u0004 \u0005[מן העולם,\u0006 מדבר אחר\u0005]\u0006 ומשיבים: \u0003היינו דאמרינן\u0004 \u0005[זה שאמרנו]\u0006 מתחילה בברייתא שנאמר \"שש\" יתר כדי ללמד \u0003לשאר בגדים שלא נאמר בהן שש,\u0004 והכוונה היא שיהיו של ששה ולא של שמונה חוטים מתחילתם.","נאמר עוד בברייתא כי כל חוט מחוטי ה\u0003פרכת\u0004 היה עשוי מ\u0003עשרים וארבעה\u0004 חוטים. כיצד? — \u0003ארבעה\u0004 מינים של \u0003שיתא שיתא\u0004 \u0005[שש שש]\u0006 ודבר זה ברור ו\u0003לא דינא ולא דיינא\u0004 \u0005[אין דין ואין דיין]\u0006 להשיג על כך, כי הלא בפרוכת ארבעה מינים (שש, ארגמן, תולעת שני ותכלת) וכל אחד מהן נעשה מששה חוטים, כפי שאמרנו שכל דבר שלא נתפרש נעשה מששה.","\u0003חשן ואפד\u0004 שכל חוט ממנו הם עשויים מ\u0003עשרים ושמונה\u0004 חוטים הוא \u0003מנא לן\u0004 \u0005[מניין לנו]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועשית חשן משפט מעשה חשב כמעשה אפד תעשנו זהב תכלת וארגמן ותולעת שני ושש משזר\"\u0004 (שמות כח, טו) \u0003ארבעה\u0004 מינים מהם עשוי האריג \u0003דשיתא שיתא\u0004 \u0005[של ששה ששה]\u0006 חוטים הם, הרי \u0003עשרין וארבעה,\u0004 וחוט נוסף של \u0003זהב\u0004 שטווים עם כל מין ומין, נמצא \u0003ארבעה\u0004 חוטים נוספים, \u0003הא עשרין ותמניא\u0004 \u0005[הרי עשרים ושמונה].\u0006","ומקשים \u0003ואימא\u0004 \u0005[ואמור]\u0006 שגם חוט של \u0003זהב נמי\u0004 \u0005[גם כן]\u0006 מ\u0003ששה\u0004 חוטים הוא עשוי! \u0003אמר רב אחא בר יעקב: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"וירקעו את פחי הזהב \u0003וקצץ פתילם\u0004 לעשות בתוך התכלת ובתוך הארגמן ובתוך תולעת השני ובתוך השש מעשה חושב\" (שמות לט, ג). \u0003\"פתיל\"\u0004 פירושו חוט כפול שאפשר לפתלו, \u0003\"פתילים\"\u0004 לשון רבים — \u0003הרי כאן ארבעה.\u0004","\u0003רב אשי אמר:\u0004 מגוף הענין אפשר ללמוד זאת, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לעשות בתוך התכלת ובתוך הארגמן\"\u0004 (שמות לט,ג), משמע שבתוך ארבעת המינים יש לעשות את חוטי הזהב. ומעתה \u0003היכי נעביד\u0004 \u0005[כיצד נעשה]?\u0006 \u0003נעביד\u0004 \u0005[נעשה]\u0006 \u0003ארבעה\u0004 חוטים שכל אחד מהם של \u0003תרי תרי\u0004 \u0005[שניים שנים],\u0006 אם כן \u0003הוו להו תמניא\u0004 \u0005[הרי הם שמונה]\u0006 ולא נתפרש מספר זה בכתוב כלל. \u0003נעביד תרי דתרי תרי\u0004 \u0005[נעשה שנים של שנים שנים]\u0006 \u0003ותרי דחד חד\u0004 \u0005[ושנים של אחד אחד] —\u0006 הלא נאמר \u0003\"ועשית\",\u0004 ללמד: \u0003שיהיו כל עשיותיו\u0004 של כל מין אריג \u0003שוות\u0004 ובכלל זה אף מנין החוטים מהם עשוי כל חוט, ולכן בהכרח יש לעשות ארבעה כדי לקיים את הכתובים בענין זה.","\u0003אמר רחבא אמר רב יהודה: המקרע בגדי כהונה\u0004 במזיד עובר על מצות לא תעשה ו\u0003לוקה. שנאמר: \"\u0004שפה יהיה לפיו סביב מעשה אורג כפי תחרא יהיה לו \u0003לא יקרע\"\u0004 (שמות כח, לב), שהוא מצות לא תעשה שלא לקרוע פי המעיל, וכן הדין בשאר בגדי כהונה. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אחא בר יעקב: ודילמא הכי קאמר רחמנא\u0004 \u0005[ושמא כך אמרה\u0006 והתכוונה \u0005התורה\u0006 בדבריה\u0005]:\u0006 \u0003נעביד ליה\u0004 \u0005[שיעשה לו]\u0006 למעיל \u0003שפה כי היכי דלא ניקרע\u0004 \u0005[כדי שלא יקרע]\u0006 \"ולא יקרע\" אינו לשון איסור אלא ביטוי של שלילה, ואין ללמוד מכאן שיש בכך משום איסור ועונש מלקות! ודוחים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"שלא יקרע\"?\u0004 הלא נאמר \"לא יקרע\" ללמד שיש איסור מיוחד בקריעתו.","וכעין זה \u0003אמר ר' אלעזר: המזיח חושן מעל האפוד\u0004 או \u0003המסיר בדי ארון\u0004 מן הטבעות עובר על מצות לא תעשה ו\u0003לוקה. שנאמר: \"\u0004ו\u0003לא יזח\u0004 החושן מעל האפוד\u0003\"\u0004 (שמות כח, כח), וכן נאמר: \"בטבעות הארון יהיו הבדים \u0003לא יסרו\u0004 ממנו\" (שמות כה, טו). \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אחא בר יעקב: ודילמא כי קאמר רחמנא חדקינהו ועבדינהו שפיר\u0004 \u0005[שמא כאשר אמרה התורה חזק אותם ועשה אותם יפה]\u0006 \u0003כדי שלא יזח\u0004 החושן מעל האפוד וש\u0003לא יסורו\u0004 הבדים! ודוחים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"שלא יזח\" ו\"שלא יסרו\",\u0004 הלא אין כתוב כן, אלא מלשון הכתוב למדים שלא רק שיש לעשותם כן, אלא כל העובר על כך חייב.","\u0003ר' יוסי בר' חנינא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 מצד אחד: \u0003\"בטבעת הארן יהיו הבדים לא יסרו ממנו\"\u0004 (שמות כה, טו) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"והובא את בדיו בטבעת\"\u0004 (שמות כז, ז), משמע שמכניסים בכל פעם את הבדים בתוך הטבעות, הרי שאינם קבועים במקומם לעולם! \u0003הא כיצד?\u0004 ומשיבים: \u0003מתפרקין ואין נשמטין.\u0004 כלומר: יכולים להזיזם קצת ממקומם אבל אינם נשמטים לגמרי מן הטבעות. שהיו הבדים עבים בקצותיהם ודקים יותר בין הקצוות ומחמת עובי הקצוות היו תוחבים אותם בכוח לתוך הטבעות ומכיון שהוכנסו כבר, שוב אינם יכולים לצאת מעצמם, אף שיכולים הם לזוז במקומם קצת לכאן ולכאן.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 נאמר: \u0003\"בטבעת הארן יהיו הבדים\u0004 לא יסורו ממנו\u0003\"\u0004 (שמות כה, טו), \u0003יכול לא יהיו זזין ממקומן\u0004 כלל? \u0003תלמוד לומר: \"והובא את בדיו בטבעת\"\u0004 (שמות כז, ז) \u0003אי\u0004 \u0005[אם]\u0006 תאמר \u0003\"והובא את בדיו\" יכול יהיו נכנסין ויוצאין\u0004 לגמרי — \u0003תלמוד לומר: \"בטבעת הארן יהיו הבדים\u0004 לא יסורו ממנו\" (שמות כה, טו). \u0003הא כיצד? מתפרקין\u0004 זה מזה, \u0003ואין נשמטין\u0004 כליל.","כיון שהוזכר הארון מביאים מה ש\u0003אמר ר' חמא בר' חנינא מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"\u0004ועשית את הקרשים למשכן \u0003עצי שטים עמדים\"\u0004 (שמות כו, טו), לומר: \u0003שעומדים דרך גדילתן,\u0004 כלומר: קרשי המשכן שהיו עשויים עצי שיטים היו עומדים כדרך עמידתו של העץ מהם הם עשויים בשעת גידולו. כלומר: שחלקו העליון של העץ בשעת גידולו היה מונח גם במשכן כלפי מעלה. \u0003דבר אחר: \"עומדים\"\u0004 פירושו: \u0003שמעמידין\u0004 (מחזיקים) \u0003את צפויין\u0004 שלא יפול, שהיה זה מחובר אליהם במסמרים. \u0003דבר אחר: \"עומדים\"\u0004 שאמר הכתוב, ללמדנו דבר אחר בא. כי \u0003שמא תאמר אבד סברן ובטל סכויין\u0004 ולא ישובו יותר לאחר גניזתם — \u0003תלמוד לומר: — \"עמדים\"\u0004 לומר: \u0003שעומדין לעולם ולעולמים.\u0004","ועוד לענין בגדי כהונה: \u0003אמר ר' חמא בר' חנינא: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"את בגדי השרד לשרת בקדש\"\u0004 (שמות לה, יט)."],["\u0003אלמלא בגדי כהונה\u0004 (\"בגדי השרד\"), שלבושים בהם הכהנים בשעת הקרבת הקרבנות המכפרים על בני ישראל, \u0003לא נשתייר משונאיהן של ישראל\u0004 (בלשון נקיה, והכוונה מישראל) \u0003שריד ופליט\u0004 ולכן קרויים הם בגדי השרד — בגדים שגורמים שישרדו, ישארו בעולם.","\u0003ר' שמואל בר נחמני אמר: דבי\u0004 \u0005[בן בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שמעון תנא\u0004 \u0005[שנה]:\u0006 מדוע נקראים הם \"בגדי השרד\" — כי בגדי כהונה \u0003גורדין\u0004 (אורגים) \u0003אותן כברייתן מכליהן,\u0004 שאין בגדי כהונה נארגים ונתפרים כשאר בגדים אלא נארגים כיריעה עגולה וסגורה שאינה צריכה תפירה, \u0003ומשרדין\u0004 (משאירים) \u0003מהן כלום\u0004 (משהו) ולכן קוראים להם \"בגדי השרד\". ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 אותו שריד, החלק שלא נארג? \u0003ריש לקיש אמר: אלו מעשה מחט,\u0004 שיש גם לתפור משהו מהם.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]:\u0006 הרי שנינו \u0003בגדי כהונה אין עושין אותן מעשה מחט, אלא מעשה אורג,\u0004 שהרי \u0003נאמר\u0004 בהם: \u0003\"מעשה ארג\"\u0004 (שמות כח, לב)! \u0003אמר אביי: לא נצרכה\u0004 עשייה במחט \u0003אלא לבית יד\u0004 (שרוול) \u0003שלהם. כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003בית יד של בגדי כהונה נארגת בפני עצמה, ונדבקת עם הבגד\u0004 בתפירה, \u0003ומגעת\u0004 באורך \u0003עד פיסת\u0004 (כף) \u0003היד.\u0004","ועוד בענין כלי המקדש \u0003אמר רחבה אמר רב יהודה: שלש ארונות עשה בצלאל, אמצעי של עץ\u0004 שהיה גובהו מבחוץ \u0003תשעה\u0004 טפחים, ועוד ארון \u0003פנימי\u0004 לו שהיה עשוי \u0003של זהב\u0004 והיה גובהו החיצוני \u0003שמונה\u0004 טפחים, והיו מכניסים אותו בתוך ארון העץ והיה הוא ממלא את כל החלל, וארון נוסף \u0003חיצון\u0004 לשניהם של זהב, שהיה גובהו מבחוץ \u0003עשרה\u0004 טפחים \u0003ומשהו\u0004 והיו מכניסים את ארון העץ לתוכו והיה זה ממלא את כל חללו.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שהיה החיצון \u0003אחד עשר\u0004 טפחים \u0003ומשהו!\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]\u0006 \u0003הא כמאן דאמר\u0004 \u0005[זה\u0006 שנאמר שהיה אחד עשר טפחים, הרי זה \u0005לשיטת האומר]\u0006 כי \u0003יש בעביו\u0004 של ציפוי הזהב לארון \u0003טפח\u0004 ואם כן יש בו טפח אחד מלמטה, ועשרה נוספים כדי גובה הארון וכפורת. \u0003הא כמאן דאמר\u0004 \u0005[זה\u0006 שנאמר שהיה גובהו עשרה טפחים, הרי \u0005לשיטת האומר]\u0006 כי \u0003אין בעביו\u0004 של הציפוי \u0003טפח\u0004 ולכן לא היה מגיע גובהו לאחד עשר טפחים. \u0003ומאי\u0004 \u0005[ומהו]\u0006 \u0003משהו\u0004 זה ששניהם מוסיפים — \u0003זיר\u0004 (קישוט כעין נזר) שהיה על הארון.","\u0003אמר ר' יוחנן: שלשה זירים הן\u0004 על כלי הקודש: \u0003של מזבח, ושל ארון, ושל שלחן.\u0004 וכיון שצורתם כעין נזר, מסמלים הם שלטון ושררה. זר \u0003של מזבח\u0004 שמקריבים עליו, הוא סימן לכתר כהונה — \u0003זכה אהרן ונטלו,\u0004 שנטל לבניו את עטרת הכהונה לדורות. זר \u0003של שלחן\u0004 שמסמל את השפע ואת הברכה שהוא סימן לכתר מלכות — \u0003זכה דוד ונטלו,\u0004 להיות לו ולבניו אחריו. זר \u0003של ארון\u0004 שהוא סימן לכתר תורה — \u0003עדיין מונח הוא\u0004 ולא זכה בו אדם לצמיתות, ו\u0003כל הרוצה ליקח — יבא ויקח\u0004 ויתעטר בכתר תורה. \u0003שמא תאמר פחות הוא\u0004 משני הכתרים האחרים ולכן לא נטלוהו — \u0003תלמוד לומר:\u0004 מה שנאמר בחכמה — \u0003\"בי מלכים ימלכו\"\u0004 (משלי ח, טו), משמע שמכוח כתר תורה באים שאר הכתרים, וגדול הוא מהם.","\u0003ר' יוחנן רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[כתוב]:\u0006 \u0003\"זר\"\u0004 (וקוראו כאילו היה נקוד בקמץ) \u0003וקרינן\u0004 \u0005[וקוראים אנו]\u0006 \u0003\"זיר\"\u0004 (בצירה), לומר: אם \u0003זכה\u0004 לעשות ללמוד לשמה ולקיימה — \u0003נעשית לו זיר\u0004 (כתר), \u0003לא זכה — זרה\u0004 התורה \u0003הימנו\u0004 ומשתכחת ממנו.","\u0003ר' יוחנן רמי\u0004 \u0005[השליך\u0006 הראה סתירה\u0005]:\u0006 נאמר במקום אחד: \u0003\"ועשית לך ארון עץ\"\u0004 (דברים י, א) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ועשו ארון עצי שטים\"\u0004 (שמות כה, י) ואם כן לא נתברר אם הדבר מוטל על משה לבדו או על כל העדה, אלא \u0003מכאן לתלמיד חכם שבני עירו מצווין לעשות לו מלאכתו.\u0004 כלומר: אף שנאמר הציווי למשה — כל בני ישראל חייבים לעשות מלאכה זו עבורו. וכן לדורות, ראוי לסייע לתלמיד חכם במלאכתו כדי שיוכל לפנות עצמו לתורה.","נאמר בארון: \u0003\"מבית ומחוץ תצפנו\"\u0004 (שמות כה, יא). \u0003אמר רבא:\u0004 יש בכך רמז המלמדנו: \u0003כל תלמיד חכם שאין תוכו\u0004 ביראת שמים ובהנהגות טובות \u0003כברו\u0004 כמו שהוא נראה מבחוץ, אלא מבפנים אינו ירא שמים כל כך — \u0003אינו\u0004 נקרא \u0003תלמיד חכם.\u0004 שכדוגמת הארון שהיתה חזותו הפנימית והחיצונית שווה, כן צריך להיות אף התלמיד חכם.","\u0003אמר אביי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רבה בר עולא:\u0004 תלמיד חכם שאינו נוהג כשורה בסתר \u0003נקרא נתעב, שנאמר: \"אף כי נתעב ונאלח איש שתה כמים עולה\"\u0004 (איוב טו, טז), שאף שהוא שותה את התורה כמים, בכל זאת יש בו עולה, וכיון שכך הריהו נתעב ונאלח.","\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"למה זה מחיר ביד כסיל לקנות חכמה ולב אין\"\u0004 (משלי יז, טז), הרי בא לומר: \u0003אוי להם לשנאיהן של תלמידי חכמים\u0004 (בלשון נקיה, והכוונה לתלמידי חכמים) כאלה \u0003שעוסקין בתורה ואין בהן יראת שמים,\u0004 והוא הנקרא כסיל, שבא לקנות חכמה של תורה, אבל לב של יראת שמים אין לו.","כעין זה \u0003מכריז\u0004 היה \u0003ר' ינאי: חבל על\u0004 מי \u0003דלית ליה דרתא\u0004 \u0005[שאין לו חצר]\u0006 \u0003ותרעא לדרתיה עביד\u0004 \u0005[ושער לחצרו הוא עושה],\u0006 כי יראת שמים היא חצירו של ה', והתורה היא פתח לחצר, וחבל על מי שעוסק בתורה מבלי שתהא בו יראת שמים.","וכיוצא בזה היה אומר להם \u0003רבא לרבנן\u0004 \u0005[לחכמים]:\u0006 \u0003במטותא מיניכו\u0004 \u0005[בבקשה מכם],\u0006 עשו ש\u0003לא תירתון תרתי\u0004 \u0005[תירשו שני]\u0006 \u0003גיהנם.\u0004 שאם אין אתם עוסקים בתורה מתוך יראת שמים, הרי בעולם הזה אתם עמלים בתורה ואינכם זוכים ליהנות מן העולם והריהו לכם כגיהנם, ולעולם הבא כיון שאין בכם יראת שמים תירשו גיהנם, ואם כן יהא לכם גיהנם כאן ושם.","\u0003אמר ר' יהושע בן לוי: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"וזאת התורה אשר שם משה\"\u0004 (דברים ד, מד) \"שם\" נשמע כמו \"סם\", ללמד, כי מי ש\u0003זכה — נעשית לו\u0004 התורה \u0003סם חיים,\u0004 ואם \u0003לא זכה — נעשית לו סם מיתה. והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר רבא: דאומן לה\u0004 \u0005[\u0006מי \u0005שמאומן בה\u0006 בתורה\u0005]\u0006 ועוסק בה ואוהב אותה — בשבילו היא \u0003סמא דחייא\u0004 \u0005[סם חיים],\u0006 אבל \u0003דלא אומן בה סמא דמותא\u0004 \u0005[מי שלא מאומן בה\u0006 הרי היא בשבילו \u0005סם המוות].\u0006","\u0003אמר ר' שמואל בר נחמני: ר' יונתן רמי\u0004 \u0005[\u0006היה \u0005משליך,\u0006 מראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"פקודי ה' ישרים משמחי לב\"\u0004 (תהלים יט, ט) ונאמר: \u0003\"אמרת ה' צרופה\"\u0004 (תהלים יח, לא) משמע: כדרך הצורף שמצרף באש. ותירץ כך: מי ש\u0003זכה\u0004 — התורה \u0003משמחתו,\u0004 מי ש\u0003לא זכה — צורפתו. ריש לקיש אמר: מגופיה דקרא נפקא\u0004 \u0005[מגופו של\u0006 אותו \u0005כתוב יוצאת]\u0006 מסקנה זו: מי ש\u0003זכה — צורפתו\u0004 התורה \u0003לחיים, לא זכה — צורפתו למיתה.\u0004","נאמר עוד: \u0003\"יראת ה' טהורה עומדת לעד\"\u0004 (תהלים יט, י). \u0003אמר ר' חנינא: זה הלומד תורה בטהרה,\u0004 שהיא העומדת לו לעד. ושאלו: \u0003מאי היא\u0004 \u0005[מה היא],\u0006 מה הכוונה למעשה? — זה הוא ש\u0003נושא אשה ואחר כך לומד תורה,\u0004 שאין ליבו טרוד בהרהורי עבירה, ואינו עלול לבוא לידי טומאה.","נאמר שם עוד: \u0003\"עדות ה' נאמנה\"\u0004 (תהלים יט, ח), \u0003אמר ר' חייא בר אבא: נאמנה היא להעיד בלומדיה,\u0004 מי למד ומי לא. ושוב לענין בגדי הקודש.","נאמר בהם: \u0003\"מעשה רקם\"\u0004 (שמות כו, לו) ונאמר גם \u0003\"מעשה חשב\"\u0004 (שמות כו, לא) \u0003אמר ר' אלעזר: שרוקמין במקום שחושבין.\u0004 כלומר: קודם יוצרים את הצורה בצבע או באופן אחר ואחר כך רוקמין שם.","\u0003תנא\u0004 \u0005[שנה החכם]\u0006 משמו של \u0003ר' נחמיה: \"רוקם\",\u0004 פירושו: \u0003מעשה מחט. לפיכך\u0004 הרי הם \u0003פרצוף אחד.\u0004 כלומר: כיון שנעשית על ידי מחט העוברת משני צידי הפרוכת במקביל, הרי שנעשית בשני הצדדים דמות זהה של פרצוף אחד. \u0003\"חושב\" — מעשה אורג, לפיכך\u0004 הרי הם \u0003שני פרצופות.\u0004 שאף שנעשים כאחת, אין הדמויות הרקומות משני צידי הפרוכת זהות זו לזו, שלפעמים היתה מצד אחד דמות נשר ומצידה השני היתה דמות אריה.","שנינו במשנה: בשמונה בגדי כהונה \u0003אלו נשאלין באורים ותומים. כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: בגדים שכהן גדול משמש בהן,\u0004 אף כהן \u0003משוח מלחמה,\u0004 הכהן הממונה לקרוא לפני העם בצאתם למלחמה דברי חיזוק (דברים כ, ב), \u0003משמש בהן, שנאמר: \"ובגדי הקדש אשר לאהרן יהיו לבניו אחריו\"\u0004 (שמות כט, כט), וכוונתו \u0003למי שבא בגדולה אחריו,\u0004 ולאחר גדולת אהרן, שהוא כהן גדול, הדרגה הבאה היא דרגת כהן משוח מלחמה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב אדא בר אהבה ואמרי לה כדי\u0004 \u0005[ויש אומרים סתם]\u0006 בלא שם המקשה, שלא ידעו מי הוא זה שהקשה, ששנינו: \u0003יכול יהא בנו‍ של משוח מלחמה משמש תחתיו\u0004 שתהיה לו זכות לתפקיד זה \u0003כדרך של כהן גדול\u0004 שבנו \u0003משמש תחתיו\u0004 אם רק ראוי הוא לכך —"],["\u0003תלמוד לומר: \"שבעת ימים ילבשם הכהן תחתיו מבניו אשר יבא אל אהל מועד\u0004 לשרת בקודש\u0003\"\u0004 (שמות כט, ל) — דווקא \u0003מי שראוי לבא אל אהל מועד,\u0004 שהוא הכהן הגדול שנכנס לפני ולפנים — הוא בלבד מוריש גדולתו לבניו. \u0003ואם איתא\u0004 \u0005[ואם יש]\u0006 מקום להנחה שכהן משוח מלחמה אף הוא משמש בשמונה בגדים \u0003מיחזא חזי\u0004 \u0005[\u0006הרי \u0005ראוי\u0006 אף \u0005הוא]\u0006 ליכנס לפנים!","\u0003אמר רב נחמן בר יצחק: הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003כל שעיקר משיחתו\u0004 היא כדי להכנס \u0003לאהל מועד\u0004 לצורך עבודה, \u0003יצא זה שעיקר משיחתו\u0004 לצורך ה\u0003מלחמה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 הלא שנינו בברייתא: כהן \u0003משוח מלחמה אינו משמש לא בארבעה\u0004 בגדים \u0003ככהן הדיוט, ולא בשמונה ככהן גדול.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 מכאן אין להביא ראיה, שכן על דין זה גופו יש לתמוה, שהרי \u0003אלא\u0004 כ\u0003זר משוית ליה\u0004 \u0005[עושה אתה אותו],\u0006 שאם אינו לא כהן גדול ולא כהן הדיוט, נמצא שאינו כהן כלל! \u0003אלא\u0004 הטעם אחר הוא: \u0003ככהן גדול\u0004 אינו משמש — \u0003משום איבה,\u0004 שלא תהא איבה בין שני אנשים הלבושים בבגדי כהונה גדולה לפיכך תיקנו שלא יעבוד במקדש, ואילו בארבעה בגדים \u0003ככהן הדיוט\u0004 אינו משמש, \u0003משום\u0004 הכלל: \u0003מעלין בקדש ולא מורידין.\u0004 וכיון שזכה להיות ככהן גדול — שוב אינו יכול לשמש ככהן הדיוט.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר אבא לרבא: והאי תנא\u0004 \u0005[\u0006והרי יש \u0005תנא זה]\u0006 \u0003דלית ליה\u0004 \u0005[שאין לו],\u0006 שאינו מקבל את הנימוק של \u0003איבה,\u0004 ואף לדבריו כהן משוח מלחמה \u0003לא קא\u0004 \u0005[אינו]\u0006 \u0003משמש\u0004 בשמונה בגדים.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה הן ה\u0003דברים שבין כהן גדול לכהן הדיוט? פר כהן משיח ופר הבא על כל המצות\u0004 שכהן גדול מביא על שגגתו בדבר שעל זדונו חייב כרת, \u0003ופר יום הכפורים, ועשירית האיפה\u0004 שכהן גדול מביא בכל יום.","וכן, הכהן הגדול \u0003לא פורע\u0004 (מגדל פרע שער ראשו) לאות אבל, \u0003ולא פורם\u0004 בגדו כאחרים בשעת אבילות, \u0003אבל פורם הוא\u0004 הכהן הגדול את בגדיו \u0003מלמטה,\u0004 במקום שאינו ניכר, \u0003וההדיוט\u0004 פורם \u0003מלמעלה. ואין מטמא\u0004 הכהן הגדול \u0003לקרוביו,\u0004 אבל ההדיוט מותר להטמא לקרובים. \u0003ומצווה\u0004 הכהן הגדול בבואו לשאת אשה, \u0003על\u0004 נשיאת \u0003הבתולה\u0004 דווקא, ולא בעולה, \u0003ומוזהר\u0004 באיסור לא תעשה שלא לשאת את \u0003האלמנה, ומחזיר\u0004 במותו \u0003את הרוצח\u0004 בשגגה מעיר המקלט,","\u0003ומקריב אונן\u0004 ביום האבילות הראשון, אבל \u0003אינו אוכל\u0004 בקדשים באותו יום \u0003ואינו חולק\u0004 באותו יום בקדשים, \u0003ונוטל\u0004 הכהן הגדול \u0003חלק בראש\u0004 מכל קרבן שירצה ואף \u0003מקריב חלק בראש\u0004 בכל קרבן שירצה. \u0003ומשמש בשמנה כלים\u0004 (בגדים) \u0003ופטור על טומאת מקדש וקדשיו, וכל עבודות יום הכפורים אינן כשירות אלא בו.\u0004","\u0003וכולן,\u0004 כל המצוות השייכות בכהן גדול שנמשח בשמן המשחה, \u0003נוהגות\u0004 אף בכהן גדול \u0003מרובה בגדים,\u0004 כגון בימי בית שני שלא היה עוד שמן המשחה, ונתמנה כהן גדול על ידי לבישת שמונה בגדים בלבד, \u0003חוץ מפר הבא על כל המצות\u0004 שהמרובה בבגדים אינו מביא,","\u0003וכולן נוהגות במשוח שעבר,\u0004 כלומר: מי שמילא את מקום הכהן הגדול בהיותו בעל מום וכדומה ולכשעבר המום חזר הכהן הראשון לגדולתו וירד ממנה ממלא מקומו, \u0003חוץ\u0004 מהקרבת \u0003פר יום הכפורים ועשירית האיפה\u0004 בכל יום.","\u0003וכולן אין נוהגות במשוח מלחמה חוץ מחמשה דברים האמורין\u0004 במפורש \u0003בפרשה\u0004 של כהן גדול: שאינו \u0003פורע, ולא פורם, ולא מטמא לקרוביו, ומצווה על הבתולה, ומוזהר על האלמנה, ומחזיר את הרוצח, כדברי ר' יהודה\u0004 במסכת מכות (יא, א), \u0003וחכמים אומרים:\u0004 כהן משוח מלחמה \u0003אינו מחזיר\u0004 את הרוצח. ונמצאנו למדים שתנא זה סבור שיכול להיות במקדש משוח שעבר ושיהיו בו דיני כהונה גדולה, הרי שאינו חושש משום איבה, ובכל זאת מחלק בין כהן גדול ומשוח מלחמה!","ודוחים: אין כאן ראיה, כי מדובר כאן באופן \u0003כי לית ליה\u0004 \u0005[כאשר אין לו]\u0006 \u0003איבה —\u0004 הרי זה \u0003בדכוותיה\u0004 \u0005[בדומה לו],\u0006 שמשוח שעבר הוא בדרגתו של כהן גדול ולכן אינו מקנא בו כל כך, אבל \u0003בדזוטר מיניה אית ליה\u0004 \u0005[במי שהוא קטן ממנו\u0006 כגון משוח מלחמה \u0005יש לו\u0006 איבה\u0005]\u0006 אם ילבש כלבושו.","מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' אבהו וקאמר לה להא שמעתא\u0004 \u0005[ואמר את\u0006 ההלכה \u0005הזו]\u0006 של רב דימי, שבגדים שמשמש בהם כהן גדול, משמש בהם גם כהן משוח מלחמה, \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן\u0004 בפני חכמי ישראל. \u0003אהדרינהו\u0004 \u0005[החזירו]\u0006 \u0003ר' אמי ור' אסי לאפייהו\u0004 \u0005[את פניהם],\u0006 להראות שאין דעתם נוחה מן הדברים. \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שלא כך היה המעשה, אלא \u0003ר' חייא בר אבא\u0004 הוא ש\u0003אמרה, ואהדרינהו\u0004 \u0005[והחזירו]\u0006 \u0003ר' אמי ור' אסי לאפייהו\u0004 \u0005[את פניהם].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על הגירסה האחרונה זו \u0003רב פפא: בשלמא\u0004 \u0005[נניח]\u0006 אם אומר אתה כי \u0003ר' אבהו\u0004 אמר זאת, מובן כי \u0003משום יקרא דבי\u0004 \u0005[כבודו של בית]\u0006 ה\u0003קיסר,\u0004 שר' אבהו היה קרוב למלכות (חגיגה יד, א), לא אמרו לו במפורש שאין דעתם נוחה מדבריו, \u0003אלא לר' חייא בר אבא — נימרו ליה מימר\u0004 \u0005[שיאמרו לו\u0006 במפורש\u0005]\u0006 כי \u0003לא אמר ר' יוחנן הכי\u0004 \u0005[כך],\u0006 ואם כן אין גירסה זו מסתברת.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין, אמר: נשאל איתמר\u0004 \u0005[נאמר]\u0006 שלא אמרו שכהן משוח מלחמה משמש בשמונה בגדים ככהן גדול, אלא שבשמונת הבגדים בהם משמש הכהן הגדול, שאלת כהן משוח מלחמה באורים ותומים אף היא אינה נעשית אלא בשמונה בגדים הללו. ואכן, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003בגדים שכהן גדול משמש בהן — כהן משוח מלחמה נשאל בהן.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כיצד שואלין\u0004 באורים ותומים? \u0003השואל\u0004 (כגון: מלך או אב בית דין) עומד \u0003ופניו כלפי\u0004 הכהן ה\u0003נשאל, והנשאל\u0004 עומד ו\u0003פניו כלפי שכינה\u0004, כלומר: כלפי האורים ותומים שבתוכם מצוי שם המפורש.","\u0003השואל אומר\u0004 בשאלתו כגון: \u0003\"ארדף אחרי הגדוד הזה\"\u0004 (שמואל א' ל, ח) \u0003והנשאל\u0004 עונה לו כפי התשובה שקיבל ו\u0003אומר\u0004 כגון: \u0003\"כה אמר ה' עלה והצלח\". ר' יהודה אומר אין צריך לומר\u0004 לשון \u0003\"כה אמר ה'\" אלא\u0004 די במה שיאמר \u0003\"עלה והצלח\".\u0004 כי ברור שהוא אומר בדיוק מה שנאמר לו.","\u0003אין שואלין בקול\u0004 רם, \u0003שנאמר: \"ושאל לו\u0004 במשפט האורים\u0003\"\u0004 (במדבר כז, כא), משמע \"לו\" — לבדו. \u0003ולא מהרהר\u0004 את שאלתו \u0003בלבו\u0004 אלא יוציאנה בשפתיו, \u0003שנאמר: \"ושאל לו\u0004 במשפט האורים \u0003לפני ה'\"\u0004 (במדבר כז, כא) ומיד לאחריו נאמר: \"ועל פיו...\" (במדבר כז, כא). \u0003אלא\u0004 כיצד שואל — \u0003כדרך שאמרה חנה בתפלתה, שנאמר: \"וחנה היא מדברת על לבה\"\u0004 (שמואל א' א, יג), כלומר: דיבור בקול שקט שאין אחר שומעו.","\u0003אין שואלין שני דברים כאחד\u0004 (בבת אחת), אלא ישאל דבר אחד ולאחר שישיבו לו ישאל בשנית. \u0003ואם שאל\u0004 שני דברים כאחד — \u0003אין מחזירין\u0004 לו בתשובה \u0003אלא\u0004 דבר \u0003אחד, ואין מחזירין לו אלא\u0004 על הדבר \u0003הראשון\u0004 ששאל. \u0003שנאמר:\u0004 ששאל דוד שתי שאלות כאחת: \u0003\"היסגרני בעלי קעילה בידו, הירד שאול ויאמר ה' ירד\"\u0004 (שמואל א' כג, יא). ותוהים: \u0003והא אמרת\u0004 ש\u0003אין מחזירין\u0004 לזה השואל שתים כאחת \u0003אלא\u0004 על הדבר ה\u0003ראשון\u0004 ששאל, וכהוכחה לדבר מביא אתה ראיה דווקא ממעשה זה שבו נענה דווקא על שאלתו השניה ולא על הראשונה! ומשיבים: \u0003דוד שאל\u0004"],["\u0003שלא כסדר והחזירו לו כסדר.\u0004 שהיה צריך לשאול תחילה אם ירד שאול, ואחר כך מה יעשו בעלי קעילה. \u0003וכיון שידע ששאל שלא כסדר, חזר ושאל כסדר, שנאמר\u0004 מיד לאחר מכן: \u0003\"היסגרו בעלי קעילה אתי ואת אנשי ביד שאול ויאמר ה' יסגירו\"\u0004 (שמואל א' כג, יב).","\u0003ואם הוצרך הדבר\u0004 לשאול \u0003שנים\u0004 כאחד ואין שהות לשאול אחת ולקבל עבורה תשובה ולאחריה לשאות את השניה — מותר לו לשאול שנים ואף \u0003מחזירין לו שנים, שנאמר: \"וישאל דוד בה' לאמר ארדף אחרי הגדוד הזה האשיגנו ויאמר לו רדף כי השג תשיג והצל תציל\"\u0004 (שמואל א' ל, ח).","ועוד בענין אורים ותומים; \u0003ואף על פי שגזירת נביא חוזרת\u0004 שפעמים שנבואת הנביא לרעה, נאמרת להתראה בלבד ואינה מתקיימת תמיד — \u0003גזירת אורים ותומים אינה חוזרת. שנאמר: \"במשפט האורים\"\u0004 (במדבר כז, כא), לומר, שדבר האורים כפסק דין במשפט.","ועוד: \u0003למה נקרא שמן אורים ותומים? — \"אורים\" שמאירין\u0004 מבארים ומפרשים \u0003את דבריהן, \"תמים\" — שמשלימין את דבריהן,\u0004 שהם מתקיימים תמיד. \u0003ואם תאמר: בגבעת בנימין מפני מה לא השלימו?\u0004 שהרי שאלו פעמים אחדות, ולא נתקיים בידם כפי קיבלו את התשובה?","","הטעם הוא: \u0003הם שלא ביחנו אם לנצח אם להנצח,\u0004 ששאלתם היתה רק אם לעלות למלחמה, ולא שאלו אם ינצחו בה לכשיעלו, \u0003ובאחרונה שביחנו\u0004 ושאלו על כך אמנם \u0003הסכימו\u0004 עמם, \u0003שנאמר: \"ופינחס בן אלעזר בן אהרן עמד לפניו בימים ההם לאמר האוסף עוד לצאת למלחמה עם בני בנימן אחי אם אחדל ויאמר ה' עלו כי מחר אתננו בידך\"\u0004 (שופטים כ, כח), וכן היה.","ושואלים: \u0003כיצד נעשית,\u0004 כלומר: כיצד נענה הכהן באורים ותומים? \u0003ר' יוחנן אומר?\u0004 אותיות התשובה \u0003בולטות\u0004 מבין שאר האותיות הכתובות בחושן והוא מצרפן בעצמו. \u0003ריש לקיש אומר: מצטרפות\u0004 האותיות, ומתחברות זו עם זו.","ומקשים: וכיצד אפשר לקבל תשובה לכל שאלה, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא כתיב בהו\u0004 \u0005[נאמר בהם]\u0006 בין שמות השבטים החקוקים על אבני החושן, האות \u0003\"צד\"י\". אמר רב שמואל בר יצחק:\u0004 בחושן המשפט גם \u0003\"אברהם יצחק ויעקב\" כתיב\u0004 \u0005[נאמר]\u0006 \u0003שם.\u0004 ומקשים עוד: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא כתיב\u0004 \u0005[נאמר]\u0006 בחושן האות \u0003\"טי\"ת\",\u0004 שאינו לא בשמות האבות ולא בשמות השבטים! \u0003אמר רב אחא בר יעקב: \"שבטי ישורון\" כתיב\u0004 \u0005[כתוב]\u0006 \u0003שם.\u0004 ועל ידי כך יש סדר אלף בית שלם.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003כל כהן שאינו מדבר ברוח הקודש ושכינה שורה עליו — אין שואלין בו\u0004 באורים ותומים. \u0003שהרי שאל צדוק\u0004 באורים ותומים \u0003ועלתה לו\u0004 תשובה, שאל \u0003אביתר ולא עלתה לו\u0004 ונסתלק כתוצאה מכך מן הכהונה, \u0003שנאמר: \"ויעל אביתר עד תם כל העם\"\u0004 (שמואל ב' טו, כד), משמע שהעיקר הוא גילוי רוח הקודש של הכהן!","ומשיבים: \u0003סיועי הוה מסייע בהדייהו\u0004 \u0005[מסייע\u0006 היה הכהן ברוח הקודש \u0005עמהם,\u0006 עם הנגלה באורים ותומים\u0005],\u0006 אבל היה נזקק לאורים ותומים, ולא היתה זו נבואה לעצמה. שנינו במשנה \u0003שאין שואלין\u0004 באורים \u0003אלא למלך\u0004 ולאב בית דין וכן למי שהציבור צריך לו. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלו]?\u0006 \u0003אמר ר' אבהו:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ולפני אלעזר הכהן יעמד ושאל לו במשפט האורים\u0004 לפני ה' על פיו יצאו ועל פיו יבואו הוא וכל בני ישראל אתו וכל העדה\u0003\"\u0004 (במדבר כז, כא). \u0003\"הוא\" — זה מלך,\u0004 שהרי יהושע כמלך ישראל הוא. \u0003\"וכל בני ישראל אתו\"\u0004 (במדבר כז, כא) — \u0003זה משוח מלחמה\u0004 שכל ישראל יוצאים למלחמה אחריו כדבריו. \u0003\"וכל העדה\"\u0004 (במדבר כז, כא) — \u0003זו סנהדרין\u0004 שהם ראשי עדת ישראל, ואם כן רמוזים כאן כל בעלי התפקיד שנמנו במשנה.","","","\u0003יום הכפורים\u0004 שנצטוינו בתורה להתענות בו, \u0003אסור\u0004 משום כך \u0003באכילה ובשתיה וברחיצה ובסיכה\u0004 (משיחת הגוף בשמן) \u0003ובנעילת הסנדל, ובתשמיש המטה.\u0004 אבל \u0003המלך\u0004 מפני כבודו וכן \u0003הכלה\u0004 כל שלושים יום לנישואיה, שצריכה לנוי מיוחד כדי להתחבב על בעלה — \u0003ירחצו את פניהם\u0004 ביום הכיפורים. \u0003והחיה\u0004 (היולדת) המצטערת — \u0003תנעול את הסנדל,\u0004 אלו \u0003דברי ר' אליעזר. וחכמים אוסרין.\u0004","ומפרטים: \u0003האוכל\u0004 ביום הכיפורים \u0003ככותבת\u0004 (פרי התמר) \u0003הגסה\u0004 (הגדולה), \u0003כמוה וכגרעינתה,\u0004 כלומר: לא כשיעור המאכל שיש בה בתמר בלי גרעינו, אלא כדי נפח של תמר וגרעינו. \u0003והשותה מלא לוגמיו\u0004 (כדי שימלא פיו) — הרי זה \u0003חייב\u0004 מן התורה, שביטל מצות עינוי ביום הכיפורים. \u0003כל האוכלים\u0004 שאדם אוכל \u0003מצטרפין\u0004 לכדי שיעור זה של \u0003כותבת, וכל המשקין מצטרפין\u0004 לשיעור של \u0003מלא לוגמיו.\u0004 אולם \u0003האוכל ושותה\u0004 כאחד \u0003אין מצטרפין\u0004 לשיעור אחד, אלא אוכל לחוד ושתיה לחוד.","על לשון המשנה שיום הכיפורים \"אסור באכילה ובשתיה\", תוהים: מדוע נקטה המשנה בלשון \u0003\"אסור\"\u0004 שמשמעה שיש רק עבירה בדבר?! והרי \u0003ענוש כרת הוא\u0004 אם אוכל, והיה ראוי לכתוב \"חייב\"! \u0003אמר ר' אילא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' ירמיה: לא נצרכה\u0004 דרך ביטוי זו \u0003אלא לחצי שיעור.\u0004 כלומר: אף על פי שלא אכל אדם את מלוא השיעור שחייב עליו כרת אלא פחות מכן — מכל מקום יש בכך משום איסור, ולכן השתמשה המשנה בלשון \"אסור\".","ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003למאן דאמר\u0004 \u0005[\u0006לשיטת \u0005מי שאמר]\u0006 כי \u0003חצי שיעור\u0004 אף הוא \u0003אסור מן התורה,\u0004 אלא שלא חייבה עליו התורה עונש — הרי לשון זו ראויה, \u0003אלא למאן דאמר\u0004 \u0005[\u0006לשיטת \u0005מי שאמר]\u0006 כי \u0003חצי שיעור מותר מן התורה,\u0004 ולא נאסר לאכול פחות מכשיעור אלא על ידי חכמים, אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 לשיטתו?","\u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו אמוראים בשאלה מה דינו של \u0003חצי שיעור\u0004 בדבר איסור, \u0003ר' יוחנן אמר: אסור\u0004 הוא \u0003מן התורה,\u0004 שהתורה אסרה אכילת איסור בכל שהוא, \u0003ריש לקיש אמר: מותר מן התורה.\u0004 ומעתה, \u0003הניחא\u0004 \u0005[\u0006תירוץ \u0005זה\u0006 שאמרנו \u0005נוח]\u0006 איפוא לשיטת \u0003ר' יוחנן. אלא\u0004 לשיטת \u0003ריש לקיש מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003מודה ריש לקיש שאסור\u0004 חצי שיעור לפחות \u0003מדרבנן.\u0004 ואם כן, אף לפי שיטתו אפשר לומר שיום הכיפורים אסור באכילה ובשתיה לגבי חצי שיעור מדברי חכמים.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שלדעת ריש לקיש יש בחצי שיעור איסור מדברי חכמים, \u0003לא ניחייב עליה\u0004 \u0005[יתחייב עליו]\u0006 \u0003קרבן שבועה, אלמא תנן,\u0004 \u0005[ומפני מה שנינו\u0006 במשנה\u0005]\u0006 וביארנו דבר זה בדרך אחרת; ששנינו: מי שאמר בשבועתו: \u0003\"שבועה שלא אוכל\" ואכל נבילות וטריפות שקצים ורמשים — חייב\u0004 משום עובר על השבועה. \u0003ור' שמעון פוטר.\u0004","\u0003והוינן בה\u0004 \u0005[והיינו עוסקים\u0006 ומתקשים בבעיה \u0005זו]:\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 יהא \u0003חייב\u0004 משום שבועה? הלא \u0003מושבע ועומד מהר סיני הוא,\u0004 ככל ישראל, שלא לאכול דברים אלה, ולפי ההלכה אין שבועה חלה על שבועה, ושבועתו השניה שנשבע כאילו לחזק שבועה ראשונה לא חלה כלל, ואם כן מדוע יהא חייב על הפרתה? \u0003רב ושמואל ור' יוחנן דאמרי\u0004 \u0005[שאמרו]\u0006 בעניין זה: שכאן מדובר \u0003בכולל דברים המותרים עם דברים האסורין.\u0004 כלומר: אילו היה נשבע רק שלא יאכל נבילות וטריפות ואכלן — ודאי לא היה חייב משום השבועה שהרי כבר מושבע ועומד הוא, אבל כיון שנשבע שלא יאכל כלל, כיון ששבועתו חלה גם על דברים שמותר לאכלם, חלה איפוא השבועה על כל דבר, ולכן חייב אם עובר עליה.","\u0003וריש לקיש אמר: אי אתה מוצא\u0004 הסבר למשנה זו \u0003אלא במפרש\u0004 ואומר שלא יאכל \u0003חצי שיעור ואליבא דרבנן\u0004 \u0005[ועל פי שיטת חכמים]\u0006 שהנשבע שלא יאכל, אסר עצמו רק בכשיעור אכילה, ואם אוכל חצי שיעור אין בו איסור ולכן צריך לפרש שנשבע גם על חצי שיעור, או בנשבע \u0003סתם\u0004 בלא לפרש חצי שיעור,"]]};
